function factionRankGateNodes(factionId) {
  return [...new Set([...FACTION_RANK_GATE_COMMON_NODES, ...(FACTION_RANK_GATE_NODES[Number(factionId)] || [])])];
}

function sqlTextArray(values) {
  return `array[${(values || []).map((value) => sqlString(value)).join(", ")}]::text[]`;
}

async function progressionSkillReputationScan(actorIds) {
  const cleanActorIds = [...new Set((actorIds || []).map((value) => Number(value)).filter((value) => Number.isSafeInteger(value) && value > 0))];
  if (!cleanActorIds.length) {
    return {
      specializationTracks: [],
      factionReputation: [],
      currentFactions: [],
      factions: [],
      specializationStatus: "unsupported: no actor ids available",
      factionReputationStatus: "unsupported: no actor ids available"
    };
  }
  const values = sqlValuesList(cleanActorIds);
  const sql = `
    with candidates(actor_id) as (values ${values})
    select 'track', st.player_id::text, st.track_type::text, st.xp_amount::text, st.level::text
    from dune.specialization_tracks st
    join candidates c on c.actor_id = st.player_id
    order by st.player_id, st.track_type;

    with candidates(actor_id) as (values ${values})
    select 'reputation', pfr.actor_id::text, pfr.faction_id::text, coalesce(f.name, ''), pfr.reputation_amount::text
    from dune.player_faction_reputation pfr
    join candidates c on c.actor_id = pfr.actor_id
    left join dune.factions f on f.id = pfr.faction_id
    order by pfr.actor_id, pfr.faction_id;

    with candidates(actor_id) as (values ${values})
    select 'current_faction', pf.actor_id::text, pf.faction_id::text, coalesce(f.name, ''), coalesce(pf.utc_time_faction_change::text, '')
    from dune.player_faction pf
    join candidates c on c.actor_id = pf.actor_id
    left join dune.factions f on f.id = pf.faction_id
    order by pf.actor_id;

    select 'faction', id::text, name, '', '' from dune.factions order by id;
  `;
  const output = await dbQuery(sql, 7000);
  const specializationTracks = [];
  const factionReputation = [];
  const currentFactions = [];
  const factions = [];
  for (const line of output.split(/\r?\n/).filter(Boolean)) {
    const parts = line.split("\t");
    if (parts[0] === "track") {
      specializationTracks.push({ player_id: parts[1] || "", track_type: parts[2] || "", xp_amount: parts[3] || "0", level: parts[4] || "0" });
    } else if (parts[0] === "reputation") {
      factionReputation.push({ actor_id: parts[1] || "", faction_id: parts[2] || "", faction_name: parts[3] || "", reputation_amount: parts[4] || "0" });
    } else if (parts[0] === "current_faction") {
      currentFactions.push({ actor_id: parts[1] || "", faction_id: parts[2] || "", faction_name: parts[3] || "", changed_at: parts[4] || "" });
    } else if (parts[0] === "faction") {
      factions.push({ id: parts[1] || "", name: parts[2] || "" });
    }
  }
  return {
    specializationTracks,
    factionReputation,
    currentFactions,
    factions,
    specializationStatus: specializationTracks.length ? "loaded" : "empty",
    factionReputationStatus: factionReputation.length ? "loaded" : "empty"
  };
}

function fieldFoundStatus(value, paths) {
  return value === "" || value == null
    ? `unsupported: field not found in scanned component JSON${paths ? `; paths checked ${paths}` : ""}`
    : "detected";
}

function progressionDecodeJson(value) {
  try { return JSON.parse(value); } catch { return value; }
}

async function progressionCharacterComponentScan(actorIds) {
  if (!actorIds.length) {
    return {
      values: null,
      target: null,
      links: [],
      componentNames: [],
      fieldStatus: {
        TotalXPEarned: "unsupported: no actor ids available",
        TotalSkillPoints: "unsupported: no actor ids available",
        UnspentSkillPoints: "unsupported: no actor ids available"
      }
    };
  }
  const sql = `
    with recursive
    candidates(actor_id) as (values ${sqlValuesList(actorIds)}),
    links as (
      select c.actor_id, afe.entity_id, coalesce(afe.slot_name, '') as slot_name, fe.components
      from candidates c
      left join dune.actor_fgl_entities afe on afe.actor_id = c.actor_id
      left join dune.fgl_entities fe on fe.entity_id = afe.entity_id
    ),
    walk(actor_id, entity_id, slot_name, path, value) as (
      select actor_id, entity_id, slot_name, array[]::text[], components
      from links
      where components is not null
      union all
      select w.actor_id, w.entity_id, w.slot_name, w.path || child.key, child.value
      from walk w
      cross join lateral (
        select e.key, e.value
        from jsonb_each(case when jsonb_typeof(w.value) = 'object' then w.value else '{}'::jsonb end) e
        union all
        select (a.ordinality - 1)::text as key, a.value
        from jsonb_array_elements(case when jsonb_typeof(w.value) = 'array' then w.value else '[]'::jsonb end) with ordinality a(value, ordinality)
      ) child
      where jsonb_typeof(w.value) in ('object', 'array')
    )
    select 'link', actor_id::text, coalesce(entity_id::text, ''), slot_name, '', ''
    from links
    union all
    select distinct 'component', '', '', '', path[1], ''
    from walk
    where array_length(path, 1) = 1
    union all
    select 'field', actor_id::text, coalesce(entity_id::text, ''), slot_name, array_to_string(path, '.'), value #>> '{}'
    from walk
    where path[array_length(path, 1)] in ('TotalXPEarned', 'TotalSkillPoints', 'UnspentSkillPoints')
    order by 1, 2, 3, 4, 5;
  `;
  const rows = parseDbRows(await dbQuery(sql, 7000), ["kind", "actor_id", "entity_id", "slot_name", "path", "value"]);
  const links = rows.filter((row) => row.kind === "link").map((row) => ({
    actor_id: row.actor_id,
    entity_id: row.entity_id,
    slot_name: row.slot_name,
    found: Boolean(row.entity_id)
  }));
  const componentNames = [...new Set(rows.filter((row) => row.kind === "component").map((row) => row.path).filter(Boolean))];
  const fields = rows.filter((row) => row.kind === "field");
  const targetOf = (name) => {
    const preferred = fields.find((row) => row.path.endsWith(`.${name}`) && /DuneCharacter/i.test(row.slot_name || ""));
    return preferred || fields.find((row) => row.path.endsWith(`.${name}`)) || null;
  };
  const totalXpTarget = targetOf("TotalXPEarned");
  const totalSkillTarget = targetOf("TotalSkillPoints");
  const unspentTarget = targetOf("UnspentSkillPoints");
  const pathOf = (name) => fields.filter((row) => row.path.endsWith(`.${name}`)).map((row) => `${row.actor_id}/${row.entity_id}/${row.slot_name}:${row.path}`).join("; ");
  const values = {
    TotalXPEarned: totalXpTarget?.value || "",
    TotalSkillPoints: totalSkillTarget?.value || "",
    UnspentSkillPoints: unspentTarget?.value || ""
  };
  return {
    values,
    target: {
      actor_id: totalXpTarget?.actor_id || totalSkillTarget?.actor_id || unspentTarget?.actor_id || "",
      entity_id: totalXpTarget?.entity_id || totalSkillTarget?.entity_id || unspentTarget?.entity_id || "",
      slot_name: totalXpTarget?.slot_name || totalSkillTarget?.slot_name || unspentTarget?.slot_name || "",
      fields: {
        TotalXPEarned: totalXpTarget ? { path: totalXpTarget.path, value: totalXpTarget.value } : null,
        TotalSkillPoints: totalSkillTarget ? { path: totalSkillTarget.path, value: totalSkillTarget.value } : null,
        UnspentSkillPoints: unspentTarget ? { path: unspentTarget.path, value: unspentTarget.value } : null
      }
    },
    links,
    componentNames,
    fieldStatus: {
      TotalXPEarned: fieldFoundStatus(values.TotalXPEarned, pathOf("TotalXPEarned")),
      TotalSkillPoints: fieldFoundStatus(values.TotalSkillPoints, pathOf("TotalSkillPoints")),
      UnspentSkillPoints: fieldFoundStatus(values.UnspentSkillPoints, pathOf("UnspentSkillPoints"))
    }
  };
}

async function progressionTechKnowledgeScan(actorIds) {
  if (!actorIds.length) {
    return { values: null, componentNames: [], target: null, fieldStatus: { m_TechKnowledgePoints: "unsupported: no actor ids available" } };
  }
  const sql = `
    with recursive
    candidates(actor_id) as (values ${sqlValuesList(actorIds)}),
    actors as (
      select c.actor_id, a.properties
      from candidates c
      left join dune.actors a on a.id = c.actor_id
    ),
    walk(actor_id, path, value) as (
      select actor_id, array[]::text[], properties
      from actors
      where properties is not null
      union all
      select w.actor_id, w.path || child.key, child.value
      from walk w
      cross join lateral (
        select e.key, e.value
        from jsonb_each(case when jsonb_typeof(w.value) = 'object' then w.value else '{}'::jsonb end) e
        union all
        select (a.ordinality - 1)::text as key, a.value
        from jsonb_array_elements(case when jsonb_typeof(w.value) = 'array' then w.value else '[]'::jsonb end) with ordinality a(value, ordinality)
      ) child
      where jsonb_typeof(w.value) in ('object', 'array')
        and coalesce(array_length(w.path, 1), 0) < 16
    )
    select distinct 'component', actor_id::text, path[1], ''
    from walk
    where array_length(path, 1) = 1
    union all
    select 'field', actor_id::text, array_to_string(path, '.'), value #>> '{}'
    from walk
    where path[array_length(path, 1)] = 'm_TechKnowledgePoints'
    order by 1, 2, 3;
  `;
  const rows = parseDbRows(await dbQuery(sql, 7000), ["kind", "actor_id", "path", "value"]);
  const componentNames = [...new Set(rows.filter((row) => row.kind === "component").map((row) => row.path).filter(Boolean))];
  const fields = rows.filter((row) => row.kind === "field");
  const preferred = fields.find((row) => String(row.actor_id) === String(actorIds[0])) || fields[0];
  const value = preferred?.value || "";
  const paths = fields.map((row) => `${row.actor_id}:${row.path}`).join("; ");
  return {
    values: { m_TechKnowledgePoints: value },
    componentNames,
    target: preferred ? { actor_id: preferred.actor_id, path: preferred.path, value } : null,
    fieldStatus: { m_TechKnowledgePoints: fieldFoundStatus(value, paths) }
  };
}

const progressionPreviews = new Map();
const PROGRESSION_CONFIRM_TEXT = "APPLY PROGRESSION";
const landsraadWeeklyPatchPreviews = new Map();
const LANDSRAAD_WEEKLY_CONFIRM_TEXT = "APPLY LANDSRAAD";
const landsraadTierPreviews = new Map();
const LANDSRAAD_TIER_CONFIRM_TEXT = "APPLY LANDSRAAD TIERS";
const LANDSRAAD_TIER_COUNT = 5;
const CHARACTER_PROGRESSION_LIMITS = {
  TotalXPEarned: 999999999,
  TotalSkillPoints: 999,
  UnspentSkillPoints: 999,
  m_TechKnowledgePoints: 999999999
};

function clampNumber(value, name, min, max = Number.MAX_SAFE_INTEGER) {
  const number = Number(value);
  if (!Number.isFinite(number)) throw new Error(`${name} must be a number.`);
  return Math.max(min, Math.min(max, number));
}

function progressionInteger(value, name, max = Number.MAX_SAFE_INTEGER) {
  const text = String(value ?? "").trim();
  if (!/^\d+$/.test(text)) throw new Error(`${name} must be a non-negative integer.`);
  const number = Number(text);
  if (!Number.isSafeInteger(number)) throw new Error(`${name} must be a safe integer.`);
  if (number > max) throw new Error(`${name} must be ${max} or lower.`);
  return number;
}

function progressionAudit(action, payload) {
  const entry = { timestamp: new Date().toISOString(), action, ...payload };
  fs.mkdirSync(path.dirname(PROGRESSION_AUDIT_LOG), { recursive: true });
  fs.appendFileSync(PROGRESSION_AUDIT_LOG, JSON.stringify(entry) + "\n", "utf8");
}

function progressionBackupPath(playerId, action, id) {
  fs.mkdirSync(PROGRESSION_BACKUP_DIR, { recursive: true });
  const safeAction = String(action || "progression").replace(/[^a-z0-9_-]/gi, "_");
  const safePlayer = String(playerId || "player").replace(/[^a-z0-9_-]/gi, "_");
  return path.join(PROGRESSION_BACKUP_DIR, `${new Date().toISOString().replace(/[:.]/g, "-")}-${safePlayer}-${safeAction}-${id}.json`);
}

async function landsraadWeeklyPatchInspect() {
  const output = await dbQuery(`
    select table_name, column_name
    from information_schema.columns
    where table_schema = 'dune'
      and table_name = 'landsraad_tasks'
      and column_name in ('id', 'goal_amount')
    order by table_name, column_name;
  `, 12000);
  const columns = new Set(parseDbRows(output, ["table", "column"]).map((row) => row.column));
  const supported = columns.has("id") && columns.has("goal_amount");
  return {
    ok: supported,
    schema: "dune",
    table: "landsraad_tasks",
    columns: [...columns],
    status: supported ? "detected" : "missing",
    reason: supported ? "" : "dune.landsraad_tasks with id and goal_amount columns was not detected."
  };
}

async function landsraadWeeklyPatchRows(limit = 500) {
  const safeLimit = requireInteger(limit, "limit", 1, 1000);
  const output = await dbQuery(`
    select id::text, goal_amount::text
    from dune.landsraad_tasks
    order by id
    limit ${safeLimit};
  `, 15000);
  return parseDbRows(output, ["id", "goal_amount"]);
}

async function landsraadWeeklyPatchPreview(payload) {
  try {
    const targetGoalAmount = progressionInteger(payload?.targetGoalAmount ?? 7000, "Target goal amount", 1000000);
    const inspect = await landsraadWeeklyPatchInspect();
    if (!inspect.ok) return { ok: false, status: "unsupported", inspect, error: inspect.reason };
    const rows = await landsraadWeeklyPatchRows();
    if (!rows.length) throw new Error("No rows were found in dune.landsraad_tasks.");
    const previewId = crypto.randomBytes(16).toString("hex");
    const oldValues = { rows };
    const changedRows = rows.filter((row) => String(row.goal_amount) !== String(targetGoalAmount));
    const newValues = {
      targetGoalAmount,
      rows: rows.map((row) => ({ id: row.id, goal_amount: targetGoalAmount })),
      changedRowCount: changedRows.length,
      totalRowCount: rows.length
    };
    const backupPath = progressionBackupPath("landsraad", "weekly_rewards", previewId);
    fs.writeFileSync(backupPath, JSON.stringify({ createdAt: new Date().toISOString(), action: "landsraad_weekly_rewards", oldValues, newValues, source: "landsraad-weekly-preview", readOnlyBackup: true }, null, 2), "utf8");
    const preview = {
      ok: true,
      status: "preview",
      previewId,
      action: "landsraad_weekly_rewards",
      backupPath,
      auditLogPath: PROGRESSION_AUDIT_LOG,
      inspect,
      oldValues,
      newValues,
      sqlPreview: `UPDATE dune.landsraad_tasks SET goal_amount = ${targetGoalAmount} WHERE goal_amount IS DISTINCT FROM ${targetGoalAmount};`,
      warning: `This live database patch changes current weekly Landsraad task goal_amount rows. Type ${LANDSRAAD_WEEKLY_CONFIRM_TEXT} before applying.`
    };
    landsraadWeeklyPatchPreviews.set(previewId, { ...preview, createdAt: Date.now() });
    progressionAudit("landsraad_weekly_preview_created", { oldValues, newValues, backupFilePath: backupPath });
    return preview;
  } catch (error) {
    return { ok: false, status: "error", error: error.message, auditLogPath: PROGRESSION_AUDIT_LOG };
  }
}

async function landsraadWeeklyPatchApply(payload) {
  let preview = null;
  try {
    const configValue = loadConfig();
    if (!configValue.progressionEditingEnabled) throw new Error("Enable Progression Editing is OFF.");
    const previewId = String(payload?.previewId || "").trim();
    preview = landsraadWeeklyPatchPreviews.get(previewId);
    if (!preview) throw new Error("Generate Preview + Backup first or refresh an expired preview.");
    if (payload?.confirmText !== LANDSRAAD_WEEKLY_CONFIRM_TEXT) throw new Error(`Type ${LANDSRAAD_WEEKLY_CONFIRM_TEXT} before applying.`);
    if (Date.now() - preview.createdAt > 1000 * 60 * 30) throw new Error("Preview expired. Generate a new preview.");
    if (!fs.existsSync(preview.backupPath)) throw new Error("Matching backup file is missing.");
    const inspect = await landsraadWeeklyPatchInspect();
    if (!inspect.ok) throw new Error(inspect.reason);
    const targetGoalAmount = requireInteger(preview.newValues?.targetGoalAmount, "targetGoalAmount", 0, 1000000);
    const output = await dbQuery(`
      with before_rows as (
        select id, goal_amount as old_goal_amount
        from dune.landsraad_tasks
      ),
      updated as (
        update dune.landsraad_tasks target
        set goal_amount = ${targetGoalAmount}
        from before_rows before
        where target.id = before.id
          and target.goal_amount is distinct from ${targetGoalAmount}
        returning target.id::text, before.old_goal_amount::text, target.goal_amount::text
      )
      select id, old_goal_amount, goal_amount
      from updated
      order by id;
    `, 30000);
    const changedRows = parseDbRows(output, ["id", "old_goal_amount", "goal_amount"]);
    const readBackRows = await landsraadWeeklyPatchRows(1000);
    const verified = readBackRows.length > 0 && readBackRows.every((row) => String(row.goal_amount) === String(targetGoalAmount));
    const debug = {
      changedRows,
      readBackRows,
      expectedGoalAmount: String(targetGoalAmount),
      changedRowCount: changedRows.length,
      totalRowCount: readBackRows.length
    };
    landsraadWeeklyPatchPreviews.delete(previewId);
    if (!verified) {
      progressionAudit("landsraad_weekly_apply_verification_failed", { oldValues: preview.oldValues, newValues: preview.newValues, backupFilePath: preview.backupPath, success: false, debug });
      return { ok: false, status: "verification_failed", action: preview.action, oldValues: preview.oldValues, newValues: preview.newValues, backupPath: preview.backupPath, auditLogPath: PROGRESSION_AUDIT_LOG, debug, warning: "Database write completed, but Landsraad task read-back did not match the requested goal amount." };
    }
    progressionAudit("landsraad_weekly_apply_success", { oldValues: preview.oldValues, newValues: preview.newValues, backupFilePath: preview.backupPath, success: true, debug });
    return { ok: true, status: "applied", action: preview.action, oldValues: preview.oldValues, newValues: preview.newValues, backupPath: preview.backupPath, auditLogPath: PROGRESSION_AUDIT_LOG, debug };
  } catch (error) {
    if (preview) {
      try { progressionAudit("landsraad_weekly_apply_failure", { oldValues: preview.oldValues, newValues: preview.newValues, backupFilePath: preview.backupPath, success: false, error: error.message }); } catch {}
    }
    return { ok: false, status: "error", error: error.message, backupPath: preview?.backupPath || "", auditLogPath: PROGRESSION_AUDIT_LOG };
  }
}

function sqlTextArrayPath(pathValue) {
  const parts = Array.isArray(pathValue)
    ? pathValue.map((part) => String(part || "").trim()).filter(Boolean)
    : String(pathValue || "").split(".").filter(Boolean);
  if (!parts.length) throw new Error("Detected JSON path is empty.");
  return `ARRAY[${parts.map((part) => sqlString(part)).join(", ")}]`;
}

function requireSqlIntegerLiteral(value, name) {
  const text = String(value ?? "").trim();
  if (!/^-?\d+$/.test(text)) throw new Error(`${name} must be an integer.`);
  return text;
}

async function progressionPlayerComponentSupport(actorId) {
  const output = await dbQuery(`
    select
      coalesce((properties ? 'FactionPlayerComponent')::text, 'false'),
      coalesce((properties ? 'TechKnowledgePlayerComponent')::text, 'false')
    from dune.actors
    where id = ${actorId}
    limit 1
  `, 20000);
  const [faction = "false", tech = "false"] = String(output || "").split("\t");
  return { factionComponent: /^true$/i.test(faction), techKnowledgeComponent: /^true$/i.test(tech) };
}

async function playerHydrationForPawnActor(pawnActorId) {
  const idText = String(pawnActorId || "").trim();
  if (!/^\d+$/.test(idText)) {
    return extractHydrationFromGasAttributes(null, { pawnActorId: idText });
  }
  try {
    const output = await dbQuery(`
      select coalesce(gas_attributes::text, '')
      from dune.actors
      where id = ${requireInteger(idText, "player_pawn_id", 1)}
      limit 1
    `, 8000);
    return extractHydrationFromGasAttributes(output || null, { pawnActorId: idText });
  } catch (error) {
    const hydration = extractHydrationFromGasAttributes(null, { pawnActorId: idText });
    hydration.error = error.message;
    return hydration;
  }
}

async function attachHydrationToPlayers(players) {
  const list = Array.isArray(players) ? players : [];
  await Promise.all(list.map(async (player) => {
    player.hydration = await playerHydrationForPawnActor(player.player_pawn_id);
  }));
  return list;
}

async function progressionPreview(payload) {
  const timer = progressionPhaseTimer("progression/preview");
  let action = "";
  const fail = (error) => {
    const timedOut = /timed out|timeout/i.test(error.message);
    const failedStep = timer.currentStep;
    timer.finish({ status: timedOut ? "timeout" : "error", action, step: failedStep, error: error.message });
    return {
      ok: false,
      status: timedOut ? "timeout" : "error",
      step: failedStep,
      timings: timer.timings,
      error: error.message
    };
  };
  try {
    await timer.step("config_load", async () => loadConfig());
    await timer.step("safety_check", async () => {});
    action = await timer.step("request_validate", async () => {
      const requestedAction = String(payload?.action || "").trim();
      if (!["specialization_xp", "faction_reputation", "skill_unlocks", "character_xp_skill_points"].includes(requestedAction)) {
        throw new Error("Unsupported progression action.");
      }
      return requestedAction;
    });

    if (action !== "character_xp_skill_points") {
      const query = String(payload?.query || payload?.playerId || "").trim();
      const playerData = await timer.step("selected_target_validate", () => withProgressionStepTimeout(progressionPlayerLookup(query), 20000, "selected_target_validate"));
      if (!playerData.ok) return progressionUnsupported(playerData.reason || "Player lookup failed.");
      const inspect = await timer.step("safety_check", () => withProgressionStepTimeout(progressionInspector(), 10000, "safety_check"));
      const actorId = requireInteger(playerData.player.actor_id, "actor_id", 1);
      const componentSupport = await progressionPlayerComponentSupport(actorId).catch(() => ({ factionComponent: false, techKnowledgeComponent: false }));
      const previewId = crypto.randomBytes(16).toString("hex");
      let oldValues = {};
      let newValues = {};
      let sqlPreview = "";
      if (action === "skill_unlocks") {
        const catalog = loadDuneSkillsCatalog();
        if (!catalog.ok || !catalog.skills.length) return progressionUnsupported(catalog.report?.message || catalog.report?.error || "Bundled skill catalog is unavailable.");
        const requestedSkillIds = [...new Set((Array.isArray(payload?.skillIds) ? payload.skillIds : []).map((value) => String(value || "").trim()).filter(Boolean))];
        if (!requestedSkillIds.length) throw new Error("Choose at least one skill to unlock.");
        if (requestedSkillIds.length > 40) throw new Error("Choose 40 skills or fewer per preview.");
        const byId = new Map(catalog.skills.map((skill) => [skill.id, skill]));
        const selectedSkills = requestedSkillIds.map((id) => byId.get(id)).filter(Boolean);
        const missingSkillIds = requestedSkillIds.filter((id) => !byId.has(id));
        if (!selectedSkills.length) throw new Error("None of the selected skill ids exist in the bundled skill catalog.");
        const storageScan = await timer.step("skill_unlock_storage_scan", () => withProgressionStepTimeout(progressionSkillUnlockStorageScan(playerData, selectedSkills), 22000, "skill_unlock_storage_scan"));
        oldValues = {
          unlockedSkills: "not read",
          storageStatus: storageScan.status,
          candidateCount: storageScan.candidateCount || 0,
          matchedSkillRefs: storageScan.matchedSkillRefs || []
        };
        newValues = {
          selectedSkillIds: selectedSkills.map((skill) => skill.id),
          skills: selectedSkills.map((skill) => ({
            id: skill.id,
            tag: skill.tag,
            name: skill.name,
            tree: skill.tree,
            type: skill.type,
            maxLevel: skill.maxLevel,
            costPerLevel: skill.costPerLevel
          })),
          missingSkillIds,
          storageScan
        };
        sqlPreview = [
          "Skill unlock preview only.",
          "The app found the game skill catalog and your selected skills, then scanned this player's actor/FGL JSON for skill unlock storage.",
          "Live skill unlock writes are blocked until a verified player skill storage adapter is detected.",
          `Storage scan: ${storageScan.status}. ${storageScan.reason || ""}`
        ].join("\n");
      } else if (action === "specialization_xp") {
        if (inspect.supports?.specializationXp?.status !== "detected") return progressionUnsupported("Specialization XP schema/function support was not detected.", inspect);
        if (String(playerData.player?.online_status || "").toLowerCase().includes("online")) throw new Error("Specialization editing requires the player to be offline.");
        const track = String(payload?.trackType || "").trim();
        if (!track) throw new Error("trackType is required.");
        const xp = Math.round(clampNumber(payload?.xpAmount, "xpAmount", 0, 44182));
        const level = clampNumber(payload?.level, "level", 0, 100);
        const current = (playerData.specializationTracks || []).find((row) => String(row.track_type).toLowerCase() === track.toLowerCase()) || null;
        const specializationPlayerId = requireInteger(current?.player_id || playerData.player?.player_controller_id, "specialization_player_id", 1);
        oldValues = current || { player_id: String(specializationPlayerId), track_type: track, xp_amount: "0", level: "0", missing: true };
        newValues = { player_id: specializationPlayerId, track_type: track, xp_amount: xp, level };
        sqlPreview = `SELECT dune.set_specialization_xp_and_level(${specializationPlayerId}, ${sqlString(track)}::dune.specializationtracktype, ${xp}, ${level});`;
      } else if (action === "faction_reputation") {
        if (inspect.supports?.factionReputation?.status !== "detected") return progressionUnsupported("Faction reputation schema/function support was not detected.", inspect);
        if (!componentSupport.factionComponent) return progressionUnsupported("FactionPlayerComponent cache sync support was not detected for this player; refusing live reputation write.", inspect);
        const factionId = requireInteger(payload?.factionId, "factionId", 1, 32767);
        const reputationAmount = Math.round(clampNumber(payload?.reputationAmount, "reputationAmount", 0, 12474));
        const targetActorIds = [...new Set([
          playerData.player?.actor_id,
          playerData.player?.player_id,
          playerData.player?.player_controller_id,
          playerData.player?.player_pawn_id,
          ...(playerData.factionReputation || []).filter((row) => String(row.faction_id) === String(factionId)).map((row) => row.actor_id),
          ...(playerData.currentFactions || []).filter((row) => String(row.faction_id) === String(factionId)).map((row) => row.actor_id)
        ].map((value) => Number(value)).filter((value) => Number.isSafeInteger(value) && value > 0))];
        const currentRows = (playerData.factionReputation || []).filter((row) => String(row.faction_id) === String(factionId));
        const currentFactionRows = (playerData.currentFactions || []).filter((row) => targetActorIds.includes(Number(row.actor_id)));
        const rankGateNodes = factionRankGateNodes(factionId);
        let currentJourneyRows = [];
        if (rankGateNodes.length) {
          if (!playerData.player?.account_user) throw new Error("Faction rank story gates require the account user/FLS id.");
          const accountId = requireInteger(playerData.player?.account_id, "account_id", 1);
          const journeyOutput = await timer.step("journey_rank_lookup", async () => withProgressionStepTimeout(dbQuery(`
            select story_node_id, complete_condition_state::text, reveal_condition_state::text
            from dune.journey_story_node
            where account_id = ${accountId}
              and story_node_id = any(${sqlTextArray(rankGateNodes)})
            order by story_node_id;
          `, 12000), 14000, "journey_rank_lookup"));
          currentJourneyRows = parseDbRows(journeyOutput, ["story_node_id", "complete_condition_state", "reveal_condition_state"]);
        }
        oldValues = { faction_id: String(factionId), reputation_rows: currentRows, current_faction_rows: currentFactionRows, journey_rank_rows: currentJourneyRows, target_actor_ids: targetActorIds };
        newValues = { faction_id: factionId, reputation_amount: reputationAmount, target_actor_ids: targetActorIds, account_user: playerData.player?.account_user || "", rank_gate_nodes: rankGateNodes };
        sqlPreview = `For actor IDs ${targetActorIds.join(", ")}: set current faction to ${factionId}, set reputation to ${reputationAmount}, rebuild FactionPlayerComponent cache, and complete ${rankGateNodes.length} faction rank journey gates. Player must be offline for the journey gate write.`;
      }
      const backupPath = progressionBackupPath(actorId, action, previewId);
      await timer.step("backup_create", async () => fs.writeFileSync(backupPath, JSON.stringify({ createdAt: new Date().toISOString(), action, player: playerData.player, oldValues, newValues, source: "progression-preview", readOnlyBackup: true }, null, 2), "utf8"));
      const preview = await timer.step("response_build", async () => ({
        ok: true,
        status: "preview",
        previewId,
        backupPath,
        action,
        player: playerData.player,
        playerOffline: !String(playerData.player?.online_status || "").toLowerCase().includes("online"),
        oldValues,
        newValues,
        fLevelTarget: null,
        techKnowledgeTarget: null,
        auditLogPath: PROGRESSION_AUDIT_LOG,
        sqlPreview,
        warning: action === "skill_unlocks"
          ? "Skill unlock selection is available as a guarded preview. Live skill unlock apply is blocked until the player skill storage path is verified."
          : `Live progression editing can corrupt player data. Backup first. Type ${PROGRESSION_CONFIRM_TEXT} before applying.`
      }));
      preview.timings = timer.finish({ status: "preview", action });
      progressionPreviews.set(previewId, { ...preview, createdAt: Date.now(), componentSupport });
      return preview;
    }

    const selected = await timer.step("selected_target_validate", async () => {
      const selectedPlayer = payload?.selectedPlayer || null;
      if (!selectedPlayer?.player) throw new Error("Progression player target is missing. Reload the player in Progression Inspector before preview.");
      if (!selectedPlayer?.fLevelTarget?.entity_id) throw new Error("Selected FLevelComponent target is missing. Reload the player before preview.");
      if (!selectedPlayer?.techKnowledgeTarget?.actor_id || !selectedPlayer?.techKnowledgeTarget?.path) throw new Error("Selected TechKnowledge target is missing. Reload the player before preview.");
      const fLevelFields = selectedPlayer.fLevelTarget.fields || {};
      for (const key of ["TotalXPEarned", "TotalSkillPoints", "UnspentSkillPoints"]) {
        if (!fLevelFields[key]?.path) throw new Error(`Selected FLevelComponent path is missing for ${key}.`);
      }
      if (String(selectedPlayer.player.online_status || "").toLowerCase().includes("online")) {
        throw new Error("Character XP editing requires the player to be offline.");
      }
      return selectedPlayer;
    });
    const player = selected.player;
    const actorId = requireInteger(player.actor_id, "actor_id", 1);
    const currentCharacter = selected.characterXp || {};
    const currentTech = selected.techKnowledge || {};
    const targetValues = {
      TotalXPEarned: progressionInteger(payload?.totalXpEarned, "TotalXPEarned", CHARACTER_PROGRESSION_LIMITS.TotalXPEarned),
      TotalSkillPoints: progressionInteger(payload?.totalSkillPoints, "TotalSkillPoints", CHARACTER_PROGRESSION_LIMITS.TotalSkillPoints),
      UnspentSkillPoints: progressionInteger(payload?.unspentSkillPoints, "UnspentSkillPoints", CHARACTER_PROGRESSION_LIMITS.UnspentSkillPoints),
      m_TechKnowledgePoints: progressionInteger(payload?.techKnowledgePoints, "TechKnowledgePoints", CHARACTER_PROGRESSION_LIMITS.m_TechKnowledgePoints)
    };
    const advancedOverride = payload?.advancedOverride === true || payload?.advancedOverride === "true";
    if (targetValues.UnspentSkillPoints > targetValues.TotalSkillPoints && !advancedOverride) {
      throw new Error("UnspentSkillPoints must not exceed TotalSkillPoints unless advanced override is enabled.");
    }
    const diff = await timer.step("diff_build", async () => {
      const oldAll = {
        TotalXPEarned: currentCharacter.TotalXPEarned ?? "",
        TotalSkillPoints: currentCharacter.TotalSkillPoints ?? "",
        UnspentSkillPoints: currentCharacter.UnspentSkillPoints ?? "",
        m_TechKnowledgePoints: currentTech.m_TechKnowledgePoints ?? ""
      };
      const oldValues = {};
      const newValues = {};
      for (const [key, value] of Object.entries(targetValues)) {
        if (String(oldAll[key]) !== String(value)) {
          oldValues[key] = oldAll[key];
          newValues[key] = value;
        }
      }
      if (!Object.keys(newValues).length) throw new Error("No changed progression values were selected.");
      return { oldAll, oldValues, newValues };
    });
    const previewId = crypto.randomBytes(16).toString("hex");
    const backupPath = progressionBackupPath(actorId, action, previewId);
    await timer.step("backup_create", async () => {
      const backup = {
        createdAt: new Date().toISOString(),
        action,
        player,
        oldValues: diff.oldValues,
        fLevelTarget: selected.fLevelTarget,
        techKnowledgeTarget: selected.techKnowledgeTarget,
        source: "progression-preview",
        readOnlyBackup: true
      };
      fs.writeFileSync(backupPath, JSON.stringify(backup, null, 2), "utf8");
    });
    const changedDescriptions = Object.keys(diff.newValues).map((key) => `${key}: ${diff.oldValues[key]} -> ${diff.newValues[key]}`);
    const componentSupport = {
      fLevelTarget: selected.fLevelTarget,
      techKnowledgeTarget: selected.techKnowledgeTarget,
      advancedOverride
    };
    await timer.step("audit_preview_write", async () => progressionAudit("progression_preview_created", { action, player, oldValues: diff.oldValues, newValues: diff.newValues, backupFilePath: backupPath, fLevelTarget: selected.fLevelTarget, techKnowledgeTarget: selected.techKnowledgeTarget }));
    const preview = await timer.step("response_build", async () => ({
      ok: true,
      status: "preview",
      previewId,
      backupPath,
      action,
      player,
      playerOffline: !String(player?.online_status || "").toLowerCase().includes("online"),
      oldValues: diff.oldValues,
      newValues: diff.newValues,
      fLevelTarget: selected.fLevelTarget,
      techKnowledgeTarget: selected.techKnowledgeTarget,
      auditLogPath: PROGRESSION_AUDIT_LOG,
      sqlPreview: `Selected target diff only:\n${changedDescriptions.join("\n")}`,
      warning: `Live progression editing can corrupt player data. Backup first. Type ${PROGRESSION_CONFIRM_TEXT} before applying.`
    }));
    progressionPreviews.set(previewId, { ...preview, createdAt: Date.now(), componentSupport });
    preview.timings = timer.finish({ status: "preview", action, changedFields: Object.keys(diff.newValues) });
    return preview;
  } catch (error) {
    return fail(error);
  }
}

function factionComponentArraySql(actorId) {
  return `
    update dune.actors
    set properties = jsonb_set(
      properties,
      '{FactionPlayerComponent,m_FactionDataArray}',
      coalesce((
        select jsonb_agg(jsonb_build_object(
          'Faction', jsonb_build_object('Name', faction_name),
          'timestamp', extract(epoch from now()),
          'ReputationAmount', reputation_amount
        ) order by faction_id)
        from (
          select pfr.faction_id, coalesce(f.name, pfr.faction_id::text) as faction_name, pfr.reputation_amount
          from dune.player_faction_reputation pfr
          left join dune.factions f on f.id = pfr.faction_id
          where pfr.actor_id = ${actorId}
            and coalesce(f.name, '') <> 'None'
        ) as reputation_rows
      ), '[]'::jsonb),
      true
    )
    where id = ${actorId}
      and properties ? 'FactionPlayerComponent';
  `;
}

async function progressionApply(payload) {
  const timer = progressionPhaseTimer("progression/apply");
  let configValue = null;
  let preview = null;
  let action = "";
  const previewId = String(payload?.previewId || "").trim();
  const rowsAffected = {};
  const skippedFields = [];
  const changedFields = [];
  let verificationDebug = {};
  const fail = async (error) => {
    const timedOut = /timed out|timeout/i.test(error.message);
    const failedStep = timer.currentStep;
    timer.finish({ status: timedOut ? "timeout" : "error", previewId, action, step: failedStep, error: error.message });
    if (preview) {
      try {
        await timer.step("audit_write", () => Promise.resolve(progressionAudit("progression_apply_failure", {
          action,
          player: preview.player,
          oldValues: preview.oldValues,
          newValues: preview.newValues,
          backupFilePath: preview.backupPath,
          success: false,
          step: failedStep,
          timings: timer.timings,
          error: error.message
        })));
      } catch {}
    }
    return {
      ok: false,
      status: timedOut ? "timeout" : "error",
      step: failedStep,
      timings: timer.timings,
      action,
      backupPath: preview?.backupPath || "",
      auditLogPath: PROGRESSION_AUDIT_LOG,
      error: error.message,
      debug: verificationDebug
    };
  };
  try {
    configValue = await timer.step("config_load", () => Promise.resolve(loadConfig()));
    await timer.step("safety_check", async () => {
      if (!configValue.progressionEditingEnabled) throw new Error("Enable Progression Editing is OFF.");
    });
    preview = await timer.step("request_validate", async () => {
      const storedPreview = progressionPreviews.get(previewId);
      if (!storedPreview) throw new Error("Dry-run preview was not generated first or has expired.");
      if (payload?.confirmText !== PROGRESSION_CONFIRM_TEXT) throw new Error(`Type ${PROGRESSION_CONFIRM_TEXT} before applying.`);
      if (Date.now() - storedPreview.createdAt > 1000 * 60 * 30) throw new Error("Dry-run preview expired. Generate a new preview.");
      action = storedPreview.action;
      return storedPreview;
    });
    await timer.step("backup_create", async () => {
      if (!fs.existsSync(preview.backupPath)) throw new Error("Matching backup file is missing.");
    });
    const actorId = requireInteger(preview.player.actor_id, "actor_id", 1);
    if (action === "skill_unlocks") {
      throw new Error("Skill unlock apply is not enabled yet. The app can list and preview selected skills, but no verified player skill unlock storage adapter was detected.");
    } else if (action === "specialization_xp") {
      const specializationPlayerId = requireInteger(preview.newValues.player_id || preview.player?.player_controller_id, "specialization_player_id", 1);
      await timer.step("safety_check", async () => {
        const inspect = await withProgressionStepTimeout(progressionInspector(), 10000, "safety_check");
        if (inspect.supports?.specializationXp?.status !== "detected") throw new Error("Specialization XP support is no longer detected.");
        if (!preview.playerOffline || String(preview.player?.online_status || "").toLowerCase().includes("online")) throw new Error("Specialization editing requires the player to be offline.");
      });
      await timer.step("flevel_update", async () => withProgressionStepTimeout(dbQuery(`
        begin;
        set local search_path to dune, public;
        select dune.set_specialization_xp_and_level(${specializationPlayerId}, ${sqlString(preview.newValues.track_type)}::dune.specializationtracktype, ${preview.newValues.xp_amount}, ${preview.newValues.level});
        commit;
      `, 20000), 22000, "flevel_update"));
      const readBackOutput = await timer.step("verify_readback", async () => withProgressionStepTimeout(dbQuery(`
        select player_id::text, track_type::text, xp_amount::text, level::text
        from dune.specialization_tracks
        where player_id = ${specializationPlayerId}
          and track_type = ${sqlString(preview.newValues.track_type)}::dune.specializationtracktype
        limit 1;
      `, 15000), 17000, "verify_readback"));
      const [playerId = "", trackType = "", xpAmount = "", level = ""] = String(readBackOutput || "").split("\t");
      const readBackValues = { player_id: playerId, track_type: trackType, xp_amount: xpAmount, level };
      const expectedValues = { player_id: String(specializationPlayerId), track_type: String(preview.newValues.track_type), xp_amount: String(preview.newValues.xp_amount), level: String(preview.newValues.level) };
      const verified = Object.keys(expectedValues).every((key) => String(readBackValues[key]) === expectedValues[key]);
      verificationDebug = { readBackValues, expectedValues };
      if (!verified) {
        progressionPreviews.delete(previewId);
        await timer.step("audit_write", async () => progressionAudit("progression_apply_verification_failed", { action, player: preview.player, oldValues: preview.oldValues, newValues: preview.newValues, backupFilePath: preview.backupPath, success: false, verificationFailed: true, timings: timer.timings, debug: verificationDebug }));
        timer.finish({ status: "verification_failed", previewId, action });
        return { ok: false, status: "verification_failed", step: "verify_readback", timings: timer.timings, action, player: preview.player, oldValues: preview.oldValues, newValues: preview.newValues, backupPath: preview.backupPath, auditLogPath: PROGRESSION_AUDIT_LOG, debug: verificationDebug, warning: "Database write completed, but specialization read-back did not match the requested XP and level." };
      }
    } else if (action === "faction_reputation") {
      await timer.step("safety_check", async () => {
        const inspect = await withProgressionStepTimeout(progressionInspector(), 10000, "safety_check");
        if (inspect.supports?.factionReputation?.status !== "detected") throw new Error("Faction reputation support is no longer detected.");
        if (!preview.componentSupport?.factionComponent) throw new Error("FactionPlayerComponent cache sync support was not detected.");
        if ((preview.newValues.rank_gate_nodes || []).length && (!preview.playerOffline || String(preview.player?.online_status || "").toLowerCase().includes("online"))) {
          throw new Error("Faction rank story gate editing requires the player to be offline.");
        }
      });
      const factionTargetActorIds = [...new Set((preview.newValues.target_actor_ids || [actorId]).map((value) => Number(value)).filter((value) => Number.isSafeInteger(value) && value > 0))];
      const rankGateNodes = Array.isArray(preview.newValues.rank_gate_nodes) ? preview.newValues.rank_gate_nodes : [];
      const accountUser = String(preview.newValues.account_user || preview.player?.account_user || "").trim();
      if (rankGateNodes.length && !accountUser) throw new Error("Faction rank story gate editing requires the account user/FLS id.");
      const completeRankGateSql = rankGateNodes.length
        ? `select dune.complete_journey_story_nodes_for_player(${sqlString(accountUser)}, ${sqlTextArray(rankGateNodes)});`
        : "";
      await timer.step("flevel_update", async () => withProgressionStepTimeout(dbQuery(`
        set search_path to dune, public;
        begin;
        ${factionTargetActorIds
          .map((targetId) => `
        select dune.change_player_faction(${targetId}, ${preview.newValues.faction_id}::smallint, 3::smallint, now()::timestamp);
        select dune.set_player_faction_reputation(${targetId}, ${preview.newValues.faction_id}::smallint, ${preview.newValues.reputation_amount});
        ${factionComponentArraySql(targetId)}`).join("\n")}
        ${completeRankGateSql}
        commit;
      `, 20000), 22000, "flevel_update"));
      const readBackOutput = await timer.step("verify_readback", async () => withProgressionStepTimeout(dbQuery(`
        with candidates(actor_id) as (values ${sqlValuesList(factionTargetActorIds)})
        select c.actor_id::text,
          coalesce(pf.faction_id::text, '') as current_faction_id,
          coalesce(cf.name, '') as current_faction_name,
          coalesce(pfr.reputation_amount::text, '') as reputation_amount
        from candidates c
        left join dune.player_faction pf on pf.actor_id = c.actor_id
        left join dune.factions cf on cf.id = pf.faction_id
        left join dune.player_faction_reputation pfr on pfr.actor_id = c.actor_id and pfr.faction_id = ${preview.newValues.faction_id}::smallint
        order by c.actor_id;
      `, 15000), 17000, "verify_readback"));
      const readBackValues = parseDbRows(readBackOutput, ["actor_id", "current_faction_id", "current_faction_name", "reputation_amount"]);
      const journeyReadBackValues = rankGateNodes.length
        ? parseDbRows(await timer.step("verify_rank_gates", async () => withProgressionStepTimeout(dbQuery(`
          select story_node_id, complete_condition_state::text, reveal_condition_state::text
          from dune.journey_story_node
          where account_id = ${requireInteger(preview.player?.account_id, "account_id", 1)}
            and story_node_id = any(${sqlTextArray(rankGateNodes)})
          order by story_node_id;
        `, 15000), 17000, "verify_rank_gates")), ["story_node_id", "complete_condition_state", "reveal_condition_state"])
        : [];
      const expectedFactionId = String(preview.newValues.faction_id);
      const expectedReputation = String(preview.newValues.reputation_amount);
      const verified = readBackValues.length === factionTargetActorIds.length
        && readBackValues.every((row) => row.current_faction_id === expectedFactionId && row.reputation_amount === expectedReputation)
        && (!rankGateNodes.length || (journeyReadBackValues.length === rankGateNodes.length && journeyReadBackValues.every((row) => row.complete_condition_state === "true" && row.reveal_condition_state === "true")));
      verificationDebug = {
        targetActorIds: factionTargetActorIds,
        rankGateNodes,
        rowsAffected,
        readBackValues,
        journeyReadBackValues,
        expectedValues: { current_faction_id: expectedFactionId, reputation_amount: expectedReputation }
      };
      if (!verified) {
        progressionPreviews.delete(previewId);
        await timer.step("audit_write", async () => progressionAudit("progression_apply_verification_failed", { action, player: preview.player, oldValues: preview.oldValues, newValues: preview.newValues, backupFilePath: preview.backupPath, success: false, verificationFailed: true, timings: timer.timings, debug: verificationDebug }));
        timer.finish({ status: "verification_failed", previewId, action });
        return { ok: false, status: "verification_failed", step: "verify_readback", timings: timer.timings, action, player: preview.player, oldValues: preview.oldValues, newValues: preview.newValues, backupPath: preview.backupPath, auditLogPath: PROGRESSION_AUDIT_LOG, debug: verificationDebug, warning: "Database write completed, but faction read-back did not match the requested values." };
      }
    } else if (action === "character_xp_skill_points") {
      await timer.step("player_offline_check", async () => {
        if (!preview.playerOffline || String(preview.player?.online_status || "").toLowerCase().includes("online")) {
          throw new Error("Character XP editing requires the player to be offline.");
        }
      });
      const fLevelTarget = preview.componentSupport?.fLevelTarget;
      const fLevelFields = fLevelTarget?.fields || {};
      if (!fLevelTarget?.entity_id
        || !fLevelFields.TotalXPEarned?.path
        || !fLevelFields.TotalSkillPoints?.path
        || !fLevelFields.UnspentSkillPoints?.path) {
        throw new Error("Preview did not include a resolved FLevelComponent path.");
      }
      const techTarget = preview.componentSupport?.techKnowledgeTarget;
      if (!techTarget?.actor_id || !techTarget?.path) throw new Error("Preview did not include a resolved TechKnowledge component path.");
      const fLevelEntityId = requireSqlIntegerLiteral(fLevelTarget.entity_id, "fLevel_entity_id");
      const fLevelChanges = [
        { key: "TotalXPEarned", path: fLevelFields.TotalXPEarned.path, value: preview.newValues.TotalXPEarned },
        { key: "TotalSkillPoints", path: fLevelFields.TotalSkillPoints.path, value: preview.newValues.TotalSkillPoints },
        { key: "UnspentSkillPoints", path: fLevelFields.UnspentSkillPoints.path, value: preview.newValues.UnspentSkillPoints }
      ].filter((field) => Object.prototype.hasOwnProperty.call(preview.newValues || {}, field.key)).filter((field) => {
        const changed = String(preview.oldValues?.[field.key] ?? "") !== String(field.value);
        (changed ? changedFields : skippedFields).push(field.key);
        return changed;
      });
      const techInPreview = Object.prototype.hasOwnProperty.call(preview.newValues || {}, "m_TechKnowledgePoints");
      const techChanged = techInPreview && String(preview.oldValues?.m_TechKnowledgePoints ?? "") !== String(preview.newValues.m_TechKnowledgePoints);
      if (techInPreview) (techChanged ? changedFields : skippedFields).push("m_TechKnowledgePoints");
      if (fLevelChanges.length) {
        let fLevelExpression = "components";
        for (const field of fLevelChanges) {
          fLevelExpression = `jsonb_set(${fLevelExpression}, ${sqlTextArrayPath(field.path)}, to_jsonb(${field.value}::bigint), false)`;
        }
        const output = await timer.step("flevel_update", async () => withProgressionStepTimeout(dbQuery(`
          begin;
          with updated_flevel as (
            update dune.fgl_entities
            set components = ${fLevelExpression}
            where entity_id = ${fLevelEntityId}
            returning 1
          )
          select 'flevel_rows', count(*)::text from updated_flevel;
          commit;
        `, 20000), 22000, "flevel_update"));
        const debugRows = parseDbRows(output, ["key", "value"]);
        Object.assign(rowsAffected, Object.fromEntries(debugRows.filter((row) => /_rows$/.test(row.key || "")).map((row) => [row.key, Number(row.value) || 0])));
      } else {
        timer.timings.flevel_update = 0;
      }
      if (techChanged) {
        const output = await timer.step("tech_update", async () => withProgressionStepTimeout(dbQuery(`
          begin;
          with updated_tech as (
            update dune.actors
            set properties = jsonb_set(
              properties,
              ${sqlTextArrayPath(techTarget.path)},
              to_jsonb(${preview.newValues.m_TechKnowledgePoints}::bigint),
              false)
            where id = ${requireInteger(techTarget.actor_id, "tech_knowledge_actor_id", 1)}
            returning 1
          )
          select 'tech_rows', count(*)::text from updated_tech;
          commit;
        `, 20000), 22000, "tech_update"));
        const debugRows = parseDbRows(output, ["key", "value"]);
        Object.assign(rowsAffected, Object.fromEntries(debugRows.filter((row) => /_rows$/.test(row.key || "")).map((row) => [row.key, Number(row.value) || 0])));
      } else {
        timer.timings.tech_update = 0;
      }
      const readBackValues = await timer.step("verify_readback", async () => withProgressionStepTimeout((async () => {
        const fLevelSelects = [
          `coalesce(components #>> ${sqlTextArrayPath(fLevelFields.TotalXPEarned.path)}, '')`,
          `coalesce(components #>> ${sqlTextArrayPath(fLevelFields.TotalSkillPoints.path)}, '')`,
          `coalesce(components #>> ${sqlTextArrayPath(fLevelFields.UnspentSkillPoints.path)}, '')`
        ].join(", ");
        const fLevelOutput = await dbQuery(`select ${fLevelSelects} from dune.fgl_entities where entity_id = ${fLevelEntityId} limit 1`, 15000);
        const [TotalXPEarned = "", TotalSkillPoints = "", UnspentSkillPoints = ""] = String(fLevelOutput || "").split("\t");
        const techOutput = await dbQuery(`select coalesce(properties #>> ${sqlTextArrayPath(techTarget.path)}, '') from dune.actors where id = ${requireInteger(techTarget.actor_id, "tech_knowledge_actor_id", 1)} limit 1`, 15000);
        return { TotalXPEarned, TotalSkillPoints, UnspentSkillPoints, m_TechKnowledgePoints: String(techOutput || "").trim() };
      })(), 30000, "verify_readback"));
      const expected = {};
      for (const field of fLevelChanges) expected[field.key] = String(field.value);
      if (techChanged) expected.m_TechKnowledgePoints = String(preview.newValues.m_TechKnowledgePoints);
      const verified = Object.keys(expected).every((key) => String(readBackValues[key]) === expected[key]);
      verificationDebug = {
        fLevelTarget,
        techKnowledgeTarget: techTarget,
        changedFields,
        skippedFields,
        rowsAffected,
        readBackValues,
        expectedValues: expected
      };
      if (!verified) {
        progressionPreviews.delete(previewId);
        await timer.step("audit_write", async () => progressionAudit("progression_apply_verification_failed", { action, player: preview.player, oldValues: preview.oldValues, newValues: preview.newValues, backupFilePath: preview.backupPath, success: false, verificationFailed: true, timings: timer.timings, debug: verificationDebug }));
        timer.finish({ status: "verification_failed", previewId, action });
        return { ok: false, status: "verification_failed", step: "verify_readback", timings: timer.timings, action, player: preview.player, oldValues: preview.oldValues, newValues: preview.newValues, backupPath: preview.backupPath, auditLogPath: PROGRESSION_AUDIT_LOG, debug: verificationDebug, warning: "Database write completed, but read-back did not match the requested values." };
      }
    } else {
      throw new Error("Unsupported progression action.");
    }
    progressionPreviews.delete(previewId);
    await timer.step("audit_write", async () => progressionAudit("progression_apply_success", { action, player: preview.player, oldValues: preview.oldValues, newValues: preview.newValues, backupFilePath: preview.backupPath, success: true, timings: timer.timings, debug: verificationDebug }));
    const response = await timer.step("response_build", async () => ({
      ok: true,
      status: "applied",
      step: "response_build",
      timings: { ...timer.timings },
      action,
      player: preview.player,
      oldValues: preview.oldValues,
      newValues: preview.newValues,
      backupPath: preview.backupPath,
      auditLogPath: PROGRESSION_AUDIT_LOG,
      debug: verificationDebug
    }));
    response.timings = timer.finish({ status: "applied", previewId, action });
    return response;
  } catch (error) {
    return await fail(error);
  }
}

function redactUrl(value) {
  try {
    const parsed = new URL(value);
    if (parsed.password) parsed.password = "****";
    if (parsed.username) parsed.username = "****";
    return parsed.toString();
  } catch {
    return String(value || "");
  }
}

function httpRequestJson(urlValue, options = {}) {
  return new Promise((resolve, reject) => {
    const transportLabel = String(options.label || "Give-item").trim() || "Receiver";
    let parsed;
    try { parsed = new URL(urlValue); }
    catch { reject(new Error(`${transportLabel} transport URL is invalid.`)); return; }
    const client = parsed.protocol === "https:" ? https : http;
    const body = options.body == null ? null : Buffer.from(typeof options.body === "string" ? options.body : JSON.stringify(options.body));
    const req = client.request(parsed, {
      method: options.method || (body ? "POST" : "GET"),
      headers: {
        ...(body ? { "Content-Type": "application/json", "Content-Length": body.length } : {}),
        ...(options.headers || {})
      },
      timeout: options.timeout || LIVE_GIVE_ENV.timeoutMs
    }, (res) => {
      let text = "";
      res.setEncoding("utf8");
      res.on("data", (chunk) => { text += chunk; });
      res.on("end", () => {
        let data = null;
        try { data = text ? JSON.parse(text) : null; } catch { data = { raw: text }; }
        resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, statusCode: res.statusCode, data, text });
      });
    });
    req.on("timeout", () => req.destroy(new Error(`${transportLabel} transport timed out.`)));
    req.on("error", (error) => {
      const target = redactUrl(urlValue);
      const detail = error.code ? `${error.code}: ${error.message}` : error.message;
      reject(new Error(`${transportLabel} transport request failed for ${target}: ${detail}`));
    });
    if (body) req.write(body);
    req.end();
  });
}

function basicAuthHeader(user, password) {
  return `Basic ${Buffer.from(`${user}:${password}`).toString("base64")}`;
}

function jsonPathEscape(value) {
  return JSON.stringify(String(value)).slice(1, -1);
}

function renderGiveItemTemplate(template, command) {
  return String(template || "").replace(/\{\{\s*(playerId|template|qty|quality|requestId)\s*\}\}/g, (_match, key) => {
    const value = key === "requestId" ? command.requestId : command[key];
    return jsonPathEscape(value);
  });
}

function liveGiveRequiredEnv(mode = LIVE_GIVE_ENV.transport) {
  if (mode === "http-json") {
    return [];
  }
  if (mode === "rabbitmq-http") {
    return [
      "DUNE_ADMIN_RABBITMQ_PUBLISH_URL",
      "DUNE_ADMIN_RABBITMQ_USER",
      "DUNE_ADMIN_RABBITMQ_PASSWORD",
      "DUNE_ADMIN_RABBITMQ_ROUTING_KEY",
      "DUNE_ADMIN_GIVE_ITEM_MESSAGE_TEMPLATE"
    ];
  }
  return [];
}

function liveGiveMissingEnv(mode = LIVE_GIVE_ENV.transport) {
  const values = {
    DUNE_ADMIN_GIVE_ITEM_URL: LIVE_GIVE_ENV.httpUrl,
    DUNE_ADMIN_RABBITMQ_PUBLISH_URL: LIVE_GIVE_ENV.rabbitPublishUrl,
    DUNE_ADMIN_RABBITMQ_USER: LIVE_GIVE_ENV.rabbitUser,
    DUNE_ADMIN_RABBITMQ_PASSWORD: LIVE_GIVE_ENV.rabbitPassword,
    DUNE_ADMIN_RABBITMQ_ROUTING_KEY: LIVE_GIVE_ENV.rabbitRoutingKey,
    DUNE_ADMIN_GIVE_ITEM_MESSAGE_TEMPLATE: LIVE_GIVE_ENV.rabbitMessageTemplate
  };
  return liveGiveRequiredEnv(mode).filter((name) => !values[name]);
}

function transportDisplayName(mode) {
  return mode || "dry-run";
}

const SERVER_STATUS_ONLINE = new Set(["healthy", "reconciling", "running", "updating", "starting", "progressing", "ready"]);
const SERVER_STATUS_OFFLINE = new Set(["stopped", "failed", "error", "unreachable", "missing", "offline"]);

function mapServerStatus(value) {
  const raw = String(value || "").trim();
  const key = raw.toLowerCase();
  if (!raw || key === "unknown") return { raw: raw || "Unknown", label: "Warning", kind: "warn", online: false };
  if (SERVER_STATUS_ONLINE.has(key)) return { raw, label: "Online", kind: "ok", online: true };
  if (SERVER_STATUS_OFFLINE.has(key)) return { raw, label: "Offline", kind: "bad", online: false };
  return { raw, label: "Warning", kind: "warn", online: false };
}

function mapServerSummaryStatus(summary) {
  const phaseStatus = mapServerStatus(summary?.phase || summary?.status);
  const checks = [summary?.servergroup, summary?.gateway, summary?.director].filter((value) => String(value || "").trim()).map(mapServerStatus);
  if (phaseStatus.kind === "bad" || checks.some((check) => check.kind === "bad")) return { label: "Offline", kind: "bad", online: false, phase: phaseStatus, checks };
  if (phaseStatus.online && checks.every((check) => check.kind !== "bad")) return { label: "Online", kind: "ok", online: true, phase: phaseStatus, checks };
  return { label: "Warning", kind: "warn", online: false, phase: phaseStatus, checks };
}

function topServerStatusDecision({ vm = {}, status = null, raw = "", statusResult = null } = {}) {
  const summary = status?.summary || {};
  const keyComponents = {
    phase: summary.phase || summary.status || "",
    servergroup: summary.servergroup || "",
    gateway: summary.gateway || "",
    director: summary.director || ""
  };
  const hardOfflineReasons = Object.entries(keyComponents)
    .filter(([, value]) => SERVER_STATUS_OFFLINE.has(String(value || "").trim().toLowerCase()))
    .map(([key, value]) => `${key}:${value}`);
  const rawText = String(raw || "");
  const battlegroupStatusReturned = Boolean(rawText.trim() && (Object.keys(summary).length || /Battlegroup:|Battlegroup Info|Game Servers/i.test(rawText)));
  const sshReachable = Boolean(statusResult?.ok || battlegroupStatusReturned);
  const hypervRunning = String(vm?.state || vm?.status || "").toLowerCase() === "running";
  const confirmationSources = {
    hypervRunning,
    sshReachable,
    battlegroupStatusReturned,
    parsedBattlegroupPhase: keyComponents.phase || "",
    keyComponents
  };
  if (hardOfflineReasons.length) {
    return { label: "Offline", kind: "bad", online: false, onlineDecisionReason: "Hard offline Battlegroup status/component detected.", hardOfflineReasons, confirmationSources };
  }
  if (battlegroupStatusReturned && sshReachable) {
    return { label: "Online", kind: "ok", online: true, onlineDecisionReason: "SSH returned usable Battlegroup status output and no hard offline state was detected.", hardOfflineReasons, confirmationSources };
  }
  if (sshReachable) {
    return { label: "Warning", kind: "warn", online: false, onlineDecisionReason: "SSH is reachable, but Battlegroup status output was not usable.", hardOfflineReasons, confirmationSources };
  }
  if (hypervRunning) {
    return { label: "Warning", kind: "warn", online: false, onlineDecisionReason: "Hyper-V reports the VM is running, but Battlegroup status could not be confirmed.", hardOfflineReasons, confirmationSources };
  }
  return { label: "Offline", kind: "bad", online: false, onlineDecisionReason: "No reachable VM or SSH Battlegroup status path was confirmed.", hardOfflineReasons: ["no_reachable_vm_or_ssh_path"], confirmationSources };
}

function statusSummaryIsOnline(summary) {
  return mapServerSummaryStatus(summary).online;
}

function serverSnapshotIsOnline(snapshot) {
  return Boolean(statusSummaryIsOnline(snapshot?.status?.summary || snapshot?.status));
}

function runtimeTransportAuditAction(nextMode, startup) {
  if (startup) return nextMode === "http-json" ? "startup_transport_http_json" : "startup_transport_dry_run";
  return nextMode === "http-json" ? "transport_changed_http_json" : "transport_changed_dry_run";
}

function appendRuntimeSafetyAudit(online, nextMode, source, reason) {
  if (nextMode === "http-json") {
    appendAdminAudit("server_online_detected", {
      source,
      serverOnline: online,
      transport: nextMode,
      reason
    });
    return;
  }
  appendAdminAudit("offline_detected", {
    source,
    serverOnline: online,
    reason
  });
  appendAdminAudit("dry_run_enabled", {
    source,
    transport: nextMode,
    serverOnline: online,
    reason
  });
}

function appendLiveGiveAvailabilityAudit(liveGiveAvailable, transport, source) {
  const changed = !liveGiveAvailability.initialized || liveGiveAvailability.available !== liveGiveAvailable;
  liveGiveAvailability.initialized = true;
  liveGiveAvailability.available = liveGiveAvailable;
  if (!changed) return;
  const reason = liveGiveAvailable
    ? "Server and receiver transport are online."
    : (transport?.dryRunReason || transport?.reason || transport?.error || runtimeGiveTransport.reason || "Live Give unavailable.");
  appendAdminAudit(liveGiveAvailable ? "online_detected" : "offline_detected", {
    source,
    serverOnline: Boolean(runtimeGiveTransport.serverOnline),
    receiverReachable: Boolean(transport?.reachable),
    reason
  });
  appendAdminAudit(liveGiveAvailable ? "live_give_enabled" : "dry_run_enabled", {
    source,
    transport: transport?.mode || runtimeGiveTransport.mode || "dry-run",
    serverOnline: Boolean(runtimeGiveTransport.serverOnline),
    receiverReachable: Boolean(transport?.reachable),
    reason
  });
}

async function updateRuntimeGiveTransport(snapshot = null, source = "status") {
  let checked = snapshot;
  if (!checked) {
    const availability = await liveGiveServerAvailability();
    checked = { vm: availability.vm, status: { summary: availability.status }, raw: availability.raw };
  }
  const online = serverSnapshotIsOnline(checked);
  const nextMode = online ? "http-json" : "dry-run";
  const mappedStatus = mapServerSummaryStatus(checked?.status?.summary || checked?.status);
  const nextReason = online ? `Server ${mappedStatus.label}.` : `Server ${mappedStatus.label}.`;
  const changed = !runtimeGiveTransport.initialized || runtimeGiveTransport.mode !== nextMode || runtimeGiveTransport.serverOnline !== online;
  const startup = !runtimeGiveTransport.initialized || source === "startup";
  runtimeGiveTransport.mode = nextMode;
  runtimeGiveTransport.serverOnline = online;
  runtimeGiveTransport.serverStatus = String(checked?.status?.summary?.status || checked?.status?.status || "");
  runtimeGiveTransport.serverStatusMapped = mappedStatus;
  runtimeGiveTransport.reason = nextReason;
  runtimeGiveTransport.initialized = true;
  if (changed) {
    appendAdminAudit(runtimeTransportAuditAction(nextMode, startup), {
      source,
      transport: nextMode,
      serverOnline: online,
      serverStatus: runtimeGiveTransport.serverStatus,
      reason: nextReason
    });
    appendRuntimeSafetyAudit(online, nextMode, source, nextReason);
  }
  return { ...runtimeGiveTransport };
}

function dryRunReason(transport) {
  if (!transport.configured) {
    if (transport.missingEnv?.length) return `Missing required env vars: ${transport.missingEnv.join(", ")}.`;
    return transport.reason || "Live give-item transport is not configured.";
  }
  if (!transport.reachable) {
    if (transport.reason) return transport.reason;
    return transport.error ? `Transport is not reachable: ${transport.error}` : "Transport is configured but not reachable.";
  }
  return "";
}

function liveGiveUnavailableMessage(transport) {
  if ((transport?.mode || runtimeGiveTransport.mode) === "dry-run" && runtimeGiveTransport.reason) {
    return `Live Give Unavailable: ${runtimeGiveTransport.serverOnline ? runtimeGiveTransport.reason : "Server Offline"}.`;
  }
  const missing = transport?.missingEnv || [];
  if (missing.includes("DUNE_ADMIN_GIVE_ITEM_TRANSPORT")) {
    return "Live Give unavailable: missing DUNE_ADMIN_GIVE_ITEM_TRANSPORT.";
  }
  if (missing.length) return `Live Give unavailable: missing ${missing.join(", ")}.`;
  return `Live Give unavailable: ${transport?.dryRunReason || transport?.reason || transport?.error || "transport is not configured."}`;
}

function giveItemCapabilities() {
  return {
    quantity: true,
    tierFilter: true,
    qualitySupported: true,
    qualityParameterName: "quality",
    acceptedQualityValues: [0, 1, 2, 3, 4, 5],
    setDurabilityTo200: true,
    durabilityValue: GIVE_ITEM_DURABILITY_VALUE,
    durabilityFields: {
      current: "stats.FItemStackAndDurabilityStats[1].CurrentDurability",
      maximum: "stats.FItemStackAndDurabilityStats[1].DecayedMaxDurability"
    },
    notes: [
      "Grade 0 uses the live receiver route with RabbitMQ AddItemToInventory.",
      "Grades 1-5 use a database-backed inventory grant and may require the player to relog or refresh inventory.",
      "Dry-run validates the player inventory and next item slot without inserting an item.",
      "Set Durability to 200 writes exactly 200 current and 200 per-instance maximum durability for catalog-proven weapons, armor, tools, and equipment; all other item classes show Durability not applicable.",
      "Known item metadata fields inspected for display/filtering: quality, Quality, itemQuality, durability, rarity, tier, grade, roll, statRoll, itemLevel.",
      "No database writes are performed for capability detection."
    ]
  };
}

function validateGiveItemPayload(payload) {
  const playerId = String(payload.playerId || "").trim();
  const template = String(payload.template || "").trim();
  const qty = Number(payload.qty || 1);
  const capabilities = giveItemCapabilities();
  const hasQuality = Object.prototype.hasOwnProperty.call(payload, "quality") && payload.quality !== "" && payload.quality !== null && payload.quality !== undefined;
  const quality = hasQuality ? Number(payload.quality) : 0;
  if (!playerId) throw new Error("Choose a player first.");
  if (playerId.length > 128 || !/^[A-Za-z0-9_:.+\-# @]+$/.test(playerId)) throw new Error("Player name/id contains unsupported characters.");
  if (!isValidTemplateId(template)) throw new Error("Choose a valid exact item template identifier.");
  if (!Number.isInteger(qty) || qty < 1 || qty > 50000) throw new Error("Quantity must be a whole number between 1 and 50000.");
  if (hasQuality && !capabilities.qualitySupported) throw new Error("Grade giving is not supported by the current receiver method.");
  if (hasQuality && (!Number.isInteger(quality) || quality < 0 || quality > 5)) throw new Error("Grade must be a whole number between 0 and 5.");
  const command = {
    playerId,
    template,
    qty,
    requestId: `${Date.now()}-${Math.random().toString(16).slice(2)}`
  };
  if (hasQuality) command.quality = quality;
  command.setDurabilityTo200 = requestedDurability(payload.setDurabilityTo200);
  return command;
}

function giveTransportConfig() {
  const runtimeMode = LIVE_GIVE_ENV.transport || runtimeGiveTransport.mode || "dry-run";
  if (runtimeMode === "dry-run" || runtimeMode === "disabled") {
    return {
      mode: "dry-run",
      configured: false,
      missingEnv: [],
      runtime: { ...runtimeGiveTransport },
      reason: runtimeGiveTransport.reason || "Server Offline or Not Healthy."
    };
  }
  if (runtimeMode === "http-json") {
    const url = LIVE_GIVE_ENV.httpUrl || LIVE_GIVE_DEFAULT_HTTP_URL;
    const missingEnv = liveGiveMissingEnv("http-json");
    if (missingEnv.length) return { mode: "http-json", configured: false, missingEnv, reason: `${missingEnv.join(", ")} required for http-json transport.` };
    const cfg = loadConfig();
    return {
      mode: "http-json",
      configured: true,
      missingEnv: [],
      url,
      healthUrl: LIVE_GIVE_ENV.httpHealthUrl || LIVE_GIVE_DEFAULT_HEALTH_URL,
      token: receiverHttpAuthToken(cfg),
      tokenSource: receiverHttpAuthSource(cfg),
      runtime: { ...runtimeGiveTransport }
    };
  }
  if (runtimeMode === "rabbitmq-http") {
    const url = LIVE_GIVE_ENV.rabbitPublishUrl;
    const user = LIVE_GIVE_ENV.rabbitUser;
    const password = LIVE_GIVE_ENV.rabbitPassword;
    const routingKey = LIVE_GIVE_ENV.rabbitRoutingKey;
    const messageTemplate = LIVE_GIVE_ENV.rabbitMessageTemplate;
    const missing = liveGiveMissingEnv("rabbitmq-http");
    if (missing.length) return { mode: "rabbitmq-http", configured: false, missingEnv: missing, reason: `${missing.join(", ")} required for rabbitmq-http transport.` };
    let overviewUrl = LIVE_GIVE_ENV.rabbitHealthUrl;
    if (!overviewUrl) {
      try {
        const parsed = new URL(url);
        parsed.pathname = "/api/overview";
        parsed.search = "";
        overviewUrl = parsed.toString();
      } catch {
        overviewUrl = "";
      }
    }
    return { mode: "rabbitmq-http", configured: true, missingEnv: [], url, user, password, routingKey, messageTemplate, overviewUrl };
  }
  return {
    mode: runtimeMode,
    configured: false,
    missingEnv: [],
    reason: `Unsupported runtime Give Item transport '${runtimeMode}'. Use http-json or dry-run.`
  };
}

function activeRuntimeConfigDiagnostics() {
  const cfg = loadConfig();
  const runtimeValues = relevantRuntimeEnvNames().map((name) => runtimeValue(name, "", cfg));
  return {
    activeConfigPath: CONFIG_PATH,
    backendConfigPath: CONFIG_PATH,
    managerConfigPath: MANAGER_CONFIG_PATH,
    appDataDir: APPDATA_DIR,
    managerDataDir: MANAGER_DATA_DIR,
    sourcePriority: [
      "defaults",
      "managed user .env generated from Setup Wizard",
      "app/user .env.local and inherited process env for advanced overrides",
      "config.json runtime mapping from Setup Wizard wins for Suite-managed values",
      "computed runtime fallbacks"
    ],
    envFiles: runtimeEnvFiles().map((entry) => ({
      label: entry.label,
      path: entry.path,
      exists: fs.existsSync(entry.path),
      override: entry.override
    })),
    values: runtimeValues,
    loadedEnvironmentVariables: runtimeValues
  };
}

async function checkGiveTransport() {
  const config = giveTransportConfig();
  if (!config.configured) return { ...config, reachable: false, dryRunReason: dryRunReason({ ...config, reachable: false }) };
  try {
    if (config.mode === "http-json") {
      const headers = config.token ? { Authorization: `Bearer ${config.token}` } : {};
      const response = await httpRequestJson(config.healthUrl, { method: "GET", headers, timeout: LIVE_GIVE_ENV.timeoutMs });
      const healthConfig = response.data?.config || response.data || {};
      const hasTokenFlag = Object.prototype.hasOwnProperty.call(healthConfig, "tokenConfigured") || Object.prototype.hasOwnProperty.call(healthConfig, "tokenConfig");
      const receiverHealthTokenConfigured = Boolean(healthConfig.tokenConfigured ?? healthConfig.tokenConfig);
      const tokenProblem = hasTokenFlag && !receiverHealthTokenConfigured;
      const checked = {
        ...config,
        reachable: response.statusCode >= 200 && response.statusCode < 500 && !tokenProblem,
        statusCode: response.statusCode,
        receiverHealthTokenConfigured,
        reason: tokenProblem ? "Receiver started without a configured authentication token." : config.reason
      };
      return { ...checked, dryRunReason: dryRunReason(checked) };
    }
    if (config.mode === "rabbitmq-http") {
      const response = await httpRequestJson(config.overviewUrl, {
        method: "GET",
        headers: { Authorization: basicAuthHeader(config.user, config.password) },
        timeout: LIVE_GIVE_ENV.timeoutMs
      });
      const checked = { ...config, reachable: response.ok, statusCode: response.statusCode };
      return { ...checked, dryRunReason: dryRunReason(checked) };
    }
  } catch (error) {
    const checked = { ...config, reachable: false, error: error.message };
    return { ...checked, dryRunReason: dryRunReason(checked) };
  }
  const checked = { ...config, reachable: false, error: "Transport reachability check is not implemented." };
  return { ...checked, dryRunReason: dryRunReason(checked) };
}

async function sendLiveGiveItem(command, checkedConfig = null) {
  const config = checkedConfig || await checkGiveTransport();
  if (!config.configured) {
    return {
      ok: false,
      dryRun: false,
      status: "live-unavailable",
      command,
      transport: config.mode,
      missingEnv: config.missingEnv || [],
      error: liveGiveUnavailableMessage(config)
    };
  }
  if (!config.reachable) {
    return {
      ok: false,
      dryRun: false,
      status: "live-unavailable",
      command,
      transport: config.mode,
      missingEnv: config.missingEnv || [],
      error: liveGiveUnavailableMessage(config)
    };
  }
  if (config.mode === "http-json") {
    const headers = config.token ? { Authorization: `Bearer ${config.token}` } : {};
    const response = await httpRequestJson(config.url, {
      method: "POST",
      headers,
      body: {
        playerId: command.playerId,
        itemId: command.template,
        template: command.template,
        quantity: command.qty,
        qty: command.qty,
        quality: command.quality,
        requestId: command.requestId
      },
      timeout: LIVE_GIVE_ENV.timeoutMs
    });
    if (!response.ok) throw new Error(`Give-item HTTP transport returned ${response.statusCode}: ${response.text || "no response body"}`);
    const verified = Boolean(response.data?.verified || response.data?.inventoryVerified || response.data?.grantVerified);
    return {
      ok: true,
      dryRun: false,
      verified,
      status: verified ? "live-verified" : "live-published",
      transport: "http-json",
      command,
      response: response.data,
      stdout: verified ? "Live Give verified by receiver inventory check." : "Live Give published/queued. Inventory verification is not available."
    };
  }
  if (config.mode === "rabbitmq-http") {
    const payload = renderGiveItemTemplate(config.messageTemplate, command);
    try { JSON.parse(payload); }
    catch (error) { throw new Error(`DUNE_ADMIN_GIVE_ITEM_MESSAGE_TEMPLATE did not render valid JSON: ${error.message}`); }
    const response = await httpRequestJson(config.url, {
      method: "POST",
      headers: { Authorization: basicAuthHeader(config.user, config.password) },
      body: {
        properties: {},
        routing_key: config.routingKey,
        payload,
        payload_encoding: "string"
      },
      timeout: LIVE_GIVE_ENV.timeoutMs
    });
    if (!response.ok || response.data?.routed === false) {
      throw new Error(`RabbitMQ publish failed${response.statusCode ? ` (${response.statusCode})` : ""}: ${response.text || "message was not routed"}`);
    }
    return {
      ok: true,
      dryRun: false,
      verified: false,
      status: "live-published",
      transport: "rabbitmq-http",
      command,
      response: { routed: response.data?.routed !== false },
      stdout: "Live Give published/queued. Inventory verification is not available."
    };
  }
  return { ok: false, dryRun: false, status: "live-unavailable", command, error: `Live Give unavailable: unsupported transport '${config.mode}'.` };
}

async function adminProbe() {
  const tablesSql = `
    select table_schema || '.' || table_name
    from information_schema.tables
    where table_type = 'BASE TABLE'
      and table_schema not in ('pg_catalog', 'information_schema')
      and (
        lower(table_name) like '%player%' or
        lower(table_name) like '%character%' or
        lower(table_name) like '%inventory%' or
        lower(table_name) like '%item%'
      )
    order by table_schema, table_name
    limit 80
  `;
  const transport = await checkGiveTransport();
  const liveGiveAvailable = Boolean(transport.configured && transport.reachable);
  let output = "";
  try {
    output = await dbQuery(tablesSql);
  } catch (error) {
    return adminProbeUnavailable(error, transport);
  }
  return {
    ok: true,
    databaseReachable: true,
    transport: transportDisplayName(transport.mode),
    configured: Boolean(transport.configured),
    reachable: Boolean(transport.reachable),
    missingEnv: transport.missingEnv || [],
    liveGiveAvailable,
    dryRunReason: liveGiveAvailable ? "" : (transport.dryRunReason || transport.reason || transport.error || "Live give-item transport is unavailable."),
    giveTransport: {
      mode: transport.mode,
      configured: Boolean(transport.configured),
      reachable: Boolean(transport.reachable),
      statusCode: transport.statusCode || null,
      target: transport.url ? redactUrl(transport.url) : "",
      missingEnv: transport.missingEnv || [],
      reason: transport.reason || transport.error || "",
      dryRunReason: liveGiveAvailable ? "" : (transport.dryRunReason || transport.reason || transport.error || "Live give-item transport is unavailable.")
    },
    tables: output ? output.split(/\r?\n/).filter(Boolean) : [],
    note: liveGiveAvailable
      ? `Live item grants are enabled through ${transport.mode}.`
      : `Player/item database access is reachable. Live item grants are dry-run only: ${transport.dryRunReason || transport.reason || transport.error || "transport is not reachable."}`
  };
}

function adminProbeUnavailable(error, transportOverride = null) {
  const transport = transportOverride || giveTransportConfig();
  const checked = {
    ...transport,
    reachable: Boolean(transport.reachable),
    error: transport.error || transport.reason || ""
  };
  const reason = dryRunReason(checked);
  return {
    ok: false,
    databaseReachable: false,
    transport: transportDisplayName(checked.mode),
    configured: Boolean(checked.configured),
    reachable: Boolean(checked.reachable),
    missingEnv: checked.missingEnv || [],
    liveGiveAvailable: Boolean(checked.configured && checked.reachable),
    dryRunReason: checked.configured && checked.reachable ? "" : reason,
    giveTransport: {
      mode: checked.mode,
      configured: Boolean(checked.configured),
      reachable: Boolean(checked.reachable),
      statusCode: checked.statusCode || null,
      target: checked.url ? redactUrl(checked.url) : "",
      missingEnv: checked.missingEnv || [],
      reason: checked.reason || checked.error || "",
      dryRunReason: checked.configured && checked.reachable ? "" : reason
    },
    error: error?.message || "Admin probe failed.",
    note: `Database/admin probe is offline: ${error?.message || "unknown error"}`
  };
}

async function liveGiveEnvStatus() {
  await updateRuntimeGiveTransport(null, "env");
  const transport = await checkGiveTransport();
  const receiverToken = await receiverTokenDiagnostics(loadConfig(), transport);
  const liveGiveAvailable = Boolean(transport.configured && transport.reachable);
  appendLiveGiveAvailabilityAudit(liveGiveAvailable, transport, "live-give-env");
  return {
    ok: true,
    liveGiveAvailable,
    transport: transportDisplayName(transport.mode),
    configured: Boolean(transport.configured),
    reachable: Boolean(transport.reachable),
    missingEnv: transport.missingEnv || [],
    dryRunReason: liveGiveAvailable ? "" : (transport.dryRunReason || transport.reason || transport.error || "Live give-item transport is unavailable."),
    message: liveGiveAvailable ? "Live Give transport is configured and reachable." : liveGiveUnavailableMessage(transport),
    runtimeTransport: { ...runtimeGiveTransport },
    activeRuntimeConfig: activeRuntimeConfigDiagnostics(),
    requiredModesHelp: requiredModesHelp(),
    receiverToken,
    receiverTokenConfigured: receiverToken.receiverTokenConfigured,
    suiteTokenConfigured: receiverToken.suiteTokenConfigured,
    receiverHealthTokenConfigured: receiverToken.receiverHealthTokenConfigured,
    tokensMatch: receiverToken.tokensMatch,
    receiverStartedBySuite: receiverToken.receiverStartedBySuite,
    configurationSource: receiverToken.configurationSource,
    giveTransport: {
      mode: transport.mode,
      configured: Boolean(transport.configured),
      reachable: Boolean(transport.reachable),
      statusCode: transport.statusCode || null,
      target: transport.url ? redactUrl(transport.url) : "",
      missingEnv: transport.missingEnv || [],
      reason: transport.reason || transport.error || "",
      receiverHealthTokenConfigured: transport.receiverHealthTokenConfigured,
      dryRunReason: liveGiveAvailable ? "" : (transport.dryRunReason || transport.reason || transport.error || "Live give-item transport is unavailable.")
    }
  };
}

function normalizeAdminPlayerRow(line) {
  const [accountId = "", flsId = "", funcomId = "", playerControllerId = "", characterId = "", playerPawnId = "", onlineStatus = "", map = "", characterName = "", resolved = "false", playerStateRowId = "", matchedColumn = ""] = String(line || "").split("\t");
  return {
    id: accountId,
    name: characterName || accountId || "Unknown",
    account_id: accountId,
    fls_id: flsId,
    funcom_id: funcomId,
    player_controller_id: playerControllerId,
    character_id: characterId,
    player_pawn_id: playerPawnId,
    online_status: onlineStatus || "unknown",
    map,
    character_name: characterName || accountId || "Unknown",
    characterNameResolved: /^true$/i.test(resolved),
    player_state_row_id: playerStateRowId,
    matched_column: matchedColumn
  };
}

const playerRenamePreviews = new Map();

function playerRenameBackupPath(rowId, previewId) {
  fs.mkdirSync(PLAYER_RENAME_BACKUP_DIR, { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  return path.join(PLAYER_RENAME_BACKUP_DIR, `${stamp}-player-${rowId}-${previewId}.json`);
}

async function playerRenameTarget(playerStateRowId) {
  const rowId = requireInteger(playerStateRowId, "player_state_row_id", 1);
  const output = await dbQuery(`
    select id::text,
      account_id::text,
      coalesce(player_state_id::text, ''),
      coalesce(player_controller_id::text, ''),
      coalesce(player_pawn_id::text, ''),
      coalesce(dune.decrypt_user_data(encrypted_character_name), ''),
      encode(encrypted_character_name, 'hex'),
      online_status::text,
      character_state::text
    from dune.encrypted_player_state
    where id = ${rowId}
    limit 1;
  `, 15000);
  const row = parseDbRows(output, ["rowId", "accountId", "playerStateId", "playerControllerId", "playerPawnId", "characterName", "encryptedCharacterNameHex", "onlineStatus", "characterState"])[0];
  if (!row) throw new Error("The selected player-state record was not found. Refresh Players and try again.");
  if (String(row.characterState).toLowerCase() !== "active") throw new Error("Only the active character record can be renamed.");
  return row;
}

async function playerRenameDuplicate(newName, excludedRowId) {
  const output = await dbQuery(`
    select id::text, account_id::text, coalesce(dune.decrypt_user_data(encrypted_character_name), '')
    from dune.encrypted_player_state
    where lower(character_state::text) = 'active'
      and id <> ${requireInteger(excludedRowId, "player_state_row_id", 1)}
      and lower(dune.decrypt_user_data(encrypted_character_name)) = lower(${sqlTextLiteral(newName)})
    limit 1;
  `, 15000);
  return parseDbRows(output, ["rowId", "accountId", "characterName"])[0] || null;
}

function prunePlayerRenamePreviews() {
  for (const [previewId, preview] of playerRenamePreviews.entries()) {
    if (playerRenamePreviewExpired(preview.createdAt)) playerRenamePreviews.delete(previewId);
  }
}

async function previewPlayerRename(body = {}) {
  prunePlayerRenamePreviews();
  const rowId = requireInteger(body.playerStateRowId, "player_state_row_id", 1);
  const newName = sanitizePlayerRenameName(body.newName);
  const target = await playerRenameTarget(rowId);
  if (!isOfflinePlayerStatus(target.onlineStatus)) throw new Error("The player must be offline before creating a rename preview.");
  if (target.characterName === newName) throw new Error("The new character name is the same as the current name.");
  const duplicate = await playerRenameDuplicate(newName, rowId);
  if (duplicate) throw new Error(`The character name "${newName}" is already in use.`);

  const previewId = crypto.randomBytes(16).toString("hex");
  const createdAt = Date.now();
  const backupPath = playerRenameBackupPath(rowId, previewId);
  const backup = {
    createdAt: new Date(createdAt).toISOString(),
    action: "player_rename",
    source: "player-rename-preview",
    row: {
      id: target.rowId,
      accountId: target.accountId,
      playerStateId: target.playerStateId,
      playerControllerId: target.playerControllerId,
      playerPawnId: target.playerPawnId,
      characterName: target.characterName,
      encryptedCharacterNameHex: target.encryptedCharacterNameHex,
      onlineStatus: target.onlineStatus,
      characterState: target.characterState
    },
    requestedName: newName
  };
  fs.writeFileSync(backupPath, JSON.stringify(backup, null, 2), "utf8");
  const preview = { previewId, createdAt, backupPath, rowId, currentName: target.characterName, newName, target };
  playerRenamePreviews.set(previewId, preview);
  appendAdminAudit("player_rename_preview_created", {
    previewId,
    playerStateRowId: rowId,
    accountId: target.accountId,
    previousName: target.characterName,
    requestedName: newName,
    backupPath
  });
  return {
    ok: true,
    status: "preview",
    previewId,
    currentName: target.characterName,
    newName,
    playerStateRowId: target.rowId,
    accountId: target.accountId,
    onlineStatus: target.onlineStatus,
    backupPath,
    expiresAt: new Date(createdAt + 15 * 60 * 1000).toISOString(),
    message: `Ready to rename ${target.characterName} to ${newName}. The player is offline and the name is available.`
  };
}

async function applyPlayerRename(body = {}) {
  prunePlayerRenamePreviews();
  const previewId = String(body.previewId || "").trim();
  const preview = playerRenamePreviews.get(previewId);
  if (!preview) throw new Error("Rename preview was not found or has expired. Generate a new preview.");
  if (body.confirmed !== true) throw new Error("Confirm the player rename before applying it.");
  if (playerRenamePreviewExpired(preview.createdAt)) {
    playerRenamePreviews.delete(previewId);
    throw new Error("Rename preview expired. Generate a new preview.");
  }
  if (!fs.existsSync(preview.backupPath)) throw new Error("The encrypted player-state backup is missing. Generate a new preview.");

  const rowId = requireInteger(preview.rowId, "player_state_row_id", 1);
  const previousName = String(preview.currentName || "");
  const newName = sanitizePlayerRenameName(preview.newName);
  try {
    let output = "";
    let queryError = null;
    try {
      output = await dbQuery(`
        begin;
        do $player_rename$
        declare
          current_name text;
          current_status text;
          current_state text;
        begin
          perform pg_advisory_xact_lock(hashtextextended(lower(${sqlTextLiteral(newName)}), 0));
          select dune.decrypt_user_data(encrypted_character_name), online_status::text, character_state::text
            into current_name, current_status, current_state
          from dune.encrypted_player_state
          where id = ${rowId}
          for update;
          if not found then
            raise exception 'The selected player-state record no longer exists.';
          end if;
          if lower(coalesce(current_state, '')) <> 'active' then
            raise exception 'Only the active character record can be renamed.';
          end if;
          if not (lower(coalesce(current_status, '')) = any(array['offline','disconnected','inactive','false','f','0','no'])) then
            raise exception 'The player is online or has an unknown connection state. Rename cancelled.';
          end if;
          if current_name is distinct from ${sqlTextLiteral(previousName)} then
            raise exception 'The character name changed after preview. Refresh Players and try again.';
          end if;
          if exists (
            select 1
            from dune.encrypted_player_state duplicate
            where duplicate.id <> ${rowId}
              and lower(duplicate.character_state::text) = 'active'
              and lower(dune.decrypt_user_data(duplicate.encrypted_character_name)) = lower(${sqlTextLiteral(newName)})
          ) then
            raise exception 'The requested character name is already in use.';
          end if;
          update dune.encrypted_player_state
          set encrypted_character_name = dune.encrypt_user_data(${sqlTextLiteral(newName)})
          where id = ${rowId};
          select dune.decrypt_user_data(encrypted_character_name)
            into current_name
          from dune.encrypted_player_state
          where id = ${rowId};
          if current_name is distinct from ${sqlTextLiteral(newName)} then
            raise exception 'Rename verification failed. The transaction was rolled back.';
          end if;
        end
        $player_rename$;
        select 'RENAMED', id::text, account_id::text, coalesce(player_state_id::text, ''),
          dune.decrypt_user_data(encrypted_character_name), online_status::text, character_state::text
        from dune.encrypted_player_state
        where id = ${rowId};
        commit;
      `, 30000);
    } catch (error) {
      queryError = error;
    }
    let verified = parseDbRows(output, ["kind", "rowId", "accountId", "playerStateId", "characterName", "onlineStatus", "characterState"])
      .find((row) => row.kind === "RENAMED");
    if (!verified || verified.characterName !== newName) {
      const readBack = await playerRenameTarget(rowId).catch(() => null);
      if (readBack?.characterName === newName) {
        verified = {
          rowId: readBack.rowId,
          accountId: readBack.accountId,
          playerStateId: readBack.playerStateId,
          characterName: readBack.characterName,
          onlineStatus: readBack.onlineStatus,
          characterState: readBack.characterState
        };
      } else if (queryError) {
        throw queryError;
      } else {
        throw new Error("Rename completed without a matching read-back result. Check the player record before retrying.");
      }
    }
    playerRenamePreviews.delete(previewId);
    appendAdminAudit("player_renamed", {
      previewId,
      playerStateRowId: rowId,
      accountId: verified.accountId,
      previousName,
      newName,
      backupPath: preview.backupPath,
      verified: true
    });
    return {
      ok: true,
      status: "applied",
      previousName,
      newName,
      playerStateRowId: verified.rowId,
      accountId: verified.accountId,
      onlineStatus: verified.onlineStatus,
      backupPath: preview.backupPath,
      auditLogPath: ADMIN_AUDIT_LOG,
      message: `Player renamed from ${previousName} to ${newName}.`
    };
  } catch (error) {
    appendAdminAudit("player_rename_failed", {
      previewId,
      playerStateRowId: rowId,
      accountId: preview.target.accountId,
      previousName,
      requestedName: newName,
      backupPath: preview.backupPath,
      error: error.message
    });
    throw error;
  }
}

const repairPreviews = new Map();
const REPAIR_CONFIRM_TEXT = "REPAIR DURABILITY";
const REPAIR_PREVIEW_TTL_MS = 30 * 60 * 1000;

function repairDbId(value, label = "database id") {
  const id = String(value || "").trim();
  if (!/^\d+$/.test(id)) throw new Error(`${label} is missing or invalid.`);
  return id;
}

async function landsraadTierInspect() {
  const metadata = await dbQuery(`
    select table_name, column_name, data_type
    from information_schema.columns
    where table_schema = 'dune'
      and (
        (table_name = 'landsraad_task_rewards' and column_name in ('task_id', 'threshold', 'template_id', 'amount'))
        or (table_name = 'landsraad_tasks' and column_name in ('id', 'term_id'))
        or (table_name = 'landsraad_decree_term' and column_name in ('term_id', 'start_time', 'test_term'))
      )
    order by table_name, ordinal_position;
  `, 12000);
  const columns = parseDbRows(metadata, ["table", "column", "data_type"]);
  const names = new Set(columns.map((row) => `${row.table}.${row.column}`));
  const requiredColumns = [
    "landsraad_task_rewards.task_id",
    "landsraad_task_rewards.threshold",
    "landsraad_task_rewards.template_id",
    "landsraad_task_rewards.amount",
    "landsraad_tasks.id",
    "landsraad_tasks.term_id",
    "landsraad_decree_term.term_id",
    "landsraad_decree_term.start_time",
    "landsraad_decree_term.test_term"
  ];
  const supported = requiredColumns.every((name) => names.has(name));
  if (!supported) {
    return { ok: false, status: "unsupported", schema: "dune", table: "landsraad_task_rewards", columns, tiers: [], detectedTierCount: 0, detectedThresholds: [], totalRewardRows: 0, reason: "The Landsraad reward-to-task schema required for current-term tier editing was not detected." };
  }
  const currentTermOutput = await dbQuery(`
    select current_term.term_id::text, current_term.test_term::text
    from dune.landsraad_decree_term current_term
    order by current_term.start_time desc nulls last, current_term.term_id desc
    limit 1;
  `, 15000);
  const currentTermRows = parseDbRows(currentTermOutput, ["termId", "testTerm"]);
  if (currentTermRows.length !== 1) {
    return { ok: false, status: currentTermRows.length ? "ambiguous_current_term" : "no_current_term", schema: "dune", table: "landsraad_task_rewards", columns, tiers: [], detectedTierCount: 0, detectedThresholds: [], totalRewardRows: 0, reason: currentTermRows.length ? `Expected one current Landsraad term; detected ${currentTermRows.length}. No tiers are editable.` : "No current Landsraad term was detected. Start a term, then refresh tiers." };
  }
  const termId = String(currentTermRows[0].termId || "").trim();
  if (!/^[1-9]\d*$/.test(termId) || termId.length > 19) {
    return { ok: false, status: "ambiguous_current_term", schema: "dune", table: "landsraad_task_rewards", columns, tiers: [], detectedTierCount: 0, detectedThresholds: [], totalRewardRows: 0, reason: "The current Landsraad term returned an invalid identifier. No tiers are editable." };
  }
  const testTermValue = String(currentTermRows[0].testTerm || "").trim().toLowerCase();
  if (!["t", "true", "1", "f", "false", "0"].includes(testTermValue)) {
    return { ok: false, status: "ambiguous_current_term", schema: "dune", table: "landsraad_task_rewards", columns, tiers: [], detectedTierCount: 0, detectedThresholds: [], totalRewardRows: 0, termId, reason: `Current Landsraad term ${termId} returned an unknown test-term state. No tiers are editable.` };
  }
  const testTerm = ["t", "true", "1"].includes(testTermValue);
  if (testTerm) {
    return { ok: false, status: "test_term", schema: "dune", table: "landsraad_task_rewards", columns, tiers: [], detectedTierCount: 0, detectedThresholds: [], totalRewardRows: 0, termId, testTerm: true, reason: `Current Landsraad term ${termId} is a test term. Reward-tier editing is limited to the current non-test term.` };
  }
  const output = await dbQuery(`
    select rewards.threshold::text, count(*)::text
    from dune.landsraad_task_rewards rewards
    join dune.landsraad_tasks tasks on tasks.id = rewards.task_id
    where tasks.term_id = ${termId}::bigint
    group by rewards.threshold
    order by rewards.threshold;
  `, 15000);
  const detectedTiers = parseDbRows(output, ["threshold", "rowCount"]).map((row) => ({
    threshold: requireInteger(row.threshold, "Stored Landsraad threshold", 1, 2147483647),
    rowCount: requireInteger(row.rowCount, "Stored Landsraad reward row count", 1, 10000000)
  }));
  const detectedThresholds = detectedTiers.map((row) => row.threshold);
  const exactTierCount = detectedTiers.length === LANDSRAAD_TIER_COUNT;
  const tiers = exactTierCount ? detectedTiers.map((row, index) => ({
    ...row,
    tier: index + 1,
    label: `Tier ${index + 1}`
  })) : [];
  const reason = exactTierCount
    ? ""
    : `Current Landsraad term ${termId} must contain exactly ${LANDSRAAD_TIER_COUNT} distinct reward thresholds; detected ${detectedTiers.length}: ${detectedThresholds.length ? detectedThresholds.join(", ") : "(none)"}. Historical terms were excluded and no tiers are editable.`;
  return {
    ok: exactTierCount,
    status: exactTierCount ? "detected" : "invalid_tier_count",
    schema: "dune",
    table: "landsraad_task_rewards",
    scope: "current_non_test_term",
    termId,
    testTerm: false,
    columns,
    tiers,
    detectedTierCount: detectedTiers.length,
    detectedThresholds,
    totalRewardRows: detectedTiers.reduce((sum, row) => sum + row.rowCount, 0),
    reason
  };
}

async function landsraadTierBackupRows(termId) {
  const currentTermId = String(termId || "").trim();
  if (!/^[1-9]\d*$/.test(currentTermId) || currentTermId.length > 19) throw new Error("Current Landsraad term id is invalid.");
  const output = await dbQuery(`
    select rewards.task_id::text, rewards.threshold::text, rewards.template_id, rewards.amount::text
    from dune.landsraad_task_rewards rewards
    join dune.landsraad_tasks tasks on tasks.id = rewards.task_id
    where tasks.term_id = ${currentTermId}::bigint
    order by rewards.threshold, rewards.task_id, rewards.template_id, rewards.amount;
  `, 20000);
  return parseDbRows(output, ["task_id", "threshold", "template_id", "amount"]);
}

function validateLandsraadThresholds(values, expectedCount) {
  if (!Array.isArray(values)) throw new Error("Tier thresholds must be an array.");
  if (values.length !== expectedCount) throw new Error(`Keep all ${expectedCount} detected Landsraad tiers.`);
  const thresholds = values.map((value, index) => requireInteger(value, `Tier ${index + 1} threshold`, 1, 2147483647));
  for (let index = 1; index < thresholds.length; index += 1) {
    if (thresholds[index] <= thresholds[index - 1]) throw new Error(`Tier ${index + 1} must be greater than Tier ${index}.`);
  }
  return thresholds;
}

async function landsraadTierPreview(payload) {
  try {
    const inspect = await landsraadTierInspect();
    if (!inspect.ok) return { ok: false, status: inspect.status, inspect, error: inspect.reason };
    const thresholds = validateLandsraadThresholds(payload?.thresholds, inspect.tiers.length);
    const rows = await landsraadTierBackupRows(inspect.termId);
    const postBackupInspect = await landsraadTierInspect();
    const backupDistribution = new Map();
    for (const row of rows) {
      const threshold = requireInteger(row.threshold, "Backed-up Landsraad threshold", 1, 2147483647);
      backupDistribution.set(threshold, (backupDistribution.get(threshold) || 0) + 1);
    }
    const distributionChanged = !postBackupInspect.ok
      || postBackupInspect.termId !== inspect.termId
      || rows.length !== inspect.totalRewardRows
      || backupDistribution.size !== inspect.tiers.length
      || inspect.tiers.some((row) => backupDistribution.get(row.threshold) !== row.rowCount)
      || postBackupInspect.tiers.some((row, index) => row.threshold !== inspect.tiers[index]?.threshold || row.rowCount !== inspect.tiers[index]?.rowCount);
    if (distributionChanged) throw new Error("Landsraad reward tiers changed during preview. No backup or preview was created; refresh and try again.");
    const previewId = crypto.randomBytes(16).toString("hex");
    const newTiers = inspect.tiers.map((row, index) => ({ ...row, threshold: thresholds[index] }));
    const backupPath = progressionBackupPath("landsraad", "tiers", previewId);
    const oldValues = { termId: inspect.termId, tiers: inspect.tiers, rows };
    const newValues = { termId: inspect.termId, tiers: newTiers, totalRewardRows: inspect.totalRewardRows };
    fs.writeFileSync(backupPath, JSON.stringify({ createdAt: new Date().toISOString(), action: "landsraad_tiers", oldValues, newValues, source: "landsraad-tier-preview", readOnlyBackup: true }, null, 2), "utf8");
    const changedRewardRows = inspect.tiers.reduce((sum, row, index) => sum + (row.threshold === thresholds[index] ? 0 : row.rowCount), 0);
    const preview = {
      ok: true,
      status: "preview",
      previewId,
      action: "landsraad_tiers",
      backupPath,
      auditLogPath: PROGRESSION_AUDIT_LOG,
      oldValues,
      newValues,
      changedRewardRows,
      confirmText: LANDSRAAD_TIER_CONFIRM_TEXT,
      warning: `This changes ${changedRewardRows} live Landsraad reward row(s). Type ${LANDSRAAD_TIER_CONFIRM_TEXT} before applying.`
    };
    landsraadTierPreviews.set(previewId, { ...preview, createdAt: Date.now() });
    progressionAudit("landsraad_tier_preview_created", { oldValues: { tiers: inspect.tiers, totalRewardRows: rows.length }, newValues, backupFilePath: backupPath });
    return preview;
  } catch (error) {
    return { ok: false, status: "error", error: error.message, auditLogPath: PROGRESSION_AUDIT_LOG };
  }
}

function landsraadTierDistributionSql(tiers) {
  return tiers.map((row) => `(${requireInteger(row.threshold, "threshold", 1, 2147483647)}, ${requireInteger(row.rowCount, "rowCount", 1, 10000000)})`).join(", ");
}

async function landsraadTierApply(payload) {
  let preview = null;
  try {
    if (!loadConfig().progressionEditingEnabled) throw new Error("Enable Progression Editing is OFF.");
    const previewId = String(payload?.previewId || "").trim();
    preview = landsraadTierPreviews.get(previewId);
    if (!preview) throw new Error("Generate Preview + Backup first or refresh an expired preview.");
    if (payload?.confirmText !== LANDSRAAD_TIER_CONFIRM_TEXT) throw new Error(`Type ${LANDSRAAD_TIER_CONFIRM_TEXT} before applying.`);
    if (Date.now() - preview.createdAt > 1000 * 60 * 30) throw new Error("Preview expired. Generate a new preview.");
    if (!fs.existsSync(preview.backupPath)) throw new Error("Matching backup file is missing.");
    const currentInspect = await landsraadTierInspect();
    if (!currentInspect.ok) throw new Error(currentInspect.reason || `Exactly ${LANDSRAAD_TIER_COUNT} Landsraad tiers are required.`);
    const oldTiers = preview.oldValues.tiers;
    const newTiers = preview.newValues.tiers;
    const termId = String(preview.oldValues.termId || "").trim();
    if (!/^[1-9]\d*$/.test(termId) || termId.length > 19) throw new Error("Preview has an invalid Landsraad term id.");
    if (currentInspect.termId !== termId) throw new Error(`The current Landsraad term changed from ${termId} to ${currentInspect.termId}. No changes were applied.`);
    validateLandsraadThresholds(newTiers.map((row) => row.threshold), oldTiers.length);
    const oldDistribution = landsraadTierDistributionSql(oldTiers);
    const newDistribution = landsraadTierDistributionSql(newTiers);
    const changedTiers = oldTiers.map((row, index) => ({ old: row, next: newTiers[index] })).filter((pair) => pair.old.threshold !== pair.next.threshold);
    const cases = changedTiers.map((pair) => `when ${requireInteger(pair.old.threshold, "old threshold", 1, 2147483647)} then ${requireInteger(pair.next.threshold, "new threshold", 1, 2147483647)}`).join("\n          ");
    const oldList = changedTiers.map((pair) => requireInteger(pair.old.threshold, "old threshold", 1, 2147483647)).join(", ");
    const updateSql = changedTiers.length ? `
      update dune.landsraad_task_rewards rewards
      set threshold = case rewards.threshold
          ${cases}
          else rewards.threshold
        end
      from dune.landsraad_tasks tasks
      where tasks.id = rewards.task_id
        and tasks.term_id = ${termId}::bigint
        and rewards.threshold in (${oldList});` : "";
    const output = await dbQueryStreamed(`
      begin;
      lock table dune.landsraad_decree_term, dune.landsraad_tasks, dune.landsraad_task_rewards in share row exclusive mode;
      do $landsraad$
      begin
        if (
          select count(*)
          from (
            select current_term.term_id, current_term.test_term
            from dune.landsraad_decree_term current_term
            order by current_term.start_time desc nulls last, current_term.term_id desc
            limit 1
          ) current_term
          where current_term.term_id = ${termId}::bigint and current_term.test_term = false
        ) <> 1
        then raise exception 'The current Landsraad term changed after preview. No changes were applied.';
        end if;
      end $landsraad$;
      do $landsraad$
      begin
        if exists (
          with expected(threshold, row_count) as (values ${oldDistribution}),
          actual as (
            select rewards.threshold, count(*)::integer as row_count
            from dune.landsraad_task_rewards rewards
            join dune.landsraad_tasks tasks on tasks.id = rewards.task_id
            where tasks.term_id = ${termId}::bigint
            group by rewards.threshold
          )
          select 1 from expected full join actual using (threshold)
          where expected.row_count is distinct from actual.row_count
        ) then raise exception 'Landsraad tier data changed after preview. No changes were applied.';
        end if;
      end $landsraad$;
      ${updateSql}
      do $landsraad$
      begin
        if exists (
          with expected(threshold, row_count) as (values ${newDistribution}),
          actual as (
            select rewards.threshold, count(*)::integer as row_count
            from dune.landsraad_task_rewards rewards
            join dune.landsraad_tasks tasks on tasks.id = rewards.task_id
            where tasks.term_id = ${termId}::bigint
            group by rewards.threshold
          )
          select 1 from expected full join actual using (threshold)
          where expected.row_count is distinct from actual.row_count
        ) then raise exception 'Landsraad tier verification failed. Transaction rolled back.';
        end if;
      end $landsraad$;
      select rewards.threshold::text, count(*)::text
      from dune.landsraad_task_rewards rewards
      join dune.landsraad_tasks tasks on tasks.id = rewards.task_id
      where tasks.term_id = ${termId}::bigint
      group by rewards.threshold order by rewards.threshold;
      commit;
    `, 30000);
    const readBack = parseDbRows(output, ["threshold", "rowCount"]).filter((row) => /^\d+$/.test(row.threshold));
    landsraadTierPreviews.delete(previewId);
    progressionAudit("landsraad_tier_apply_success", { oldValues: { tiers: oldTiers }, newValues: { tiers: newTiers }, backupFilePath: preview.backupPath, success: true, readBack });
    return { ok: true, status: "applied", action: preview.action, tiers: newTiers, changedRewardRows: preview.changedRewardRows, backupPath: preview.backupPath, auditLogPath: PROGRESSION_AUDIT_LOG, readBack };
  } catch (error) {
    if (preview) {
      try { progressionAudit("landsraad_tier_apply_failure", { oldValues: { tiers: preview.oldValues.tiers }, newValues: preview.newValues, backupFilePath: preview.backupPath, success: false, error: error.message }); } catch {}
    }
    return { ok: false, status: "error", error: error.message, backupPath: preview?.backupPath || "", auditLogPath: PROGRESSION_AUDIT_LOG };
  }
}

function repairDecodeStats(value) {
  return Buffer.from(String(value || ""), "base64").toString("utf8");
}

function repairPublicTarget(row) {
  const candidate = durabilityRepairCandidate(row.kind, row.currentDurability, row.decayedMaxDurability);
  const catalogItem = itemCatalogProvider.resolve(row.templateId);
  return {
    targetId: `${row.kind}:${row.id}`,
    kind: row.kind,
    id: row.id,
    inventoryId: row.inventoryId || "",
    inventoryType: row.inventoryType || "",
    vehicleId: row.vehicleId || "",
    vehicleName: row.vehicleName || "",
    templateId: row.templateId || "",
    displayName: catalogItem?.name || row.templateId || row.id,
    catalogSource: catalogItem?.source || "raw-id",
    icon: catalogItem?.icon || "",
    currentDurability: candidate.current,
    allowedMaximum: candidate.maximum,
    repairable: candidate.repairable,
    reason: candidate.reason
  };
}

function repairPlayerSelector(player = {}) {
  const rowId = String(player.player_state_row_id || "").trim();
  if (/^\d+$/.test(rowId)) return `row:${rowId}`;
  const controllerId = String(player.player_controller_id || player.actor_id || "").trim();
  if (/^\d+$/.test(controllerId)) return `controller:${controllerId}`;
  const accountId = String(player.account_id || player.id || "").trim();
  if (/^\d+$/.test(accountId)) return `account:${accountId}`;
  return controllerId || accountId;
}

async function repairResolvePlayer(queryValue) {
  const query = String(queryValue || "").trim();
  if (!query) throw new Error("Choose a player first.");
  const selector = /^(row|controller|account):(\d+)$/i.exec(query);
  const lookup = selector ? selector[2] : query;
  const result = await adminPlayers({ query: lookup, limit: selector ? 50 : 5, hydration: false });
  if (!result.ok || !result.players?.length) throw new Error(result.error || "Player was not found.");
  const selectorField = selector ? { row: "player_state_row_id", controller: "player_controller_id", account: "account_id" }[selector[1].toLowerCase()] : "";
  const exact = result.players.filter((row) => selectorField
    ? String(row[selectorField] || "") === lookup
    : [row.account_id, row.player_controller_id, row.player_pawn_id, row.character_id, row.player_state_row_id, row.character_name]
      .some((value) => String(value || "").toLowerCase() === query.toLowerCase()));
  if (selector && !exact.length) throw new Error("The selected player record was not found. Refresh Players and try again.");
  if (exact.length > 1) throw new Error("The player lookup is ambiguous. Choose the player by controller or account id.");
  const row = exact[0] || result.players[0];
  const player = progressionPlayerFromAdminRow(row, result.source || "adminPlayers");
  repairDbId(player.account_id, "Player account id");
  repairDbId(player.player_controller_id || player.actor_id, "Player controller id");
  repairDbId(player.player_pawn_id, "Player pawn id");
  return player;
}

async function repairInspectPlayer(queryValue, { includePrivate = false } = {}) {
  const player = await repairResolvePlayer(queryValue);
  const accountId = repairDbId(player.account_id, "Player account id");
  const controllerId = repairDbId(player.player_controller_id || player.actor_id, "Player controller id");
  const pawnId = repairDbId(player.player_pawn_id, "Player pawn id");
  const itemSql = `
    select 'item', i.id::text, inv.id::text, inv.inventory_type::text, '', '',
      coalesce(i.template_id::text, ''),
      coalesce(i.stats #>> '{FItemStackAndDurabilityStats,1,CurrentDurability}', ''),
      coalesce(i.stats #>> '{FItemStackAndDurabilityStats,1,DecayedMaxDurability}', ''),
      replace(encode(convert_to(i.stats::text, 'UTF8'), 'base64'), E'\\n', '')
    from dune.inventories inv
    join dune.items i on i.inventory_id = inv.id
    where inv.actor_id = ${pawnId}
      and i.stats #> '{FItemStackAndDurabilityStats,1,CurrentDurability}' is not null
    order by i.id;
  `;
  const vehicleSql = `
    set search_path to dune, public;
    with owned as (
      select * from dune.get_player_owned_vehicles_data(${controllerId}, ${accountId})
    )
    select 'vehicle-module', vm.id::text, '', '', o.out_actor_id::text,
      replace(replace(coalesce(o.out_name, o.out_class, 'Vehicle'), E'\\t', ' '), E'\\n', ' '),
      coalesce(vm.template_id::text, ''),
      coalesce(vm.stats #>> '{FVehicleModuleDurabilityStats,1,CurrentDurability}', ''),
      coalesce(vm.stats #>> '{FVehicleModuleDurabilityStats,1,DecayedMaxDurability}', ''),
      replace(encode(convert_to(vm.stats::text, 'UTF8'), 'base64'), E'\\n', '')
    from owned o
    join dune.vehicle_modules vm on vm.vehicle_id = o.out_actor_id
    where vm.stats #> '{FVehicleModuleDurabilityStats,1,CurrentDurability}' is not null
    order by o.out_actor_id, vm.id;
  `;
  const columns = ["kind", "id", "inventoryId", "inventoryType", "vehicleId", "vehicleName", "templateId", "currentDurability", "decayedMaxDurability", "statsBase64"];
  const [itemOutput, vehicleOutput] = await Promise.all([dbQuery(itemSql, 30000), dbQuery(vehicleSql, 30000)]);
  const privateTargets = [...parseDbRows(itemOutput, columns), ...parseDbRows(vehicleOutput, columns)]
    .filter((row) => row.kind === "item" || row.kind === "vehicle-module")
    .map((row) => ({ ...row, stats: repairDecodeStats(row.statsBase64) }));
  const targets = privateTargets.map(repairPublicTarget);
  const items = targets.filter((target) => target.kind === "item");
  const vehicleModules = targets.filter((target) => target.kind === "vehicle-module");
  const response = {
    ok: true,
    player,
    playerOffline: isOfflinePlayerStatus(player.online_status),
    items,
    vehicleModules,
    summary: {
      durableItems: items.length,
      vehicleModules: vehicleModules.length,
      repairableItems: items.filter((target) => target.repairable).length,
      repairableVehicleModules: vehicleModules.filter((target) => target.repairable).length,
      unknownVehicleMaximums: vehicleModules.filter((target) => target.allowedMaximum === null).length
    },
    policy: {
      preservesPermanentDecay: true,
      itemFallbackMaximum: 100,
      vehicleUnknownMaximumsBlocked: true,
      applyRequiresOfflinePlayer: true,
      liveBattlegroupSupported: true
    }
  };
  return includePrivate ? { ...response, privateTargets } : response;
}

function pruneRepairPreviews() {
  for (const [id, preview] of repairPreviews) {
    if (Date.now() - preview.createdAt > REPAIR_PREVIEW_TTL_MS) repairPreviews.delete(id);
  }
}

async function previewDurabilityRepair(body = {}) {
  pruneRepairPreviews();
  const inspected = await repairInspectPlayer(body.query || body.playerId, { includePrivate: true });
  if (!inspected.playerOffline) throw new Error("The player must be offline before creating a repair preview.");
  const selectedIds = new Set(Array.isArray(body.targetIds) ? body.targetIds.map(String) : []);
  if (!selectedIds.size) throw new Error("Select at least one repairable item or vehicle module.");
  const selected = inspected.privateTargets.filter((row) => selectedIds.has(`${row.kind}:${row.id}`)).map((row) => ({ ...row, ...repairPublicTarget(row) }));
  if (selected.length !== selectedIds.size) throw new Error("One or more selected repair targets no longer exist. Refresh the inspector.");
  const blocked = selected.find((target) => !target.repairable);
  if (blocked) throw new Error(`${blocked.targetId} cannot be repaired: ${blocked.reason}`);
  const previewId = crypto.randomBytes(16).toString("hex");
  const createdAt = Date.now();
  fs.mkdirSync(REPAIR_BACKUP_DIR, { recursive: true });
  const backupPath = path.join(REPAIR_BACKUP_DIR, `${new Date().toISOString().replace(/[:.]/g, "-")}-${previewId}.json`);
  const backup = { action: "durability_repair", createdAt: new Date(createdAt).toISOString(), player: inspected.player, targets: selected.map(({ statsBase64, ...target }) => target) };
  fs.writeFileSync(backupPath, JSON.stringify(backup, null, 2), "utf8");
  const preview = { previewId, createdAt, backupPath, player: inspected.player, targets: selected };
  repairPreviews.set(previewId, preview);
  appendAdminAudit("durability_repair_preview_created", { previewId, accountId: inspected.player.account_id, targetCount: selected.length, backupPath });
  return { ok: true, status: "preview", previewId, player: inspected.player, targets: selected.map(repairPublicTarget), backupPath, auditLogPath: ADMIN_AUDIT_LOG, confirmText: REPAIR_CONFIRM_TEXT, expiresAt: new Date(createdAt + REPAIR_PREVIEW_TTL_MS).toISOString() };
}

async function applyDurabilityRepair(body = {}) {
  pruneRepairPreviews();
  const previewId = String(body.previewId || "").trim();
  const preview = repairPreviews.get(previewId);
  if (!preview) throw new Error("Repair preview was not found or has expired. Generate a new preview.");
  if (String(body.confirmText || "").trim() !== REPAIR_CONFIRM_TEXT) throw new Error(`Type ${REPAIR_CONFIRM_TEXT} to apply the repair.`);
  const player = await repairResolvePlayer(repairPlayerSelector(preview.player));
  if (!isOfflinePlayerStatus(player.online_status)) throw new Error("The player is online or has an unknown connection state. Repair cancelled.");
  const accountId = repairDbId(player.account_id, "Player account id");
  const controllerId = repairDbId(player.player_controller_id || player.actor_id, "Player controller id");
  const pawnId = repairDbId(player.player_pawn_id, "Player pawn id");
  const statements = preview.targets.map((target) => {
    const id = repairDbId(target.id);
    const table = target.kind === "item" ? "dune.items" : "dune.vehicle_modules";
    const durabilityPath = target.kind === "item" ? "{FItemStackAndDurabilityStats,1,CurrentDurability}" : "{FVehicleModuleDurabilityStats,1,CurrentDurability}";
    const expectedStats = sqlString(target.stats);
    const maximum = Number(target.allowedMaximum);
    return `
      update ${table}
      set stats = jsonb_set(stats, '${durabilityPath}', to_jsonb(${maximum}::double precision), false)
      where id = ${id} and stats = ${expectedStats}::jsonb;
      get diagnostics changed = row_count;
      if changed <> 1 then raise exception 'Repair target ${target.targetId} changed after preview.'; end if;
      if not exists (select 1 from ${table} where id = ${id} and abs((stats #>> '${durabilityPath}')::double precision - ${maximum}) < 0.000001) then
        raise exception 'Repair verification failed for ${target.targetId}.';
      end if;`;
  }).join("\n");
  try {
    await dbQueryStreamed(`
      begin;
      do $durability_repair$
      declare changed integer;
      begin
        perform 1
        from dune.player_state ps
        where ps.account_id = ${accountId}
          and ps.player_controller_id = ${controllerId}
          and ps.player_pawn_id = ${pawnId}
          and lower(coalesce(ps.online_status::text, '')) = any(array['offline','disconnected','inactive','false','f','0','no'])
        for update;
        if not found then raise exception 'The player became online or changed after preview. Repair cancelled.'; end if;
        ${statements}
      end
      $durability_repair$;
      commit;
    `, 45000);
    repairPreviews.delete(previewId);
    appendAdminAudit("durability_repair_applied", { previewId, accountId: player.account_id, targetCount: preview.targets.length, backupPath: preview.backupPath, verified: true });
    return { ok: true, status: "applied", repaired: preview.targets.length, player, targets: preview.targets.map(repairPublicTarget), backupPath: preview.backupPath, auditLogPath: ADMIN_AUDIT_LOG, message: `Repaired ${preview.targets.length} durability record(s) to their allowed maximum.` };
  } catch (error) {
    appendAdminAudit("durability_repair_failed", { previewId, accountId: player.account_id, targetCount: preview.targets.length, backupPath: preview.backupPath, error: error.message });
    throw error;
  }
}

function loadRepairQueue() {
  try {
    if (!fs.existsSync(REPAIR_QUEUE_PATH)) return [];
    const parsed = JSON.parse(fs.readFileSync(REPAIR_QUEUE_PATH, "utf8"));
    return Array.isArray(parsed) ? parsed.filter((item) => item && item.queueId && Array.isArray(item.targetIds)).map((item) => item.status === "processing"
      ? { ...item, status: "queued", nextAttemptAt: new Date().toISOString(), lastError: "Suite restarted while this repair was processing; safely queued for revalidation." }
      : item) : [];
  } catch (error) {
    appendAdminAudit("durability_repair_queue_load_failed", { path: REPAIR_QUEUE_PATH, error: error.message });
    return [];
  }
}

let repairQueue = loadRepairQueue();
let repairQueueProcessing = false;

function saveRepairQueue() {
  repairQueue = repairQueue.slice(0, 200);
  fs.mkdirSync(path.dirname(REPAIR_QUEUE_PATH), { recursive: true });
  const temporaryPath = `${REPAIR_QUEUE_PATH}.tmp`;
  fs.writeFileSync(temporaryPath, JSON.stringify(repairQueue, null, 2), "utf8");
  fs.renameSync(temporaryPath, REPAIR_QUEUE_PATH);
}

function publicRepairQueueItem(item) {
  return {
    queueId: item.queueId,
    status: item.status,
    player: item.player,
    targetIds: item.targetIds,
    targetCount: item.targetIds.length,
    createdAt: item.createdAt,
    updatedAt: item.updatedAt,
    attempts: item.attempts || 0,
    nextAttemptAt: item.nextAttemptAt || "",
    lastError: item.lastError || "",
    result: item.result || null
  };
}

function repairQueueSnapshot() {
  return {
    ok: true,
    processing: repairQueueProcessing,
    path: REPAIR_QUEUE_PATH,
    items: repairQueue.map(publicRepairQueueItem),
    summary: {
      queued: repairQueue.filter((item) => item.status === "queued").length,
      processing: repairQueue.filter((item) => item.status === "processing").length,
      completed: repairQueue.filter((item) => item.status === "completed").length,
      failed: repairQueue.filter((item) => item.status === "failed").length
    }
  };
}

async function enqueueDurabilityRepair(body = {}) {
  const confirmText = String(body.confirmText || "").trim();
  if (confirmText !== "QUEUE REPAIR") throw new Error("Type QUEUE REPAIR to queue repairs for an online player.");
  const inspected = await repairInspectPlayer(body.query || body.playerId, { includePrivate: true });
  const requested = new Set(Array.isArray(body.targetIds) ? body.targetIds.map(String) : []);
  if (!requested.size) throw new Error("Select at least one repairable item or vehicle module.");
  const selected = inspected.privateTargets.filter((row) => requested.has(`${row.kind}:${row.id}`)).map((row) => ({ ...row, ...repairPublicTarget(row) }));
  if (selected.length !== requested.size) throw new Error("One or more selected repair targets no longer exist. Refresh the inspector.");
  const blocked = selected.find((target) => !target.repairable);
  if (blocked) throw new Error(`${blocked.targetId} cannot be queued: ${blocked.reason}`);
  const playerQuery = repairPlayerSelector(inspected.player);
  const duplicate = repairQueue.find((item) => item.status === "queued" && String(item.player?.query) === String(playerQuery)
    && item.targetIds.length === requested.size && item.targetIds.every((id) => requested.has(id)));
  if (duplicate) return { ok: true, status: "already-queued", item: publicRepairQueueItem(duplicate), queue: repairQueueSnapshot() };
  const now = new Date().toISOString();
  const item = {
    queueId: crypto.randomBytes(12).toString("hex"),
    status: "queued",
    player: {
      query: String(playerQuery),
      accountId: inspected.player.account_id,
      controllerId: inspected.player.player_controller_id || inspected.player.actor_id,
      pawnId: inspected.player.player_pawn_id,
      characterName: inspected.player.character_name,
      onlineStatusAtQueue: inspected.player.online_status
    },
    targetIds: [...requested],
    createdAt: now,
    updatedAt: now,
    attempts: 0,
    nextAttemptAt: now,
    lastError: "",
    result: null
  };
  repairQueue.unshift(item);
  saveRepairQueue();
  appendAdminAudit("durability_repair_queued", { queueId: item.queueId, accountId: item.player.accountId, playerStatus: item.player.onlineStatusAtQueue, targetIds: item.targetIds });
  setTimeout(() => processRepairQueue().catch(() => {}), 250).unref?.();
  return { ok: true, status: "queued", item: publicRepairQueueItem(item), queue: repairQueueSnapshot(), message: `Queued ${item.targetIds.length} repair(s) for ${item.player.characterName || "player"}. They will run automatically after the player disconnects.` };
}

function removeRepairQueueItem(queueId) {
  const id = String(queueId || "").trim();
  const index = repairQueue.findIndex((item) => item.queueId === id);
  if (index < 0) throw new Error("Repair queue item was not found.");
  if (repairQueue[index].status === "processing") throw new Error("This repair is currently processing and cannot be removed.");
  const [removed] = repairQueue.splice(index, 1);
  saveRepairQueue();
  appendAdminAudit("durability_repair_queue_removed", { queueId: removed.queueId, accountId: removed.player?.accountId, status: removed.status });
  return { ok: true, removed: publicRepairQueueItem(removed), queue: repairQueueSnapshot() };
}

async function processRepairQueueItem(item) {
  const inspected = await repairInspectPlayer(item.player.query, { includePrivate: true });
  item.player.onlineStatusLastChecked = inspected.player.online_status;
  if (!inspected.playerOffline) {
    item.status = "queued";
    item.updatedAt = new Date().toISOString();
    item.nextAttemptAt = new Date(Date.now() + 20000).toISOString();
    item.lastError = "Waiting for player to disconnect.";
    return;
  }
  const requested = new Set(item.targetIds);
  const current = inspected.privateTargets.filter((row) => requested.has(`${row.kind}:${row.id}`)).map((row) => ({ ...row, ...repairPublicTarget(row) }));
  const repairableIds = current.filter((target) => target.repairable).map((target) => target.targetId);
  const skipped = item.targetIds.filter((id) => !repairableIds.includes(id));
  if (!repairableIds.length) {
    item.status = "completed";
    item.updatedAt = new Date().toISOString();
    item.nextAttemptAt = "";
    item.lastError = "";
    item.result = { repaired: 0, skipped, message: "No selected targets still required repair when the player disconnected." };
    appendAdminAudit("durability_repair_queue_completed", { queueId: item.queueId, accountId: item.player.accountId, repaired: 0, skipped });
    return;
  }
  const preview = await previewDurabilityRepair({ query: item.player.query, targetIds: repairableIds });
  const result = await applyDurabilityRepair({ previewId: preview.previewId, confirmText: REPAIR_CONFIRM_TEXT });
  item.status = "completed";
  item.updatedAt = new Date().toISOString();
  item.nextAttemptAt = "";
  item.lastError = "";
  item.result = { repaired: result.repaired, skipped, backupPath: result.backupPath, auditLogPath: result.auditLogPath, message: result.message };
  appendAdminAudit("durability_repair_queue_completed", { queueId: item.queueId, accountId: item.player.accountId, repaired: result.repaired, skipped, backupPath: result.backupPath });
}

async function processRepairQueue() {
  if (SERVER_MIGRATION_ENABLED && migrationMaintenance.status().active) return { ...repairQueueSnapshot(), skipped: true, reason: MIGRATION_MAINTENANCE_BANNER };
  if (repairQueueProcessing) return repairQueueSnapshot();
  const due = repairQueue.filter((item) => item.status === "queued" && (!item.nextAttemptAt || Date.parse(item.nextAttemptAt) <= Date.now()));
  if (!due.length) return repairQueueSnapshot();
  repairQueueProcessing = true;
  try {
    for (const item of due) {
      item.status = "processing";
      item.updatedAt = new Date().toISOString();
      saveRepairQueue();
      try {
        await processRepairQueueItem(item);
      } catch (error) {
        item.attempts = Number(item.attempts || 0) + 1;
        item.status = item.attempts >= 10 ? "failed" : "queued";
        item.updatedAt = new Date().toISOString();
        item.nextAttemptAt = item.status === "queued" ? new Date(Date.now() + 60000).toISOString() : "";
        item.lastError = error.message;
        appendAdminAudit(item.status === "failed" ? "durability_repair_queue_failed" : "durability_repair_queue_retry", { queueId: item.queueId, accountId: item.player?.accountId, attempts: item.attempts, error: error.message });
      }
      saveRepairQueue();
    }
  } finally {
    repairQueueProcessing = false;
  }
  return repairQueueSnapshot();
}

const ADMIN_PLAYER_SCHEMA_TTL_MS = 5 * 60 * 1000;
let adminPlayerSchemaCache = { output: "", loadedAt: 0 };
let adminPlayerSchemaInFlight = null;

async function adminPlayerSchemaColumns() {
  if (adminPlayerSchemaCache.output && Date.now() - adminPlayerSchemaCache.loadedAt < ADMIN_PLAYER_SCHEMA_TTL_MS) {
    return adminPlayerSchemaCache.output;
  }
  if (adminPlayerSchemaInFlight) return adminPlayerSchemaInFlight;
  adminPlayerSchemaInFlight = dbQuery(`
    select table_name || E'\\t' || string_agg(column_name, ',' order by ordinal_position)
    from information_schema.columns
    where table_schema = 'dune'
      and table_name in ('player_state', 'communinet_player', 'accounts')
    group by table_name
  `, 5000).then((output) => {
    adminPlayerSchemaCache = { output, loadedAt: Date.now() };
    return output;
  }).finally(() => {
    adminPlayerSchemaInFlight = null;
  });
  return adminPlayerSchemaInFlight;
}

async function adminPlayers(options = {}) {
  const quoteIdent = (value) => `"${String(value).replace(/"/g, '""')}"`;
  const query = String(options.query || "").trim();
  const typedSelector = parsePlayerSelector(query);
  const numericQuery = /^\d+$/.test(query) || Boolean(typedSelector);
  const limit = Math.max(1, Math.min(Number(options.limit || (query ? 20 : 200)) || 20, query ? 50 : 200));
  const includeHydration = options.hydration !== false;
  const diagnostics = {
    serverPath: DEFAULT_SERVER_ROOT || "",
    sshTarget: VM_IP ? `${SSH_USER}@${VM_IP}` : `${SSH_USER}@auto-vm-ip`,
    sourcesChecked: [],
    filesChecked: [],
    sourceTableUsed: "",
    joinPathUsed: "",
    characterNamesResolved: 0,
    playersFound: 0,
    reason: "",
    errors: []
  };
  const columnOutput = await adminPlayerSchemaColumns().catch((error) => {
    diagnostics.errors.push(`dune metadata lookup: ${error.message}`);
    return "";
  });
  const tableColumns = new Map(columnOutput.split(/\r?\n/).filter(Boolean).map((line) => {
    const [table = "", columnsRaw = ""] = line.split("\t");
    return [table, new Set(columnsRaw.split(",").filter(Boolean).map((column) => column.toLowerCase()))];
  }));
  const playerStateColumns = tableColumns.get("player_state") || new Set();
  const accountColumns = tableColumns.get("accounts") || new Set();
  const canonicalPlayerSchemaSupported = ["id", "account_id", "player_controller_id", "player_state_id", "player_pawn_id", "online_status", "character_name", "last_avatar_activity"]
    .every((column) => playerStateColumns.has(column))
    && ["id", "user", "funcom_id"].every((column) => accountColumns.has(column));
  const communinetColumns = tableColumns.get("communinet_player") || new Set();
  const hasCommuninetAccountId = communinetColumns.has("account_id");
  const communinetSourceLabel = hasCommuninetAccountId ? "dune.communinet_player + dune.player_state" : "dune.player_state";
  const communinetJoinPath = hasCommuninetAccountId
    ? "dune.communinet_player.account_id -> dune.player_state.account_id -> dune.accounts.id"
    : "dune.player_state.account_id -> dune.accounts.id";
  const selectPlayerColumns = `
      a.account_id::text,
      coalesce(ac."user", '') as fls_id,
      coalesce(ac.funcom_id, '') as funcom_id,
      coalesce(ps.player_controller_id::text, '') as player_controller_id,
      coalesce(ps.player_state_id::text, ps.player_pawn_id::text, ps.player_controller_id::text, '') as character_id,
      coalesce(ps.player_pawn_id::text, '') as player_pawn_id,
      coalesce(ps.online_status::text, 'unknown') as online_status,
      '' as map,
      coalesce(nullif(ps.character_name, ''), nullif(ac."user", ''), a.account_id::text) as character_name,
      case when coalesce(nullif(ps.character_name, ''), nullif(ac."user", '')) is null then 'false' else 'true' end as resolved,
      coalesce(ps.id::text, '') as player_state_row_id`;
  const queriedPlayerSql = (partial = false) => {
    if (typedSelector) {
      const column = typedSelector.column;
      const numericValue = typedSelector.value;
      return `
        select ${selectPlayerColumns},
          ${sqlString(typedSelector.matchedColumn)} as matched_column
        from (
          select distinct account_id
          from dune.player_state
          where ${quoteIdent(column)} = ${numericValue}
        ) a
        left join dune.player_state ps on ps.account_id = a.account_id
        left join dune.accounts ac on ac.id = a.account_id
        where ps.${quoteIdent(column)} = ${numericValue}
        order by ps.last_avatar_activity desc nulls last, ps.player_state_id
        limit ${limit}
      `;
    }
    const value = partial ? sqlString(`%${query}%`) : sqlString(query);
    const op = partial ? "ilike" : "=";
    const loweredOp = partial ? "ilike" : "=";
    const namePredicate = partial
      ? `(ps.character_name ilike ${value} or ac."user" ilike ${value})`
      : `(lower(ps.character_name) = lower(${value}) or lower(ac."user") = lower(${value}))`;
    const idPredicate = numericQuery
      ? `
          or a.account_id::text = ${sqlString(query)}
          or ps.account_id::text = ${sqlString(query)}
          or ps.player_controller_id::text = ${sqlString(query)}
          or ps.player_pawn_id::text = ${sqlString(query)}
          or ps.player_state_id::text = ${sqlString(query)}
          or ps.id::text = ${sqlString(query)}
        `
      : "";
    return `
      select ${selectPlayerColumns},
        case
          when lower(coalesce(ps.character_name, '')) ${loweredOp} lower(${value}) then 'character_name'
          when ${partial ? `ac."user" ${op} ${value}` : `lower(coalesce(ac."user", '')) = lower(${value})`} then 'account_user'
          ${numericQuery ? `
          when a.account_id::text = ${sqlString(query)} then 'account_id'
          when ps.player_controller_id::text = ${sqlString(query)} then 'player_controller_id'
          when ps.player_pawn_id::text = ${sqlString(query)} then 'player_pawn_id'
          when ps.player_state_id::text = ${sqlString(query)} then 'player_state_id'
          when ps.id::text = ${sqlString(query)} then 'player_state_row_id'` : ""}
          else 'unknown'
        end as matched_column
      from (
        select account_id from dune.player_state
        where ${partial ? "character_name ilike " + value : "lower(character_name) = lower(" + value + ")"}
          ${numericQuery ? `
          or account_id::text = ${sqlString(query)}
          or player_controller_id::text = ${sqlString(query)}
          or player_pawn_id::text = ${sqlString(query)}
          or player_state_id::text = ${sqlString(query)}
          or id::text = ${sqlString(query)}` : ""}
        union
        select id as account_id from dune.accounts
        where ${partial ? "\"user\" ilike " + value : "lower(\"user\") = lower(" + value + ")"}
          ${numericQuery ? `
          or id::text = ${sqlString(query)}
          or ${partial ? "funcom_id ilike " + value : "lower(funcom_id) = lower(" + value + ")"}` : ""}
        ${hasCommuninetAccountId ? `union
        select account_id from dune.communinet_player
        where ${numericQuery ? `account_id::text = ${sqlString(query)}` : "false"}` : ""}
      ) a
      left join dune.player_state ps on ps.account_id = a.account_id
      left join dune.accounts ac on ac.id = a.account_id
      where ${namePredicate}
        ${idPredicate}
      order by
        case
          ${numericQuery ? `when ps.id::text = ${sqlString(query)} then 0` : ""}
          when lower(coalesce(ps.character_name, '')) ${loweredOp} lower(${value}) then 1
          when ${partial ? `ac."user" ${op} ${value}` : `lower(coalesce(ac."user", '')) = lower(${value})`} then 2
          ${numericQuery ? `when ac.funcom_id ${op} ${value} then 3` : ""}
          else 4
        end,
        ps.last_avatar_activity desc nulls last,
        ps.player_state_id
      limit ${limit}
    `;
  };
  const characterQuery = query ? queriedPlayerSql(false) : `
    with account_ids as (
      select distinct account_id
      from dune.player_state
      where account_id is not null
    )
    select ${selectPlayerColumns}
    from account_ids a
    left join dune.player_state ps on ps.account_id = a.account_id
    left join dune.accounts ac on ac.id = a.account_id
    order by
      case
        when lower(coalesce(ps.online_status::text, '')) in ('online','connected','active','true','t','1','yes') then 0
        when lower(coalesce(ps.online_status::text, '')) in ('offline','disconnected','inactive','false','f','0','no') then 2
        else 1
      end,
      ps.last_avatar_activity desc nulls last,
      a.account_id,
      ps.player_state_id
    limit ${limit}
  `;
  try {
    const started = Date.now();
    console.info("[admin/players] player lookup SQL started", { query, limit, mode: query ? "queried-exact" : "full-list-player-state", timeoutMs: query ? 7000 : 15000 });
    let output = await dbQuery(characterQuery, query ? 7000 : 15000);
    let players = output ? output.split(/\r?\n/).filter(Boolean).map(normalizeAdminPlayerRow).filter((player) => player.id) : [];
    if (query && !players.length) {
      console.info("[admin/players] exact query returned no players; trying partial query", { query, limit, timeoutMs: 7000 });
      output = await dbQuery(queriedPlayerSql(true), 7000);
      players = output ? output.split(/\r?\n/).filter(Boolean).map(normalizeAdminPlayerRow).filter((player) => player.id) : [];
    }
    console.info("[admin/players] player lookup SQL completed", {
      query,
      limit,
      numericQuery,
      rows: players.length,
      durationMs: Date.now() - started,
      sqlParameters: { exact: query, partial: query ? `%${query}%` : "" },
      matchedColumns: players.map((player) => ({
        account_id: player.account_id,
        character_name: player.character_name,
        matched_column: player.matched_column || ""
      }))
    });
    const resolvedCount = players.filter((player) => player.characterNameResolved).length;
    diagnostics.sourcesChecked.push({
      type: "database",
      source: query ? communinetSourceLabel : "dune.player_state",
      idColumn: query && hasCommuninetAccountId ? "communinet_player.account_id / player_state.account_id" : "player_state.account_id",
      nameColumn: "player_state.character_name",
      rows: players.length,
      resolvedNames: resolvedCount,
      ok: true,
      joinPath: query ? communinetJoinPath : "dune.player_state.account_id -> dune.accounts.id",
      query: query || "",
      durationMs: Date.now() - started
    });
    diagnostics.sourceTableUsed = "dune.player_state";
    diagnostics.joinPathUsed = query ? communinetJoinPath : "dune.player_state.account_id -> dune.accounts.id";
    diagnostics.characterNamesResolved = resolvedCount;
    diagnostics.playersFound = players.length;
    if (includeHydration) await attachHydrationToPlayers(players);
    if (players.length) {
      if (!resolvedCount) diagnostics.reason = "Player rows were found, but none had a character_name in dune.player_state.";
      return {
        ok: true,
        source: "dune.player_state",
        query,
        joinPath: diagnostics.joinPathUsed,
        characterNamesResolved: resolvedCount,
        players,
        diagnostics,
        error: resolvedCount ? "" : diagnostics.reason,
        details: playerDiagnosticLines(diagnostics)
      };
    }
    diagnostics.reason = query && hasCommuninetAccountId ? "No account/player rows were found in dune.communinet_player or dune.player_state." : "No account/player rows were found in dune.player_state.";
    if (canonicalPlayerSchemaSupported) {
      return {
        ok: true,
        source: "dune.player_state",
        query,
        players: [],
        diagnostics,
        error: diagnostics.reason,
        details: playerDiagnosticLines(diagnostics)
      };
    }
    if (query && !numericQuery) {
      return {
        ok: true,
        source: "dune.player_state",
        query,
        joinPath: diagnostics.joinPathUsed,
        characterNamesResolved: 0,
        players: [],
        diagnostics,
        error: diagnostics.reason,
        details: playerDiagnosticLines(diagnostics)
      };
    }
  } catch (error) {
    diagnostics.sourcesChecked.push({
      type: "database",
      source: communinetSourceLabel,
      idColumn: hasCommuninetAccountId ? "communinet_player.account_id / player_state.account_id" : "player_state.account_id",
      nameColumn: "player_state.character_name",
      rows: 0,
      resolvedNames: 0,
      ok: false,
      joinPath: communinetJoinPath,
      error: error.message
    });
    diagnostics.errors.push(`dune.player_state character query: ${error.message}`);
    if (canonicalPlayerSchemaSupported) {
      diagnostics.reason = "The authoritative dune.player_state query failed. Compatibility table scanning was skipped because the canonical player schema is present.";
      return {
        ok: false,
        source: "dune.player_state",
        query,
        players: [],
        diagnostics,
        error: `${diagnostics.reason} ${error.message}`,
        details: playerDiagnosticLines(diagnostics)
      };
    }
    if (query && !numericQuery) {
      diagnostics.reason = "Player name query failed. Refusing to fall back to ID-only player discovery for a non-numeric query.";
      return {
        ok: false,
        source: "dune.player_state",
        query,
        players: [],
        diagnostics,
        error: `${diagnostics.reason} ${error.message}`,
        details: playerDiagnosticLines(diagnostics)
      };
    }
  }
  const metaSql = `
    select table_name || E'\\t' || string_agg(column_name, ',' order by ordinal_position)
    from information_schema.columns
    where table_schema = 'dune'
      and (
        lower(table_name) like '%player%' or
        lower(table_name) like '%character%'
      )
    group by table_name
    order by
      case
        when table_name = 'communinet_player' then 0
        when table_name = 'overmap_players' then 1
        when table_name like '%player%' then 2
        else 3
      end,
      table_name
    limit 40
  `;
  let metaOutput = "";
  try {
    metaOutput = await dbQuery(metaSql);
  } catch (error) {
    diagnostics.reason = "Could not read Dune database metadata.";
    diagnostics.errors.push(error.message);
    return {
      ok: false,
      source: "",
      players: [],
      diagnostics,
      error: diagnostics.reason,
      details: playerDiagnosticLines(diagnostics)
    };
  }
  const idNames = ["player_id", "playerid", "account_id", "accountid", "character_id", "characterid", "id", "uid", "uuid"];
  const nameNames = ["display_name", "displayname", "player_name", "playername", "character_name", "charactername", "name", "username", "nickname"];
  const candidates = metaOutput.split(/\r?\n/).filter(Boolean).map((line) => {
    const [table, columnsRaw = ""] = line.split("\t");
    const columns = columnsRaw.split(",").filter(Boolean);
    const lower = new Map(columns.map((column) => [column.toLowerCase(), column]));
    const idCol = idNames.map((name) => lower.get(name)).find(Boolean) || columns.find((column) => /player.*id|id.*player|character.*id|id$/i.test(column));
    const nameCol = nameNames.map((name) => lower.get(name)).find(Boolean) || columns.find((column) => /display/i.test(column) || (/name/i.test(column) && !/channel|guild|clan|faction|session|server|map/i.test(column)));
    if (!table || !idCol) return null;
    const idExpr = quoteIdent(idCol);
    const nameExpr = nameCol ? `coalesce(${quoteIdent(nameCol)}::text, ${idExpr}::text)` : `${idExpr}::text`;
    return {
      table: `dune.${table}`,
      idColumn: idCol,
      nameColumn: nameCol || "",
      sql: `select distinct ${idExpr}::text, ${nameExpr} from dune.${quoteIdent(table)} where ${idExpr} is not null order by 2 limit 100`
    };
  }).filter(Boolean);

  if (!candidates.length) {
    diagnostics.reason = "No Dune database tables with player-like or character-like columns were found.";
    return {
      ok: true,
      source: "",
      players: [],
      diagnostics,
      error: diagnostics.reason,
      details: playerDiagnosticLines(diagnostics)
    };
  }

  let best = { source: "", players: [] };
  for (const candidate of candidates) {
    const check = {
      type: "database",
      source: candidate.table,
      idColumn: candidate.idColumn,
      nameColumn: candidate.nameColumn || "(id only)",
      rows: 0,
      ok: false
    };
    try {
      const output = await dbQuery(candidate.sql);
      const players = output ? output.split(/\r?\n/).filter(Boolean).map((line) => {
        const [id, name] = line.split("\t");
        return { id: id || "", name: name || id || "Unknown" };
      }) : [];
      check.rows = players.length;
      check.ok = true;
      diagnostics.sourcesChecked.push(check);
      if (players.length > 0) {
        best = { source: candidate.table, players };
        break;
      }
    } catch (error) {
      check.error = error.message;
      diagnostics.sourcesChecked.push(check);
      diagnostics.errors.push(`${candidate.table}: ${error.message}`);
    }
  }

  diagnostics.playersFound = best.players.length;
  if (!best.players.length) {
    diagnostics.reason = "No player rows were found in the checked Dune database tables. Players may need to join once, or their records may be stored in another table not yet recognized.";
  }

  return {
    ok: true,
    source: best.source,
    players: best.players,
    diagnostics,
    error: best.players.length ? "" : diagnostics.reason,
    details: playerDiagnosticLines(diagnostics)
  };
}

const adminPlayerDirectory = createPlayerDirectory({
  freshMs: 15000,
  staleMs: 5 * 60 * 1000,
  load: () => adminPlayers({ limit: 200, hydration: false })
});

async function loadAdminPlayerDirectory(options = {}) {
  const result = await adminPlayerDirectory.get({ force: options.force === true });
  const limit = Math.max(1, Math.min(Number(options.limit || 200) || 200, 200));
  return { ...result, players: result.players.slice(0, limit) };
}

async function playersFeed() {
  const quoteIdent = (value) => `"${String(value).replace(/"/g, '""')}"`;
  const columnOutput = await dbQuery(`
    select table_name || E'\\t' || string_agg(column_name, ',' order by ordinal_position)
    from information_schema.columns
    where table_schema = 'dune'
      and table_name in ('player_state', 'communinet_player', 'accounts')
    group by table_name
  `);
  const tableColumns = new Map(columnOutput.split(/\r?\n/).filter(Boolean).map((line) => {
    const [table = "", columnsRaw = ""] = line.split("\t");
    return [table, new Set(columnsRaw.split(",").filter(Boolean).map((column) => column.toLowerCase()))];
  }));
  const psColumns = tableColumns.get("player_state") || new Set();
  const communinetColumns = tableColumns.get("communinet_player") || new Set();
  const hasCommuninetAccountId = communinetColumns.has("account_id");
  const hasPs = (column) => psColumns.has(column.toLowerCase());
  const firstPsColumn = (columns) => columns.find((column) => hasPs(column));
  const levelColumn = firstPsColumn(["level", "character_level", "player_level", "current_level"]);
  const onlineColumn = firstPsColumn(["is_online", "online", "is_connected", "connected"]);
  const statusColumn = firstPsColumn(["status", "connection_status", "online_status", "presence_status"]);
  const lastSeenColumn = firstPsColumn(["last_avatar_activity", "last_seen", "last_login", "updated_at"]);
  const levelExpr = levelColumn ? `coalesce(ps.${quoteIdent(levelColumn)}::text, '')` : `''`;
  const onlineExpr = onlineColumn
    ? `case
        when ps.${quoteIdent(onlineColumn)} is null then ''
        when lower(ps.${quoteIdent(onlineColumn)}::text) in ('true','t','1','yes','online','connected','active') then 'online'
        when lower(ps.${quoteIdent(onlineColumn)}::text) in ('false','f','0','no','offline','disconnected','inactive') then 'offline'
        else ps.${quoteIdent(onlineColumn)}::text
      end`
    : `''`;
  const statusExpr = statusColumn ? `coalesce(ps.${quoteIdent(statusColumn)}::text, '')` : `''`;
  const lastSeenExpr = lastSeenColumn ? `coalesce(ps.${quoteIdent(lastSeenColumn)}::text, '')` : `''`;
  const playerStateOrder = lastSeenColumn ? `ps.${quoteIdent(lastSeenColumn)} desc nulls last,` : "";
  const communinetAccountSource = hasCommuninetAccountId
    ? "select account_id from dune.communinet_player where account_id is not null union"
    : "";
  const feedQuery = `
    with account_ids as (
      ${communinetAccountSource}
      select account_id from dune.player_state where account_id is not null
    )
    select
      a.account_id::text,
      coalesce(ac."user", '') as fls_id,
      coalesce(ac.funcom_id, '') as funcom_id,
      coalesce(ps.player_controller_id::text, '') as player_controller_id,
      coalesce(ps.player_state_id::text, ps.player_pawn_id::text, ps.player_controller_id::text, '') as character_id,
      coalesce(nullif(ps.character_name, ''), a.account_id::text) as character_name,
      ${levelExpr} as level,
      ${onlineExpr} as online_state,
      ${statusExpr} as status_text,
      ${lastSeenExpr} as last_seen
    from account_ids a
    left join dune.player_state ps on ps.account_id = a.account_id
    left join dune.accounts ac on ac.id = a.account_id
    order by a.account_id, ${playerStateOrder} ps.player_state_id
    limit 120
  `;
  const output = await dbQuery(feedQuery);
  const seen = new Set();
  const players = output ? output.split(/\r?\n/).filter(Boolean).map((line) => {
    const [accountId = "", flsId = "", funcomId = "", playerControllerId = "", characterId = "", characterName = "", level = "", onlineState = "", statusText = "", lastSeen = ""] = line.split("\t");
    const rawStatus = String(onlineState || statusText || "").toLowerCase();
    let status = "unknown";
    if (/online|connected|active|true|1/.test(rawStatus)) status = "online";
    else if (/offline|disconnected|inactive|false|0/.test(rawStatus)) status = "offline";
    return {
      id: accountId,
      name: characterName || accountId || "Unknown",
      account_id: accountId,
      fls_id: flsId,
      funcom_id: funcomId,
      player_controller_id: playerControllerId,
      character_id: characterId,
      level: level || null,
      status,
      statusSource: onlineColumn || statusColumn || "",
      last_seen: lastSeen || null
    };
  }).filter((player) => {
    const key = player.account_id || player.id;
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  }) : [];
  return {
    ok: true,
    source: "dune.communinet_player + dune.player_state",
    players,
    fields: {
      level: levelColumn || "",
      status: onlineColumn || statusColumn || "",
      lastSeen: lastSeenColumn || ""
    }
  };
}

function liveMapNormalizeStatus(value) {
  const raw = String(value || "").toLowerCase();
  if (/online|connected|active|true|1/.test(raw)) return "online";
  if (/offline|disconnected|inactive|false|0/.test(raw)) return "offline";
  return raw || "unknown";
}

function liveMapNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

// Shared map model: actor world X/Y maps linearly to a 4096 image plane. Pixel X grows
// left-to-right and pixel Y grows top-to-bottom. Hagga Basin reverses world Y so movement
// direction matches the calibrated image. Live Map and Teleport both use this module.
const LIVE_MAP_WORLD_BOUNDS = Coordinates.MAP_CONFIGS;

function liveMapBoundsForRow(row) {
  return Coordinates.mapConfig(row.map);
}

function liveMapCoordinateRejectReason(row) {
  if (row.x === null && row.y === null) return "x/y are not finite numbers";
  if (row.x === null) return "x is not a finite number";
  if (row.y === null) return "y is not a finite number";
  const bounds = liveMapBoundsForRow(row);
  if (bounds && !Coordinates.withinBounds(row, bounds)) return "coordinates outside configured map bounds";
  return "";
}

function liveMapCoordinateDebug(rawRows, normalizedRows) {
  const rejected = normalizedRows
    .map((row) => ({ row, reason: liveMapCoordinateRejectReason(row) }))
    .filter((entry) => entry.reason);
  const finiteRows = normalizedRows.filter((row) => row.x !== null && row.y !== null);
  const xs = finiteRows.map((row) => row.x);
  const ys = finiteRows.map((row) => row.y);
  const reasonCounts = rejected.reduce((acc, entry) => {
    acc[entry.reason] = (acc[entry.reason] || 0) + 1;
    return acc;
  }, {});
  return {
    rawRowCount: rawRows.length,
    acceptedCoordinateCount: finiteRows.length,
    rejectedCoordinateCount: rejected.length,
    rejectedReasons: reasonCounts,
    rejectedSamples: rejected.slice(0, 5).map((entry) => ({ reason: entry.reason, id: entry.row.id, name: entry.row.name, x: entry.row.x, y: entry.row.y, z: entry.row.z, map: entry.row.map })),
    finiteCoordinates: finiteRows.length === normalizedRows.length,
    minX: xs.length ? Math.min(...xs) : null,
    maxX: xs.length ? Math.max(...xs) : null,
    minY: ys.length ? Math.min(...ys) : null,
    maxY: ys.length ? Math.max(...ys) : null,
    sample: finiteRows[0] || normalizedRows[0] || null
  };
}

let liveMapResourceDatasetCache = null;
function loadKnownResourceSpawnLocations() {
  if (liveMapResourceDatasetCache) return liveMapResourceDatasetCache;
  const payload = JSON.parse(fs.readFileSync(DUNE_RESOURCE_SPAWN_LOCATIONS_PATH, "utf8"));
  const map = String(payload.map || "");
  const bounds = Coordinates.mapConfig(map);
  if (map !== "HaggaBasin" || !Array.isArray(payload.locations)) throw new Error("Known resource spawn dataset must contain Hagga Basin locations.");
  const counts = { smallSpice: 0, flourSand: 0, total: payload.locations.length };
  const rows = payload.locations.map((entry, index) => {
    const keys = Object.keys(entry).sort().join(",");
    if (keys !== "name,x,y,z") throw new Error(`Known resource spawn row ${index + 1} contains unsupported packaged fields.`);
    const name = String(entry.name || "");
    const resourceType = name === "Small Spice" ? "small-spice" : name === "Flour Sand" ? "flour-sand" : "";
    const x = Number(entry.x);
    const y = Number(entry.y);
    const z = Number(entry.z);
    if (!resourceType || ![x, y, z].every(Number.isFinite)) throw new Error(`Known resource spawn row ${index + 1} is invalid.`);
    if (!Coordinates.withinBounds({ x, y }, bounds)) throw new Error(`Known resource spawn row ${index + 1} is outside Hagga Basin bounds.`);
    if (resourceType === "small-spice") counts.smallSpice += 1;
    else counts.flourSand += 1;
    return {
      id: `known-resource-${index + 1}`,
      type: "resource",
      resourceType,
      name,
      map,
      x,
      y,
      z,
      status: "Possible spawn location; current activity is not proven.",
      staticSpawnLocation: true
    };
  });
  if (counts.total !== 117 || counts.smallSpice !== 87 || counts.flourSand !== 30) throw new Error(`Known resource spawn dataset count mismatch: expected 87 Small Spice and 30 Flour Sand, received ${counts.smallSpice} and ${counts.flourSand}.`);
  liveMapResourceDatasetCache = { rows, counts, provenance: payload.provenance || {}, map };
  return liveMapResourceDatasetCache;
}

let experimentalResourceAreaPaksDirLoaded = false;
let experimentalResourceAreaPaksDirOverride = "";

function configuredExperimentalResourceAreaPaksDir() {
  const environmentPath = String(process.env.ALPHANINE_DUNE_PAKS_DIR || "").trim();
  if (environmentPath) return environmentPath;
  if (!experimentalResourceAreaPaksDirLoaded) {
    experimentalResourceAreaPaksDirLoaded = true;
    try {
      const saved = JSON.parse(fs.readFileSync(EXPERIMENTAL_RESOURCE_AREA_SETTINGS_PATH, "utf8"));
      experimentalResourceAreaPaksDirOverride = String(saved?.paksDir || "").trim();
    } catch (error) {
      if (error?.code !== "ENOENT") console.warn(`Experimental Resource Areas settings could not be read: ${error.message || error}`);
    }
  }
  return experimentalResourceAreaPaksDirOverride;
}

function saveExperimentalResourceAreaGameFolder(selectedFolder) {
  const selected = String(selectedFolder || "").trim();
  if (!selected) throw new Error("Select the Dune Awakening game folder first.");
  const paksDir = ExperimentalResourceAreas.findPaksDirectory(selected);
  fs.mkdirSync(path.dirname(EXPERIMENTAL_RESOURCE_AREA_SETTINGS_PATH), { recursive: true });
  const temporary = `${EXPERIMENTAL_RESOURCE_AREA_SETTINGS_PATH}.${process.pid}.tmp`;
  fs.writeFileSync(temporary, `${JSON.stringify({ schemaVersion: 1, paksDir }, null, 2)}\n`, "utf8");
  fs.renameSync(temporary, EXPERIMENTAL_RESOURCE_AREA_SETTINGS_PATH);
  experimentalResourceAreaPaksDirLoaded = true;
  experimentalResourceAreaPaksDirOverride = paksDir;
  return paksDir;
}

function experimentalResourceAreaOptions() {
  return {
    paksDir: configuredExperimentalResourceAreaPaksDir(),
    buildId: process.env.ALPHANINE_DUNE_BUILD_ID || ""
  };
}

function experimentalResourceAreaStatus() {
  const result = ExperimentalResourceAreas.status(EXPERIMENTAL_RESOURCE_AREA_CACHE_DIR, {
    ...experimentalResourceAreaOptions()
  });
  return {
    ...result,
    disabledByDefault: true,
    semantics: "Procedural distribution data; not exact nodes or guaranteed spawns.",
    intensityLabel: "Heatmap intensity",
    overlayUrlTemplate: result.cacheKey ? `/api/live-map/resource-areas/overlay/${result.cacheKey}/source-top-max-y/{resource}.png` : ""
  };
}

function generateExperimentalResourceAreas() {
  ExperimentalResourceAreas.generate({
    cacheDir: EXPERIMENTAL_RESOURCE_AREA_CACHE_DIR,
    ...experimentalResourceAreaOptions(),
    repakExe: process.env.ALPHANINE_REPAK_EXE || "",
    appDir: __dirname
  });
  return experimentalResourceAreaStatus();
}

function selectExperimentalResourceAreaGameFolder(selectedFolder) {
  const paksDir = saveExperimentalResourceAreaGameFolder(selectedFolder);
  return { ...experimentalResourceAreaStatus(), selectedGamePath: path.resolve(selectedFolder), paksDir };
}

function normalizeLiveMapActorRow(row, type, fallbackName) {
  const x = liveMapNumber(row.x);
  const y = liveMapNumber(row.y);
  const z = liveMapNumber(row.z);
  const map = row.map || "HaggaBasin";
  const normalized = {
    id: row.id || `${type}-${row.actor_id || row.base_id || row.vehicle_id || ""}`,
    type,
    name: row.name || fallbackName || row.id || type,
    x,
    y,
    z,
    status: type === "player" ? liveMapNormalizeStatus(row.status || row.online_status) : (row.status || row.online_status || "active"),
    updatedAt: row.updated_at || row.updatedAt || "",
    actor_id: row.actor_id || row.id || "",
    character_name: row.character_name || "",
    account_id: row.account_id || "",
    fls_id: row.fls_id || "",
    funcom_id: row.funcom_id || "",
    player_controller_id: row.player_controller_id || "",
    pawn_entity_id: row.pawn_entity_id || row.actor_id || "",
    hydration: row.hydration || extractHydrationFromGasAttributes(row.gas_attributes || null, { pawnActorId: row.pawn_entity_id || row.actor_id || "" }),
    online: liveMapNormalizeStatus(row.status || row.online_status),
    online_status: row.status || row.online_status || "",
    map,
    partition_id: liveMapNumber(row.partition_id),
    hasPosition: x !== null && y !== null,
    source: row.source || "dune.actors.transform"
  };
  const mapPosition = x === null || y === null ? null : Coordinates.worldToMapPoint({ x, y }, map, { clamp: false });
  normalized.coordinateDebug = {
    rawDbPosition: { x, y, z },
    transformedMapPosition: mapPosition,
    sourceCoordinateFields: "((dune.actors.transform).location).x/y/z",
    sourceTable: normalized.source,
    elevationSource: "actor-transform-exact-only"
  };
  return normalized;
}

async function liveMapActorsTransformPlayers() {
  const sql = `
    select a.id::text as id,
           a.id::text as actor_id,
           coalesce(ps.player_pawn_id::text, a.id::text) as pawn_entity_id,
           coalesce(ps.account_id::text, a.owner_account_id::text, '') as account_id,
           coalesce(ac."user", '') as fls_id,
           coalesce(ac.funcom_id, '') as funcom_id,
           coalesce(ps.player_controller_id::text, '') as player_controller_id,
           coalesce(nullif(ps.character_name, ''), ac."user", a.id::text) as name,
           coalesce(nullif(ps.character_name, ''), '') as character_name,
           coalesce(ps.online_status::text, 'Offline') as status,
           (((a.transform).location).x)::double precision as x,
           (((a.transform).location).y)::double precision as y,
           (((a.transform).location).z)::double precision as z,
           coalesce(a.map, 'HaggaBasin') as map,
           coalesce(a.partition_id, 0)::text as partition_id,
           coalesce(ps.last_avatar_activity::text, '') as updated_at,
           coalesce(a.gas_attributes::text, '') as gas_attributes,
           'dune.actors transform / player_state.player_pawn_id' as source
    from dune.actors a
    join dune.player_state ps on ps.player_pawn_id = a.id
    join dune.world_partition wp on wp.partition_id = a.partition_id and nullif(wp.server_id, '') is not null
    left join dune.accounts ac on ac.id = ps.account_id
    where a.transform is not null
      and ((a.transform).location).x is not null
      and ((a.transform).location).y is not null
    order by coalesce(ps.online_status::text, '') desc, lower(coalesce(ps.character_name, '')), a.id
    limit 500
  `;
  const query = await liveMapPgQuery(sql, 30000);
  const rows = query.rows;
  const normalized = rows.map((row) => normalizeLiveMapActorRow(row, "player", "Player"));
  return { rows: normalized.filter((row) => row.hasPosition), debug: liveMapCoordinateDebug(rows, normalized), db: query.db, durationMs: query.durationMs };
}

async function liveMapActorsTransformVehicles() {
  const sql = `
    select a.id::text as id,
           a.id::text as actor_id,
           coalesce(nullif(a.class, ''), 'Vehicle ' || a.id::text) as name,
           (((a.transform).location).x)::double precision as x,
           (((a.transform).location).y)::double precision as y,
           (((a.transform).location).z)::double precision as z,
           coalesce(a.map, 'HaggaBasin') as map,
           coalesce(a.partition_id, 0)::text as partition_id,
           '' as updated_at,
           'dune.vehicles + dune.actors.transform' as source
    from dune.vehicles v
    join dune.actors a on a.id = v.id
    join dune.world_partition wp on wp.partition_id = a.partition_id and nullif(wp.server_id, '') is not null
    where a.transform is not null
      and ((a.transform).location).x is not null
      and ((a.transform).location).y is not null
    order by a.map, a.partition_id, a.id
    limit 500
  `;
  const query = await liveMapPgQuery(sql, 30000);
  const rows = query.rows;
  const normalized = rows.map((row) => normalizeLiveMapActorRow(row, "vehicle", "Vehicle"));
  return { rows: normalized.filter((row) => row.hasPosition), debug: liveMapCoordinateDebug(rows, normalized), db: query.db, durationMs: query.durationMs };
}

async function liveMapActorsTransformBases() {
  const sql = `
    select b.id::text as id,
           a.id::text as actor_id,
           coalesce(nullif(pa.actor_name, ''), nullif(a.class, ''), 'Base ' || b.id::text) as name,
           (((a.transform).location).x)::double precision as x,
           (((a.transform).location).y)::double precision as y,
           (((a.transform).location).z)::double precision as z,
           coalesce(a.map, 'HaggaBasin') as map,
           coalesce(a.partition_id, 0)::text as partition_id,
           '' as updated_at,
           'dune.buildings + building_instances + actor_fgl_entities + actors.transform' as source
    from dune.buildings b
    join dune.building_instances bi on bi.building_id = b.id
    join dune.actor_fgl_entities afe on afe.entity_id = bi.owner_entity_id
    join dune.actors a on a.id = afe.actor_id
    join dune.world_partition wp on wp.partition_id = a.partition_id and nullif(wp.server_id, '') is not null
    left join dune.permission_actor pa on pa.actor_id = a.id
    where a.transform is not null
      and ((a.transform).location).x is not null
      and ((a.transform).location).y is not null
    group by b.id, pa.actor_name, a.id, a.map, a.partition_id, a.class, a.transform
    order by a.map, a.partition_id, b.id
    limit 500
  `;
  const query = await liveMapPgQuery(sql, 30000);
  const rows = query.rows;
  const normalized = rows.map((row) => normalizeLiveMapActorRow(row, "base", "Base"));
  return { rows: normalized.filter((row) => row.hasPosition), debug: liveMapCoordinateDebug(rows, normalized), db: query.db, durationMs: query.durationMs };
}

function liveMapConfigPayload() {
  const defaultMap = Coordinates.mapConfig(loadConfig().mapDefault).key;
  const defaultConfig = LIVE_MAP_WORLD_BOUNDS[defaultMap] || LIVE_MAP_WORLD_BOUNDS.HaggaBasin;
  const defaultImage = defaultMap === "HaggaBasin" ? "/assets/hagga-basin-map.png" : defaultMap === "DeepDesert" ? "/assets/deep-desert-map.png" : "/assets/world-map-overland.png";
  return {
    map: { ...defaultConfig, actorMap: defaultMap, image: defaultImage, fallbackImage: "/assets/world-map-overland.png" },
    maps: {
      HaggaBasin: { ...LIVE_MAP_WORLD_BOUNDS.HaggaBasin, actorMap: "HaggaBasin", image: "/assets/hagga-basin-map.png", fallbackImage: "/assets/world-map-overland.png" },
      DeepDesert: { ...LIVE_MAP_WORLD_BOUNDS.DeepDesert, actorMap: "DeepDesert", image: "/assets/deep-desert-map.png", fallbackImage: "/assets/world-map-overland.png" }
    },
    defaultMap
  };
}

function liveMapDebugFromLayers(layers, diagnostics, db = null, errors = []) {
  const all = [...(layers.players || []), ...(layers.vehicles || []), ...(layers.bases || []), ...(layers.resources || [])];
  const xs = all.map((row) => row.x).filter((value) => value !== null && Number.isFinite(Number(value)));
  const ys = all.map((row) => row.y).filter((value) => value !== null && Number.isFinite(Number(value)));
  const rejectedCoordinateCount = Object.values(diagnostics).reduce((sum, item) => sum + Number(item?.rejectedCoordinateCount || 0), 0);
  const errorDebug = errors.map((error) => error.debug).find(Boolean) || {};
  const source = db || errorDebug || {};
  const tunnel = source.tunnel || {};
  const lastDbError = errors.map((error) => error.message || String(error)).find(Boolean) || "";
  return {
    ok: !errors.length,
    dbConnected: Boolean(db && !errors.length),
    connectionSource: source.connectionSource || source.resolvedSource || "unknown",
    resolvedSource: source.resolvedSource || source.connectionSource || "unknown",
    didCallGetVM: false,
    manualDbConfigExists: Boolean(source.manualDbConfigExists || source.configured),
    configuredDbHost: source.configuredDbHost || source.host || "",
    configuredDbPort: source.configuredDbPort || source.port || tunnel.port || "",
    configuredDbName: source.configuredDbName || source.database || "",
    configuredDbUser: source.configuredDbUser || source.user || "",
    usedHost: source.host || tunnel.host || source.configuredDbHost || "",
    usedPort: source.port || tunnel.port || source.configuredDbPort || "",
    tunnelExpected: Boolean(source.tunnelExpected || tunnel.localTunnelExpected),
    tunnelListening: Boolean(source.tunnelListening || tunnel.running),
    tunnelPid: source.tunnelPid || tunnel.pid || "",
    tunnelState: source.tunnelState || tunnel.state || "idle",
    tunnelLastError: source.tunnelLastError || tunnel.lastError || "",
    tunnelAttemptCount: Number(source.tunnelAttemptCount || tunnel.attemptCount || 0),
    lastDbError,
    rowCounts: {
      players: layers.players.length,
      vehicles: layers.vehicles.length,
      bases: layers.bases.length,
      resources: (layers.resources || []).length
    },
    rawDbRowCounts: {
      players: diagnostics.players?.rawRowCount || 0,
      vehicles: diagnostics.vehicles?.rawRowCount || 0,
      bases: diagnostics.bases?.rawRowCount || 0
    },
    rejectedCoordinateCount,
    coordinateDiagnostics: diagnostics,
    coordinateRange: {
      minX: xs.length ? Math.min(...xs) : null,
      maxX: xs.length ? Math.max(...xs) : null,
      minY: ys.length ? Math.min(...ys) : null,
      maxY: ys.length ? Math.max(...ys) : null
    },
    bounds: LIVE_MAP_WORLD_BOUNDS.HaggaBasin,
    maps: liveMapConfigPayload().maps,
    outsideBoundsWarning: Object.values(diagnostics).some((item) => item?.rejectedReasons?.["coordinates outside configured map bounds"]),
    dbUnavailableMessage: lastDbError ? (source.tunnelLastError || tunnel.lastError || lastDbError) : "",
    errors: errors.map((error) => error.message || String(error))
  };
}

function liveMapDemoMarkersPayload() {
  const generatedAt = new Date().toISOString();
  const resourceDataset = loadKnownResourceSpawnLocations();
  const layers = {
    players: [
      { id: "debug-player-1", type: "player", name: "Debug Player", x: -102400, y: -80600, z: 312, status: "debug", updatedAt: generatedAt, actor_id: "debug-player-1", map: "HaggaBasin", hasPosition: true, source: "debugMarkers=1" }
    ],
    vehicles: [
      { id: "debug-vehicle-1", type: "vehicle", name: "Debug Vehicle", x: 54200, y: -121500, z: 304, status: "debug", updatedAt: generatedAt, actor_id: "debug-vehicle-1", map: "HaggaBasin", hasPosition: true, source: "debugMarkers=1" }
    ],
    bases: [
      { id: "debug-base-1", type: "base", name: "Debug Base", x: -248000, y: 118000, z: 289, status: "debug", updatedAt: generatedAt, actor_id: "debug-base-1", map: "HaggaBasin", hasPosition: true, source: "debugMarkers=1" }
    ],
    resources: resourceDataset.rows
  };
  const diagnostics = {
    players: liveMapCoordinateDebug(layers.players, layers.players),
    vehicles: liveMapCoordinateDebug(layers.vehicles, layers.vehicles),
    bases: liveMapCoordinateDebug(layers.bases, layers.bases)
  };
  const rows = [...layers.players, ...layers.vehicles, ...layers.bases, ...layers.resources];
  const debug = liveMapDebugFromLayers(layers, diagnostics, null, []);
  return {
    ok: true,
    generatedAt,
    demo: true,
    message: "Debug marker mode adds fake player, vehicle, and base markers for UI validation. Resource markers remain the bundled static known spawn locations.",
    layers,
    rows,
    bounds: { minX: Math.min(...rows.map((row) => row.x)), maxX: Math.max(...rows.map((row) => row.x)), minY: Math.min(...rows.map((row) => row.y)), maxY: Math.max(...rows.map((row) => row.y)) },
    resourceCounts: resourceDataset.counts,
    resourceProvenance: resourceDataset.provenance,
    sources: [{ kind: "debug", table: "debugMarkers=1", status: "fake", rows: 3, coordinateRows: 3 }, { kind: "resources", table: "bundled known spawn locations", status: "static", rows: resourceDataset.rows.length, coordinateRows: resourceDataset.rows.length, coordinates: "world X/Y/Z; existing Suite conversion" }],
    errors: [],
    debug: { ...debug, dbConnected: false, connectionSource: "debug-markers", resolvedSource: "debug-markers", debugMarkers: true, dbUnavailableMessage: "" },
    ...liveMapConfigPayload()
  };
}

async function liveMapLayer(kind) {
  if (kind === "players") return await liveMapActorsTransformPlayers();
  if (kind === "vehicles") return await liveMapActorsTransformVehicles();
  if (kind === "bases") return await liveMapActorsTransformBases();
  throw new Error("Unknown Live Map layer.");
}

async function liveMapMarkersPayload() {
  const resourceDataset = loadKnownResourceSpawnLocations();
  const result = {
    ok: true,
    generatedAt: new Date().toISOString(),
    layers: { players: [], vehicles: [], bases: [], resources: resourceDataset.rows },
    resourceCounts: resourceDataset.counts,
    resourceProvenance: resourceDataset.provenance,
    rows: [],
    sources: [],
    errors: [],
    bounds: null,
    debug: {}
  };
  const diagnostics = { players: null, vehicles: null, bases: null, resources: liveMapCoordinateDebug(resourceDataset.rows, resourceDataset.rows) };
  const errors = [];
  let db = null;
  result.sources.push({ kind: "resources", table: "bundled known spawn locations", status: "static", rows: resourceDataset.rows.length, coordinateRows: resourceDataset.rows.length, coordinates: "world X/Y/Z; existing Suite conversion" });
  try {
    const players = await liveMapActorsTransformPlayers();
    result.layers.players = players.rows;
    diagnostics.players = players.debug;
    db = db || players.db;
    result.sources.push({ kind: "players", table: "dune.actors + dune.player_state + dune.world_partition", status: result.layers.players.length ? "real" : "empty", rows: result.layers.players.length, coordinateRows: result.layers.players.length, join: "ps.player_pawn_id = actors.id; active world_partition.partition_id = actors.partition_id", coordinates: "((actors.transform).location).x/y/z" });
  } catch (error) {
    errors.push(error);
    result.errors.push(`players transform query: ${error.message}`);
    result.sources.push({ kind: "players", table: "dune.actors + dune.player_state", status: "unavailable", rows: 0, coordinateRows: 0, join: "ps.player_pawn_id = actors.id", coordinates: "((actors.transform).location).x/y/z", error: error.message });
  }
  try {
    const vehicles = await liveMapActorsTransformVehicles();
    result.layers.vehicles = vehicles.rows;
    diagnostics.vehicles = vehicles.debug;
    db = db || vehicles.db;
    result.sources.push({ kind: "vehicles", table: "dune.vehicles + dune.actors + dune.world_partition", status: result.layers.vehicles.length ? "real" : "empty", rows: result.layers.vehicles.length, coordinateRows: result.layers.vehicles.length, join: "actors.id = vehicles.id; active world_partition.partition_id = actors.partition_id", coordinates: "((actors.transform).location).x/y/z" });
  } catch (error) {
    errors.push(error);
    result.errors.push(`vehicles transform query: ${error.message}`);
    result.sources.push({ kind: "vehicles", table: "dune.vehicles + dune.actors", status: "unavailable", rows: 0, coordinateRows: 0, join: "actors.id = vehicles.id", coordinates: "((actors.transform).location).x/y/z", error: error.message });
  }
  try {
    const bases = await liveMapActorsTransformBases();
    result.layers.bases = bases.rows;
    diagnostics.bases = bases.debug;
    db = db || bases.db;
    result.sources.push({ kind: "bases", table: "dune.buildings + dune.building_instances + dune.actor_fgl_entities + dune.actors + dune.permission_actor + dune.world_partition", status: result.layers.bases.length ? "real" : "empty", rows: result.layers.bases.length, coordinateRows: result.layers.bases.length, join: "building_instances.owner_entity_id = actor_fgl_entities.entity_id; actors.id = actor_fgl_entities.actor_id; active world_partition.partition_id = actors.partition_id", coordinates: "((actors.transform).location).x/y/z" });
  } catch (error) {
    errors.push(error);
    result.errors.push(`bases transform query: ${error.message}`);
    result.sources.push({ kind: "bases", table: "dune.buildings + dune.building_instances + dune.actor_fgl_entities + dune.actors", status: "unavailable", rows: 0, coordinateRows: 0, join: "building_instances.owner_entity_id = actor_fgl_entities.entity_id; actors.id = actor_fgl_entities.actor_id", coordinates: "((actors.transform).location).x/y/z", error: error.message });
  }
  const allPoints = [...result.layers.players, ...result.layers.vehicles, ...result.layers.bases, ...result.layers.resources];
  if (allPoints.length) {
    const xs = allPoints.map((row) => row.x);
    const ys = allPoints.map((row) => row.y);
    result.bounds = { minX: Math.min(...xs), maxX: Math.max(...xs), minY: Math.min(...ys), maxY: Math.max(...ys) };
  }
  result.rows = allPoints;
  result.debug = liveMapDebugFromLayers(result.layers, diagnostics, db, errors);
  return { ...result, ...liveMapConfigPayload() };
}

function normalizeTeleportPlayerState(row) {
  if (!row) return null;
  const dbNumber = (value) => value === null || value === undefined || String(value).trim() === "" ? null : Number(value);
  const partitionId = Number(row.partition_id);
  const state = {
    playerId: String(row.player_id || row.fls_id || row.player_controller_id || row.account_id || "").trim(),
    playerName: String(row.character_name || row.fls_id || row.account_id || "").trim(),
    actorId: String(row.actor_id || "").trim(),
    accountId: String(row.account_id || "").trim(),
    flsId: String(row.fls_id || "").trim(),
    playerControllerId: String(row.player_controller_id || "").trim(),
    map: String(row.map || "").trim(),
    partitionId: Number.isInteger(partitionId) ? partitionId : null,
    partitionActive: String(row.partition_active || "").toLowerCase() === "true",
    x: dbNumber(row.x),
    y: dbNumber(row.y),
    z: dbNumber(row.z),
    onlineStatus: String(row.online_status || "").trim(),
    source: "dune.player_state + dune.actors + dune.world_partition"
  };
  state.positionValid = [state.x, state.y, state.z].every(Number.isFinite);
  state.partitionValid = Number.isInteger(state.partitionId) && state.partitionId > 0 && state.partitionActive;
  return state;
}

async function resolveTeleportPlayerState(identity, role = "source") {
  const value = String(identity || "").trim();
  if (!value) throw new Error(`Teleport ${role} player is not selected.`);
  const exact = sqlString(value);
  const sql = `
    select
      coalesce(nullif(ac."user", ''), ps.player_controller_id::text, ps.account_id::text, '') as player_id,
      coalesce(nullif(ps.character_name, ''), nullif(ac."user", ''), ps.account_id::text, '') as character_name,
      coalesce(ps.player_pawn_id::text, '') as actor_id,
      coalesce(ps.account_id::text, '') as account_id,
      coalesce(ac."user", '') as fls_id,
      coalesce(ps.player_controller_id::text, '') as player_controller_id,
      coalesce(a.map, '') as map,
      a.partition_id::text as partition_id,
      case when wp.partition_id is not null and nullif(wp.server_id, '') is not null then 'true' else 'false' end as partition_active,
      (((a.transform).location).x)::double precision as x,
      (((a.transform).location).y)::double precision as y,
      (((a.transform).location).z)::double precision as z,
      coalesce(ps.online_status::text, '') as online_status
    from dune.player_state ps
    join dune.actors a on a.id = ps.player_pawn_id
    left join dune.accounts ac on ac.id = ps.account_id
    left join dune.world_partition wp on wp.partition_id = a.partition_id
    where ps.player_pawn_id::text = ${exact}
       or ps.player_controller_id::text = ${exact}
       or ps.player_state_id::text = ${exact}
       or ps.account_id::text = ${exact}
       or lower(coalesce(ps.character_name, '')) = lower(${exact})
       or lower(coalesce(ac."user", '')) = lower(${exact})
       or coalesce(ac.funcom_id, '') = ${exact}
    order by
      case when ps.player_pawn_id::text = ${exact} then 0
           when ps.player_controller_id::text = ${exact} then 1
           when lower(coalesce(ac."user", '')) = lower(${exact}) then 2
           else 3 end,
      ps.last_avatar_activity desc nulls last
    limit 1
  `;
  const query = await liveMapPgQuery(sql, 15000);
  const state = normalizeTeleportPlayerState(query.rows?.[0]);
  if (!state?.actorId) throw new Error(`Teleport ${role} player could not be resolved to a current pawn actor from the database.`);
  return state;
}

function teleportStateSummary(state) {
  if (!state) return null;
  return {
    playerId: state.playerId,
    playerName: state.playerName,
    actorId: state.actorId,
    map: state.map,
    partitionId: state.partitionId,
    partitionActive: state.partitionActive,
    x: state.x,
    y: state.y,
    z: state.z,
    onlineStatus: state.onlineStatus,
    source: state.source
  };
}

async function liveMapTeleportPreview(payload) {
  const preview = await liveMapTeleportRequest({ ...payload, requestMode: "preview" }, { dryRun: true, test: true, execution: false });
  return {
    ok: true,
    status: "preview",
    message: preview.canExecute
      ? "Teleport preview resolved from current database state. No live teleport command was sent."
      : "Teleport preview created, but execution is blocked until the required target state is resolved.",
    ...preview
  };
}

function receiverHttpAuthToken(configValue = loadConfig()) {
  return String(
    configValue.receiverToken
    || LIVE_GIVE_ENV.httpToken
    || process.env.DUNE_RECEIVER_TOKEN
    || process.env.DUNE_ADMIN_GIVE_ITEM_TOKEN
    || ""
  ).trim();
}

function receiverHttpAuthSource(configValue = loadConfig()) {
  if (configValue.receiverToken) return "config.receiverToken";
  if (LIVE_GIVE_ENV.httpToken) return "DUNE_ADMIN_GIVE_ITEM_TOKEN";
  if (process.env.DUNE_RECEIVER_TOKEN) return "DUNE_RECEIVER_TOKEN";
  if (process.env.DUNE_ADMIN_GIVE_ITEM_TOKEN) return "DUNE_ADMIN_GIVE_ITEM_TOKEN";
  return "none";
}

function teleportReceiverUrl(configValue = loadConfig()) {
  const receiver = receiverUrls(configValue);
  const pathPart = String(configValue.teleportEndpointPath || "/teleport").trim() || "/teleport";
  const endpointPath = pathPart.startsWith("/") ? pathPart : `/${pathPart}`;
  return `http://${receiver.host}:${receiver.port}${endpointPath}`;
}

function renderTeleportTemplate(template, values) {
  return String(template || "").replace(/\{([A-Za-z0-9_]+)\}/g, (whole, key) => (
    Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : whole
  ));
}

function readTeleportPresetRows(filePath) {
  if (!fs.existsSync(filePath)) return [];
  const raw = JSON.parse(fs.readFileSync(filePath, "utf8").replace(/^\uFEFF/, ""));
  return Array.isArray(raw) ? raw : Array.isArray(raw.presets) ? raw.presets : [];
}

function normalizeTeleportPreset(row, origin) {
  if (!row || row.enabled === false || row.verified !== true) return null;
  const x = Number(row.x), y = Number(row.y), z = Number(row.z);
  const partitionId = Number(row.partition_id ?? row.partitionId ?? 0);
  const preset = {
    name: String(row.name || "").trim(),
    map: String(row.map || "HaggaBasin").trim(),
    x,
    y,
    z,
    partition_id: Number.isFinite(partitionId) ? Math.trunc(partitionId) : 0,
    verified: true,
    source: String(row.source || "verified-location").trim(),
    source_actor_id: String(row.source_actor_id || "").trim(),
    source_player_name: String(row.source_player_name || "").trim(),
    created_at: String(row.created_at || "").trim(),
    origin
  };
  if (!preset.name || ![preset.x, preset.y, preset.z].every(Number.isFinite) || preset.z === 0) return null;
  if (!Coordinates.withinBounds(preset, preset.map)) return null;
  return preset;
}

function loadTeleportLocationPresets() {
  try {
    const bundled = readTeleportPresetRows(BUNDLED_TELEPORT_PRESETS_PATH).map((row) => normalizeTeleportPreset(row, "bundled")).filter(Boolean);
    const saved = readTeleportPresetRows(TELEPORT_PRESETS_PATH).map((row) => normalizeTeleportPreset(row, "saved")).filter(Boolean);
    const byName = new Map();
    for (const preset of [...bundled, ...saved]) byName.set(preset.name.toLowerCase(), preset);
    return { ok: true, presets: [...byName.values()], path: TELEPORT_PRESETS_PATH, bundledPath: BUNDLED_TELEPORT_PRESETS_PATH };
  } catch (error) {
    return { ok: false, presets: [], path: TELEPORT_PRESETS_PATH, bundledPath: BUNDLED_TELEPORT_PRESETS_PATH, error: error.message };
  }
}

function teleportPlayerRowMatches(row, value) {
  const expected = String(value || "").trim();
  if (!expected) return false;
  return [row.id, row.actor_id, row.pawn_entity_id, row.fls_id, row.funcom_id, row.player_controller_id, row.account_id]
    .some((candidate) => String(candidate || "").trim() === expected);
}

async function saveCurrentPlayerTeleportPreset(payload) {
  if (payload.confirmed !== true) throw new Error("Confirm that the player is standing at a safe location before saving the preset.");
  const name = String(payload.name || "").trim();
  if (!name || name.length > 80 || /[\u0000-\u001f]/.test(name)) throw new Error("Preset name must be between 1 and 80 printable characters.");
  const actorId = String(payload.actorId || "").trim();
  const playerId = String(payload.playerId || "").trim();
  const layer = await liveMapActorsTransformPlayers();
  const player = layer.rows.find((row) => (actorId && String(row.actor_id || row.id) === actorId) || teleportPlayerRowMatches(row, playerId));
  if (!player) throw new Error("Current player position could not be verified. Refresh Live Map and select the player again.");
  if (liveMapNormalizeStatus(player.status || player.online_status) !== "online") throw new Error("Only a currently online player position can be saved as a safe preset.");
  if (![player.x, player.y, player.z].every((value) => Number.isFinite(Number(value))) || Number(player.z) === 0) {
    throw new Error("Current player position does not include a safe X/Y/Z transform.");
  }
  const preset = {
    enabled: true,
    verified: true,
    name,
    map: String(player.map || "HaggaBasin"),
    x: Number(player.x),
    y: Number(player.y),
    z: Number(player.z),
    partition_id: Math.trunc(Number(player.partition_id || 0)),
    source: "online-player-position",
    source_actor_id: String(player.actor_id || player.id || ""),
    source_player_name: String(player.character_name || player.name || ""),
    created_at: new Date().toISOString()
  };
  if (!Coordinates.withinBounds(preset, preset.map)) throw new Error("Current player position is outside the configured map bounds.");
  const rows = readTeleportPresetRows(TELEPORT_PRESETS_PATH);
  const existingIndex = rows.findIndex((row) => String(row?.name || "").trim().toLowerCase() === name.toLowerCase());
  if (existingIndex >= 0 && payload.overwrite !== true) {
    const error = new Error(`A verified preset named ${name} already exists.`);
    error.statusCode = 409;
    throw error;
  }
  if (existingIndex >= 0) rows[existingIndex] = preset;
  else rows.push(preset);
  fs.mkdirSync(path.dirname(TELEPORT_PRESETS_PATH), { recursive: true });
  fs.writeFileSync(TELEPORT_PRESETS_PATH, JSON.stringify({ version: 1, presets: rows }, null, 2), "utf8");
  appendAdminAudit("teleport_preset_saved", { name, map: preset.map, x: preset.x, y: preset.y, z: preset.z, partitionId: preset.partition_id, source: preset.source, actorId: preset.source_actor_id });
  return { ok: true, message: `Verified teleport preset saved: ${name}`, preset: normalizeTeleportPreset(preset, "saved"), ...loadTeleportLocationPresets() };
}

function deleteTeleportLocationPreset(nameValue) {
  const name = String(nameValue || "").trim();
  if (!name) throw new Error("Choose a saved location first.");
  const rows = readTeleportPresetRows(TELEPORT_PRESETS_PATH);
  const next = rows.filter((row) => String(row?.name || "").trim().toLowerCase() !== name.toLowerCase());
  if (next.length === rows.length) throw new Error(`Saved location not found: ${name}`);
  fs.mkdirSync(path.dirname(TELEPORT_PRESETS_PATH), { recursive: true });
  fs.writeFileSync(TELEPORT_PRESETS_PATH, JSON.stringify({ version: 1, presets: next }, null, 2), "utf8");
  appendAdminAudit("teleport_preset_deleted", { name });
  return { ok: true, message: `Deleted saved location: ${name}`, ...loadTeleportLocationPresets() };
}

function matchingTeleportPreset(payload) {
  const result = loadTeleportLocationPresets();
  if (!result.ok) return null;
  const name = String(payload.presetName || "").trim();
  const x = Number(payload.x);
  const y = Number(payload.y);
  const map = String(payload.map || "HaggaBasin");
  return result.presets.find((preset) => (
    (!name || preset.name === name)
    && preset.map === map
    && Math.hypot(preset.x - x, preset.y - y) <= 1
  )) || null;
}

async function verifiedTeleportActor(payload, source) {
  const actorId = String(payload.targetActorId || "").trim();
  if (!actorId) throw new Error("Exact actor teleport requires a target actor id. Refresh Live Map and select the actor again.");
  const requestedType = String(payload.targetActorType || "").trim().toLowerCase();
  const loaders = source === "player-position" || requestedType === "player"
    ? [liveMapActorsTransformPlayers]
    : requestedType === "vehicle"
      ? [liveMapActorsTransformVehicles]
      : requestedType === "base"
        ? [liveMapActorsTransformBases]
        : [liveMapActorsTransformPlayers, liveMapActorsTransformVehicles, liveMapActorsTransformBases];
  for (const load of loaders) {
    const layer = await load();
    const actor = layer.rows.find((row) => String(row.actor_id || row.id) === actorId);
    if (actor) return actor;
  }
  throw new Error(`Exact actor position could not be verified for actor ${actorId}.`);
}

async function resolveLiveMapTeleportPlan(payload) {
  const submittedPlayerId = String(payload.playerId || "").trim();
  if (!submittedPlayerId) throw new Error("Choose or enter a source player/controller id first.");
  if (submittedPlayerId.length > 128 || !/^[A-Za-z0-9_:.+\-# @]+$/.test(submittedPlayerId)) throw new Error("Source player/controller id contains unsupported characters.");
  const source = await resolveTeleportPlayerState(submittedPlayerId, "source");
  const targetType = String(payload.targetActorType || "").trim().toLowerCase();
  const targetPlayerIdentity = targetType === "player" ? String(payload.targetPlayerId || payload.targetActorId || "").trim() : "";
  const requestedMap = String(payload.map || source.map || "HaggaBasin").trim();
  const preset = String(payload.elevationSource || "") === "location-preset" ? matchingTeleportPreset(payload) : null;
  let target = null;
  let targetKind = "map-click";
  let x = Number(payload.x);
  let y = Number(payload.y);
  let z = null;
  let map = source.map || requestedMap;
  let partitionId = source.partitionId;
  let partitionReason = "source player's current pawn partition_id from SQL";
  let safeZReason = "map-click dispatch altitude 5000; TeleportTo resolves safe ground in the game receiver";
  let commandMode = "safe-ground";
  const blockers = [];

  if (targetPlayerIdentity) {
    targetKind = "player";
    commandMode = "exact";
    target = await resolveTeleportPlayerState(targetPlayerIdentity, "target");
    x = target.x;
    y = target.y;
    z = target.z;
    map = target.map || map;
    partitionId = target.partitionId;
    partitionReason = "target player's current pawn partition_id from SQL";
    safeZReason = "target player's current pawn Z from SQL";
    if (!target.positionValid) blockers.push("Target player does not have a complete current X/Y/Z transform in the database.");
    if (!target.partitionValid) blockers.push("Target player's current database partition_id is missing or inactive.");
  } else if (preset) {
    targetKind = "verified-preset";
    commandMode = "exact";
    x = preset.x;
    y = preset.y;
    z = preset.z;
    map = preset.map || map;
    safeZReason = `verified location preset ${preset.name}`;
    if (source.map && map !== source.map) blockers.push(`Verified preset is on ${map}, but the source player's current world is ${source.map}.`);
  } else if (payload.targetActorId && targetType && targetType !== "player") {
    targetKind = "actor";
    commandMode = "exact";
    const actor = await verifiedTeleportActor(payload, "actor-transform");
    x = Number(actor.x);
    y = Number(actor.y);
    z = Number(actor.z);
    map = String(actor.map || map);
    safeZReason = "target actor's current transform Z from SQL";
    target = {
      actorId: String(actor.actor_id || actor.id || ""),
      playerName: String(actor.name || ""),
      map,
      partitionId: Number(actor.partition_id),
      x,
      y,
      z,
      positionValid: [x, y, z].every(Number.isFinite)
    };
    if (!target.positionValid) blockers.push("Target actor does not have a complete current X/Y/Z transform in the database.");
  } else {
    z = 5000;
    if (requestedMap && source.map && requestedMap !== source.map) blockers.push(`Map-click target is on ${requestedMap}, but the source player's current world is ${source.map}.`);
  }

  if (!source.positionValid) blockers.push("Source player does not have a complete current X/Y/Z transform in the database.");
  if (targetKind !== "player" && !source.partitionValid) blockers.push("Source player's current database partition_id is missing or inactive.");
  if (!Number.isInteger(partitionId) || partitionId <= 0) blockers.push("A valid database-resolved partition_id is required.");
  if (![x, y].every(Number.isFinite)) blockers.push("Teleport target X/Y must be numeric.");
  if (!Number.isFinite(z) || z === 0) blockers.push("A safe target Z could not be resolved.");
  const mapConfig = Coordinates.mapConfig(map);
  if ([x, y].every(Number.isFinite) && !Coordinates.withinBounds({ x, y }, mapConfig)) blockers.push(`Teleport target is outside ${mapConfig.label} bounds.`);
  return {
    source,
    target,
    targetKind,
    commandMode,
    playerId: source.playerId || submittedPlayerId,
    characterName: source.playerName,
    x,
    y,
    z,
    map,
    partitionId,
    partitionReason,
    safeZReason,
    blockers: [...new Set(blockers)],
    canExecute: blockers.length === 0
  };
}

async function liveMapTeleportRequest(payload, options = {}) {
  const cfg = loadConfig();
  const frontendRequestMode = String(payload.requestMode || "unspecified").trim().toLowerCase();
  const finalBackendMode = options.execution === true ? "execute" : "preview";
  const plan = await resolveLiveMapTeleportPlan(payload);
  const { playerId, characterName, x, y, z, map, partitionId } = plan;
  const mapConfig = Coordinates.mapConfig(map);
  const diagnostics = {
    selectedSourcePlayer: { id: plan.source.playerId, name: plan.source.playerName },
    sourceActorId: plan.source.actorId,
    targetActorId: plan.targetKind === "player" ? plan.target?.actorId || "" : "",
    sourceState: teleportStateSummary(plan.source),
    targetState: plan.targetKind === "player" ? teleportStateSummary(plan.target) : null,
    targetKind: plan.targetKind,
    commandMode: plan.commandMode,
    frontendRequestMode,
    finalBackendMode,
    selectedPartitionId: partitionId,
    partitionReason: plan.partitionReason,
    safeZReason: plan.safeZReason,
    sent: { x, y, z },
    blockers: plan.blockers
  };
  if (options.execution === true && !plan.canExecute) throw new Error(`Teleport execution blocked: ${plan.blockers.join(" ")}`);
  if (!plan.canExecute) {
    return {
      endpoint: teleportReceiverUrl(cfg),
      command: "",
      request: { playerId, characterName, x, y, z, partition_id: partitionId, map, dryRun: true, test: true, frontendRequestMode, backendRequestMode: "preview" },
      warning: plan.blockers.join(" "),
      elevationSource: plan.safeZReason,
      canExecute: false,
      resolution: { diagnostics }
    };
  }
  const commandTemplate = effectiveTeleportCommandTemplate(cfg.teleportCommandTemplate);
  const command = commandTemplate ? renderTeleportTemplate(commandTemplate, {
    playerId,
    characterName,
    x,
    y,
    z,
    map,
    partitionId: Math.trunc(partitionId)
  }) : `${plan.commandMode === "safe-ground" ? "TeleportTo" : "TeleportToExact"} ${playerId} ${x} ${y} ${z}`;
  const values = {
    playerId: jsonPathEscape(playerId),
    characterName: jsonPathEscape(characterName),
    x,
    y,
    z,
    partitionId: Math.trunc(partitionId),
    map: jsonPathEscape(map),
    command: jsonPathEscape(command),
    dryRun: options.dryRun === true ? "true" : "false",
    test: options.test === true ? "true" : "false"
  };
  const rendered = renderTeleportTemplate(cfg.teleportPayloadTemplate || defaultConfig.teleportPayloadTemplate, values);
  let requestPayload;
  try { requestPayload = JSON.parse(rendered); }
  catch (error) { throw new Error(`Teleport HTTP JSON payload template rendered invalid JSON: ${error.message}`); }
  // The API route owns execution mode. Saved templates and caller flags cannot
  // downgrade Execute into another preview (or promote Preview into execution).
  applyTeleportRequestMode(requestPayload, { frontendRequestMode, execution: options.execution === true });
  requestPayload.commandMode = plan.commandMode;
  requestPayload.targetKind = plan.targetKind;
  // Presence is resolved from the database by the Suite, not trusted from the
  // browser. The receiver uses it to avoid an online RabbitMQ attempt for a
  // player who must be moved through the offline database routine instead.
  requestPayload.playerOnlineStatus = plan.source.onlineStatus || "unknown";
  const result = {
    endpoint: teleportReceiverUrl(cfg),
    command,
    request: requestPayload,
    warning: "",
    elevationSource: plan.safeZReason,
    canExecute: true,
    resolution: { diagnostics }
  };
  if (payload.debug === true) {
    result.coordinateDebug = {
      playerCurrent: payload.playerCurrent || null,
      clickedMapPosition: payload.clickedMapPosition || null,
      convertedTarget: Coordinates.diagnostics({ x, y, z }, mapConfig),
      elevationSource: plan.safeZReason,
      targetKind: plan.targetKind,
      mapBoundsUsed: Coordinates.diagnostics({ x, y, z }, mapConfig).bounds
    };
  }
  return result;
}

async function liveMapTeleportStatus() {
  const cfg = loadConfig();
  const availability = await liveGiveServerAvailability();
  const receiver = await receiverStatus();
  const hookConfigured = Boolean(String(cfg.teleportEndpointPath || "").trim() && String(cfg.teleportPayloadTemplate || "").trim());
  const receiverTeleport = receiver?.health?.config?.teleport || {};
  const receiverLiveTeleportEnabled = receiverTeleport.liveTeleportEnabled !== false;
  const receiverTeleportSupported = receiverTeleport.teleportSupported !== false;
  const reasons = [];
  if (!availability.online) reasons.push("Server is not online.");
  if (!receiver.ok) reasons.push(`Receiver is not reachable at ${receiver.healthUrl}.`);
  if (!cfg.liveTeleportEnabled) reasons.push("Receiver live teleport is disabled. Set DUNE_RECEIVER_LIVE_TELEPORT_ENABLED=true to allow live teleport.");
  if (receiver.ok && receiverTeleport.liveTeleportEnabled === false) reasons.push("Receiver live teleport is disabled. Set DUNE_RECEIVER_LIVE_TELEPORT_ENABLED=true to allow live teleport.");
  if (!hookConfigured) reasons.push("Teleport endpoint/payload is not configured.");
  if (receiver.ok && receiverTeleport.teleportSupported === false) reasons.push("Receiver does not support live teleport.");
  return {
    ok: true,
    canTeleport: availability.online && receiver.ok && Boolean(cfg.liveTeleportEnabled) && receiverLiveTeleportEnabled && hookConfigured && receiverTeleportSupported,
    serverHealthy: availability.online,
    receiverReachable: receiver.ok,
    liveTeleportEnabled: Boolean(cfg.liveTeleportEnabled),
    receiverLiveTeleportEnabled,
    hookConfigured,
    receiverTeleportSupported,
    endpoint: teleportReceiverUrl(cfg),
    reasons
  };
}

async function liveMapTeleportExecute(payload) {
  const status = await liveMapTeleportStatus();
  const preview = await liveMapTeleportRequest({ ...payload, requestMode: "execute" }, { dryRun: false, test: false, execution: true });
  if (!status.serverHealthy) return { ok: false, status: "blocked", error: "Server is not online.", ...preview, readiness: status };
  if (!status.receiverReachable) return { ok: false, status: "blocked", error: "Receiver offline.", ...preview, readiness: status };
  if (!status.liveTeleportEnabled) return { ok: false, status: "blocked", error: "Receiver live teleport is disabled. Set DUNE_RECEIVER_LIVE_TELEPORT_ENABLED=true to allow live teleport.", ...preview, readiness: status };
  if (!status.receiverLiveTeleportEnabled) return { ok: false, status: "blocked", error: "Receiver live teleport is disabled. Set DUNE_RECEIVER_LIVE_TELEPORT_ENABLED=true to allow live teleport.", ...preview, readiness: status };
  if (!status.hookConfigured) return { ok: false, status: "blocked", error: "Teleport endpoint/payload is not configured.", ...preview, readiness: status };
  if (!status.receiverTeleportSupported) return { ok: false, status: "blocked", error: "Receiver does not support live teleport.", ...preview, readiness: status };
  appendAdminAudit("teleport_requested", {
    endpoint: preview.endpoint,
    authHeaderPresent: Boolean(receiverHttpAuthToken(loadConfig())),
    authTokenSource: receiverHttpAuthSource(loadConfig()),
    sourcePlayerPosition: payload.playerCurrent || null,
    targetMapPosition: payload.clickedMapPosition || null,
    calculatedTargetZ: preview.request.z,
    elevationSource: preview.elevationSource,
    safetyOffset: 0,
    finalPayload: preview.request,
    resolution: preview.resolution?.diagnostics || null,
    frontendRequestMode: preview.resolution?.diagnostics?.frontendRequestMode || "unknown",
    finalBackendMode: preview.resolution?.diagnostics?.finalBackendMode || "unknown",
    finalDryRun: preview.request.dryRun,
    finalTest: preview.request.test,
    playerId: preview.request.playerId,
    characterName: preview.request.characterName,
    x: preview.request.x,
    y: preview.request.y,
    z: preview.request.z,
    map: preview.request.map
  });
  const cfg = loadConfig();
  const authToken = receiverHttpAuthToken(cfg);
  const headers = authToken ? { Authorization: `Bearer ${authToken}` } : {};
  try {
    const response = await httpRequestJson(preview.endpoint, {
      method: "POST",
      headers,
      body: preview.request,
      timeout: 75000,
      label: "Teleport receiver"
    });
    const failedStatus = response.data?.status || `http-${response.statusCode}`;
    if (!response.ok || response.data?.ok !== true) {
      const message = response.data?.message || response.data?.error || response.text || `Receiver returned ${response.statusCode}.`;
      appendAdminAudit("teleport_failed", { endpoint: preview.endpoint, status: failedStatus, message });
      return { ok: false, status: failedStatus, error: message, response: response.data, httpStatus: response.statusCode, ...preview, readiness: status };
    }
    appendAdminAudit("teleport_sent_to_rmq", { endpoint: preview.endpoint, response: response.data });
    return { ok: true, status: response.data?.status || "sent_to_rmq", message: response.data?.message || "Teleport command sent. Verify in game.", response: response.data, httpStatus: response.statusCode, ...preview, readiness: status };
  } catch (error) {
    appendAdminAudit("teleport_failed", { endpoint: preview.endpoint, error: error.message });
    return { ok: false, status: "failed", error: error.message, ...preview, readiness: status };
  }
}

async function verifyLiveMapTeleport(payload) {
  const playerId = String(payload.playerId || "").trim();
  const commandMode = String(payload.commandMode || payload.expected?.commandMode || "exact").trim().toLowerCase();
  const expected = {
    x: Number(payload.expected?.x ?? payload.x),
    y: Number(payload.expected?.y ?? payload.y),
    z: Number(payload.expected?.z ?? payload.z),
    partitionId: Number(payload.expected?.partitionId ?? payload.partitionId)
  };
  if (!playerId) throw new Error("Teleport verification requires the source player id.");
  if (![expected.x, expected.y, expected.z].every(Number.isFinite)) throw new Error("Teleport verification requires the exact X/Y/Z that was sent.");
  const state = await resolveTeleportPlayerState(playerId, "verification source");
  const xyDistance = Math.hypot(state.x - expected.x, state.y - expected.y);
  const zDistance = Math.abs(state.z - expected.z);
  const partitionMatches = Number.isInteger(expected.partitionId) && state.partitionId === expected.partitionId;
  if (!["exact", "safe-ground"].includes(commandMode)) throw new Error("Teleport verification commandMode must be exact or safe-ground.");
  const zMatches = commandMode === "safe-ground" || zDistance < 100;
  const verified = xyDistance < 50 && zMatches && partitionMatches;
  let reason = "Database position has not reached the sent teleport target yet.";
  if (!partitionMatches) reason = `Post-teleport partition_id ${state.partitionId ?? "missing"} does not match sent partition_id ${expected.partitionId}.`;
  else if (xyDistance >= 50) reason = `Post-teleport X/Y is ${Math.round(xyDistance)} units from the sent target.`;
  else if (!zMatches) reason = `Post-teleport Z is ${Math.round(zDistance)} units from the sent target.`;
  else if (verified && commandMode === "safe-ground") reason = "Post-teleport database X/Y and partition_id match; the game resolved the landing Z.";
  else if (verified) reason = "Post-teleport database X/Y/Z and partition_id match the sent target.";
  if (verified) appendAdminAudit("teleport_database_verified", { playerId, sourceActorId: state.actorId, expected, postTeleport: { x: state.x, y: state.y, z: state.z, map: state.map, partitionId: state.partitionId }, reason });
  return {
    ok: true,
    status: verified ? "verified" : "pending",
    verified,
    playerId,
    selectedSourcePlayer: { id: state.playerId, name: state.playerName },
    sourceActorId: state.actorId,
    expected,
    postTeleport: { x: state.x, y: state.y, z: state.z, map: state.map, partitionId: state.partitionId },
    xyDistance,
    zDistance,
    partitionMatches,
    commandMode,
    reason,
    checkedAt: new Date().toISOString()
  };
}

function playerDiagnosticLines(diagnostics) {
  const lines = [
    `Server path: ${diagnostics.serverPath || "Not configured"}`,
    `SSH target: ${diagnostics.sshTarget || "Not configured"}`,
    `Source table used: ${diagnostics.sourceTableUsed || "Auto-detect fallback"}`,
    `Join path used: ${diagnostics.joinPathUsed || "No join path selected"}`,
    `Character names resolved: ${diagnostics.characterNamesResolved || 0}`,
    `Sources checked: ${diagnostics.sourcesChecked.length}`,
    `Players found: ${diagnostics.playersFound}`
  ];
  if (diagnostics.filesChecked.length) {
    lines.push(`Files/logs checked: ${diagnostics.filesChecked.join(", ")}`);
  } else {
    lines.push("Files/logs checked: none; current player discovery uses the Dune database.");
  }
  for (const source of diagnostics.sourcesChecked.slice(0, 10)) {
    const status = source.ok ? `${source.rows} row(s)` : `error: ${source.error || "unknown"}`;
    const resolved = typeof source.resolvedNames === "number" ? `, resolved=${source.resolvedNames}` : "";
    const join = source.joinPath ? `, join=${source.joinPath}` : "";
    lines.push(`${source.source} [id=${source.idColumn}, name=${source.nameColumn}${resolved}${join}] -> ${status}`);
  }
  if (diagnostics.sourcesChecked.length > 10) {
    lines.push(`...${diagnostics.sourcesChecked.length - 10} more source(s) checked.`);
  }
  if (diagnostics.reason) lines.push(`Reason: ${diagnostics.reason}`);
  for (const error of diagnostics.errors.slice(0, 5)) lines.push(`Parse/check error: ${error}`);
  return lines;
}

async function liveGiveServerAvailability() {
  const vm = await vmInfo();
  let status = null;
  let raw = "";
  const canCheckBattlegroup = Boolean((vm.exists && vm.state === "Running") || VM_IP);
  if (canCheckBattlegroup) {
    const result = await battlegroup("status");
    raw = result.stdout || result.stderr || result.error || "";
    status = parseStatus(raw);
  }
  const online = Boolean(statusSummaryIsOnline(status?.summary));
  return { online, vm, status: status?.summary || null, raw };
}

function dbBackedGiveItemGrade(command) {
  const grade = Number(command?.quality || 0);
  return Number.isInteger(grade) && grade > 0 ? grade : 0;
}

function giveItemCatalogItem(template) {
  const wanted = String(template || "").trim().toLowerCase();
  return gearCatalog().find((item) => String(item.id || "").trim().toLowerCase() === wanted) || null;
}

async function investigateGiveItemDurability(template) {
  const output = await dbQuery(buildDurabilityInvestigationSql(sqlString(template)), 15000);
  const row = parseDbRows(output, ["dataType", "udtName", "compositeStatsType", "currentRows", "numericRows", "maximumRows", "maximumNumericRows", "selectedCurrentRows", "selectedNumericRows", "selectedMaximumRows", "selectedMaximumNumericRows"])[0] || {};
  const evidence = {
    readOnly: true,
    table: "dune.items",
    column: "stats",
    dataType: String(row.dataType || ""),
    udtName: String(row.udtName || ""),
    saveItemCompositeStatsType: String(row.compositeStatsType || ""),
    fields: {
      current: "stats.FItemStackAndDurabilityStats[1].CurrentDurability",
      maximum: "stats.FItemStackAndDurabilityStats[1].DecayedMaxDurability"
    },
    encoding: "JSON number",
    observed: {
      currentDurabilityRows: Number(row.currentRows || 0),
      numericDurabilityRows: Number(row.numericRows || 0),
      maximumDurabilityRows: Number(row.maximumRows || 0),
      numericMaximumDurabilityRows: Number(row.maximumNumericRows || 0),
      selectedTemplateRows: Number(row.selectedCurrentRows || 0),
      selectedTemplateNumericRows: Number(row.selectedNumericRows || 0),
      selectedTemplateMaximumRows: Number(row.selectedMaximumRows || 0),
      selectedTemplateNumericMaximumRows: Number(row.selectedMaximumNumericRows || 0)
    }
  };
  evidence.authoritative = evidence.dataType === "jsonb"
    && evidence.udtName === "jsonb"
    && evidence.saveItemCompositeStatsType === "jsonb"
    && evidence.observed.currentDurabilityRows === evidence.observed.numericDurabilityRows
    && evidence.observed.maximumDurabilityRows === evidence.observed.numericMaximumDurabilityRows;
  return evidence;
}

function assertAuthoritativeDurabilityEvidence(expectation, evidence) {
  if (expectation?.applied && !evidence?.authoritative) {
    throw new Error("Durability schema or production-shaped encoding is not authoritative; the entire item grant was blocked before write.");
  }
}

async function adminGiveDbItemToPlayer(command, options = {}) {
  const playerId = String(command?.playerId || "").trim();
  const template = String(command?.template || "").trim();
  const qty = requireInteger(command?.qty, "quantity", 1, 50000);
  const grade = requireInteger(command?.quality ?? 0, "grade", 0, 5);
  const mode = String(options.mode || "dry-run").toLowerCase();
  const dryRun = mode !== "execute";
  if (!playerId) throw new Error("Choose a player first.");
  if (!isValidTemplateId(template)) throw new Error("Choose a valid exact item template identifier.");
  const catalogItem = giveItemCatalogItem(template);
  const durability = durabilityExpectation(catalogItem, command?.setDurabilityTo200);
  const durabilityEvidence = await investigateGiveItemDurability(template);
  assertAuthoritativeDurabilityEvidence(durability, durabilityEvidence);
  const metadata = storageItemMetadata(template);
  const stackCount = Math.ceil(qty / metadata.stackMax);
  const targetPredicate = [
    `ps.account_id::text = ${sqlString(playerId)}`,
    `ps.player_controller_id::text = ${sqlString(playerId)}`,
    `ps.player_pawn_id::text = ${sqlString(playerId)}`,
    `ps.player_state_id::text = ${sqlString(playerId)}`,
    `lower(ps.character_name) = lower(${sqlString(playerId)})`,
    `lower(coalesce(ac."user", '')) = lower(${sqlString(playerId)})`
  ].join("\n         or ");
  const targetCte = `
    target as (
      select ps.account_id::text as account_id,
             ps.player_pawn_id::text as actor_id,
             coalesce(ps.character_name, ac."user", ps.account_id::text) as character_name,
             coalesce(ps.online_status::text, 'unknown') as online_status
      from dune.player_state ps
      left join dune.accounts ac on ac.id = ps.account_id
      where ${targetPredicate}
      order by case when lower(coalesce(ps.character_name, '')) = lower(${sqlString(playerId)}) then 0 else 1 end,
               ps.last_avatar_activity desc nulls last,
               ps.player_state_id
      limit 1
    )`;
  const inventoryCtes = `
    preferred_inventory as (
      select inv.id::text as inventory_id,
             inv.actor_id::text as actor_id,
             coalesce(inv.max_item_count, 0)::int as max_item_count,
             coalesce(inv.max_item_volume, 0)::int as max_item_volume,
             coalesce(inv.inventory_type, -1)::int as inventory_type
      from dune.inventories inv
      where inv.actor_id = (select actor_id::bigint from target limit 1)
        and inv.inventory_type = 0
      order by inv.id
      limit 1
    ),
    fallback_inventory as (
      select inv.id::text as inventory_id,
             inv.actor_id::text as actor_id,
             coalesce(inv.max_item_count, 0)::int as max_item_count,
             coalesce(inv.max_item_volume, 0)::int as max_item_volume,
             coalesce(inv.inventory_type, -1)::int as inventory_type
      from dune.inventories inv
      where inv.actor_id = (select actor_id::bigint from target limit 1)
        and not exists(select 1 from preferred_inventory)
      order by inv.id
      limit 1
    ),
    chosen_inventory as (
      select * from preferred_inventory
      union all
      select * from fallback_inventory
      limit 1
    ),
    current_count as (
      select count(*)::int as item_count
      from dune.items i
      where i.inventory_id = (select inventory_id::bigint from chosen_inventory limit 1)
    ),
    next_position as (
      select coalesce(max(i.position_index), -1) + 1 as position_index
      from dune.items i
      where i.inventory_id = (select inventory_id::bigint from chosen_inventory limit 1)
    )`;
  const precheckSql = `
    with ${targetCte},
    ${inventoryCtes}
    select
      case
        when not exists(select 1 from target) then 'player_not_found'
        when not exists(select 1 from chosen_inventory) then 'inventory_not_found'
        when (select max_item_count from chosen_inventory limit 1) > 0
          and (select item_count from current_count) + ${stackCount} > (select max_item_count from chosen_inventory limit 1) then 'inventory_full'
        else 'ready'
      end,
      coalesce((select account_id from target limit 1), ''),
      coalesce((select actor_id from target limit 1), ''),
      coalesce((select character_name from target limit 1), ''),
      coalesce((select online_status from target limit 1), ''),
      coalesce((select inventory_id from chosen_inventory limit 1), ''),
      coalesce((select inventory_type::text from chosen_inventory limit 1), ''),
      coalesce((select max_item_count::text from chosen_inventory limit 1), ''),
      coalesce((select max_item_volume::text from chosen_inventory limit 1), ''),
      coalesce((select item_count::text from current_count), '0'),
      coalesce((select position_index::text from next_position), '0')
  `;
  const precheckOutput = await dbQuery(precheckSql, 15000);
  const precheck = parseDbRows(precheckOutput, ["status", "accountId", "actorId", "characterName", "onlineStatus", "inventoryId", "inventoryType", "maxItemCount", "maxItemVolume", "itemCount", "nextPosition"])[0] || {};
  if (precheck.status === "player_not_found") throw new Error(`Player was not found for item grant target: ${playerId}`);
  if (precheck.status === "inventory_not_found") throw new Error(`Player inventory was not found for ${precheck.characterName || playerId}.`);
  if (precheck.status === "inventory_full") throw new Error(`Player inventory does not have the ${stackCount} free slot(s) required for ${giveItemDisplayName(template)}.`);
  if (precheck.status !== "ready") throw new Error(`Database item grant precheck failed: ${precheck.status || "unknown"}.`);
  const player = {
    accountId: precheck.accountId,
    actorId: precheck.actorId,
    characterName: precheck.characterName,
    onlineStatus: precheck.onlineStatus
  };
  const inventory = {
    id: precheck.inventoryId,
    type: Number(precheck.inventoryType || 0),
    maxItemCount: Number(precheck.maxItemCount || 0),
    maxItemVolume: Number(precheck.maxItemVolume || 0),
    itemCount: Number(precheck.itemCount || 0),
    nextPosition: Number(precheck.nextPosition || 0)
  };
  if (dryRun) {
    return {
      ok: true,
      dryRun: true,
      status: "dry-run-passed",
      grantKind: "Verified Inventory Item Grant",
      transport: "database",
      command,
      player,
      inventory,
      item: { id: template, name: giveItemDisplayName(template), qty, grade, stackCount, stackMax: metadata.stackMax, durability },
      durability,
      durabilityEvidence,
      stdout: `Dry-run passed. ${giveItemDisplayName(template)} x${qty} grade ${grade} would be inserted into inventory ${inventory.id}. ${durability.display}.`,
      stderr: "",
      note: `Dry-run validated the target player inventory, ${stackCount} required slot(s), destination, and durability applicability. No database write was performed. ${durability.applicable ? durability.reason : "Durability not applicable; no durability data will be written."}`
    };
  }
  const statsJson = itemStatsJsonForGrant(durability);
  const insertSql = `
    begin;
    set local search_path=dune,public;
    select i.id from dune.inventories i
      where i.id=${requireInteger(inventory.id, "inventory_id", 1)}
        and i.actor_id=${requireInteger(player.actorId, "player_actor_id", 1)}
      for update;
    create temp table player_grant_target on commit drop as
      select i.id inventory_id, i.actor_id, coalesce(i.max_item_count,0)::int max_item_count,
             (select count(*)::int from dune.items it where it.inventory_id=i.id) item_count,
             (select coalesce(max(it.position_index),-1)::bigint from dune.items it where it.inventory_id=i.id) max_position
      from dune.inventories i
      where i.id=${requireInteger(inventory.id, "inventory_id", 1)}
        and i.actor_id=${requireInteger(player.actorId, "player_actor_id", 1)}
      limit 1;
    do $$ begin
      if not exists(select 1 from player_grant_target) then raise exception 'Player inventory destination changed before item grant'; end if;
      if exists(select 1 from dune.items i join player_grant_target t on t.inventory_id=i.inventory_id
                where i.position_index is null or i.position_index<0 or (t.max_item_count>0 and i.position_index>=t.max_item_count)) then
        raise exception 'Player inventory contains invalid occupied slot positions';
      end if;
      if exists(select 1 from dune.items i join player_grant_target t on t.inventory_id=i.inventory_id
                group by i.position_index having count(*)>1) then
        raise exception 'Player inventory contains duplicate occupied slot positions';
      end if;
    end $$;
    create temp table player_grant_slots on commit drop as
      select candidate.position_index, row_number() over(order by candidate.position_index)::int slot_number
      from player_grant_target t
      cross join lateral (
        select free_slot.position_index::bigint
        from generate_series(0,greatest(t.max_item_count-1,0)) free_slot(position_index)
        where t.max_item_count>0
          and not exists(select 1 from dune.items occupied where occupied.inventory_id=t.inventory_id and occupied.position_index=free_slot.position_index)
        order by free_slot.position_index
        limit ${stackCount}
      ) candidate
      union all
      select (t.max_position+n)::bigint,n::int
      from player_grant_target t cross join generate_series(1,${stackCount}) n
      where t.max_item_count<=0;
    do $$ begin
      if (select count(*) from player_grant_slots) <> ${stackCount} then raise exception 'Player inventory no longer has enough valid free slots'; end if;
    end $$;
    create temp table player_grant_prepared on commit drop as
      select t.inventory_id,
             least(${metadata.stackMax},${qty}-(s.slot_number-1)*${metadata.stackMax})::bigint stack_size,
             s.position_index
      from player_grant_target t cross join player_grant_slots s;
    create temp table player_grant_inserted on commit drop as
      with inserted as (
        insert into dune.items (inventory_id,template_id,stack_size,quality_level,position_index,stats)
        select p.inventory_id,${sqlString(template)},p.stack_size,${grade},p.position_index,${sqlString(statsJson)}::jsonb
        from player_grant_prepared p
        returning id,inventory_id,template_id,stack_size,quality_level,position_index,stats
      ) select * from inserted;
    do $$ begin
      if not coalesce((select count(*)=${stackCount}
                              and coalesce(sum(i.stack_size),0)=${qty}
                              and count(distinct i.position_index)=count(*)
                              and bool_and(i.inventory_id=${requireInteger(inventory.id, "inventory_id", 1)})
                              and bool_and(i.template_id=${sqlString(template)})
                              and bool_and(i.quality_level=${grade})
                              and bool_and(${durability.applied
                                ? `jsonb_typeof(i.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}')='number' and (i.stats #>> '${GIVE_ITEM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE} and jsonb_typeof(i.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')='number' and (i.stats #>> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE}`
                                : `i.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}' is null and i.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}' is null`})
                         from player_grant_inserted i),false) then
        raise exception 'Player item grant failed transactional identity, quantity, slot, grade, or durability verification';
      end if;
    end $$;
    select 'inserted',count(*)::text,coalesce(sum(i.stack_size),0)::text,
           coalesce(string_agg(i.id::text,',' order by i.id),''),
           coalesce(string_agg(i.position_index::text,',' order by i.id),''),
           count(*) filter(where i.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}' is not null)::text,
           count(*) filter(where jsonb_typeof(i.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}')='number')::text,
           count(*) filter(where jsonb_typeof(i.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}')='number' and (i.stats #>> '${GIVE_ITEM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE})::text,
           count(*) filter(where i.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}' is not null)::text,
           count(*) filter(where jsonb_typeof(i.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')='number')::text,
           count(*) filter(where jsonb_typeof(i.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')='number' and (i.stats #>> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE})::text
      from player_grant_inserted i;
    commit;
  `;
  const insertOutput = await dbQuery(insertSql, 30000);
  const insertedRows = parseDbRows(insertOutput, ["status", "stackCount", "quantity", "itemIds", "positions", "durabilityPresentStacks", "numericDurabilityStacks", "exactDurabilityStacks", "maximumDurabilityPresentStacks", "numericMaximumDurabilityStacks", "exactMaximumDurabilityStacks"]);
  const inserted = [...insertedRows].reverse().find((row) => row.status === "inserted") || {};
  if (inserted.status !== "inserted") throw new Error(`Database item grant failed: ${inserted.status || "unknown"}.`);
  const itemIds = String(inserted.itemIds || "").split(",").filter(Boolean);
  const positions = String(inserted.positions || "").split(",").filter(Boolean).map(Number);
  const durabilityReadBack = {
    foundStacks: Number(inserted.stackCount || 0),
    durabilityPresentStacks: Number(inserted.durabilityPresentStacks || 0),
    numericDurabilityStacks: Number(inserted.numericDurabilityStacks || 0),
    exactDurabilityStacks: Number(inserted.exactDurabilityStacks || 0),
    maximumDurabilityPresentStacks: Number(inserted.maximumDurabilityPresentStacks || 0),
    numericMaximumDurabilityStacks: Number(inserted.numericMaximumDurabilityStacks || 0),
    exactMaximumDurabilityStacks: Number(inserted.exactMaximumDurabilityStacks || 0)
  };
  const durabilityVerification = classifyDurabilityReadBack(durability, durabilityReadBack);
  if (!durabilityVerification.ok) throw new Error(durabilityVerification.message);
  const receiptId = `give-${Date.now()}-${crypto.randomBytes(4).toString("hex")}`;
  const receipt = {
    receiptId,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    status: "database-verified",
    destination: "player-inventory",
    checkCount: 0,
    player,
    inventory,
    item: { id: template, name: giveItemDisplayName(template), quantity: Number(inserted.quantity || qty), grade, stackCount: Number(inserted.stackCount || stackCount), stackMax: metadata.stackMax, itemIds, positions, durability },
    durability,
    durabilityEvidence,
    verification: { durability: durabilityReadBack }
  };
  let receiptWarning = "";
  try { giveItemReceiptStore.add(receipt); }
  catch (error) { receiptWarning = ` The database transaction succeeded, but the receipt could not be persisted: ${error.message}`; }
  return {
    ok: true,
    dryRun: false,
    status: "db-inserted",
    grantKind: "Verified Inventory Item Grant",
    transport: "database",
    command,
    player,
    inventory,
    item: {
      id: template,
      name: giveItemDisplayName(template),
      qty: Number(inserted.quantity || qty),
      grade,
      stackCount: Number(inserted.stackCount || stackCount),
      stackMax: metadata.stackMax,
      itemIds,
      positions,
      durability
    },
    durability,
    durabilityEvidence,
    durabilityVerification,
    receipt,
    stdout: `Inserted and transactionally verified ${giveItemDisplayName(template)} x${qty} grade ${grade} into ${player.characterName || playerId}'s inventory ${inventory.id}. ${durability.display}.`,
    stderr: "",
    note: `Database grant, destination read-back, slot allocation, and durability verification completed. The player may need to relog or refresh inventory before the item appears.${receiptWarning}`
  };
}

async function adminGiveItem(payload) {
  const timer = liveGiveTimingTracker();
  let command = null;
  let mode = "dry-run";
  let auditBase = {};
  let durabilityAudit = null;
  try {
    command = await timer.step("validate_payload", () => validateGiveItemPayload(payload));
    mode = String(payload?.mode || "dry-run").toLowerCase();
    auditBase = {
      playerId: command.playerId,
      template: command.template,
      qty: command.qty,
      quality: command.quality,
      requestId: command.requestId,
      setDurabilityTo200: command.setDurabilityTo200
    };
    const catalogItem = giveItemCatalogItem(command.template) || (/^recipe:/i.test(command.template) ? {
      id: command.template,
      name: recipeDisplayName(command.template.replace(/^recipe:/i, "")),
      category: "Schematics",
      type: recipeCategory(command.template.replace(/^recipe:/i, "")),
      source: "Live DB Known Recipes",
      recipeId: command.template.replace(/^recipe:/i, "")
    } : /^tech:/i.test(command.template) ? {
      id: command.template,
      name: techKnowledgeDisplayName(techKnowledgeKeyFromTemplate(command.template)),
      category: "Schematics",
      type: techKnowledgeCategory(techKnowledgeKeyFromTemplate(command.template)),
      source: "Live DB Research Tree",
      techKnowledgeKey: techKnowledgeKeyFromTemplate(command.template),
      recipeId: techKnowledgeRecipeIdCandidates(command.template)[0] || ""
    } : null);
    const durability = durabilityExpectation(catalogItem, command.setDurabilityTo200);
    durabilityAudit = durability;
    if (catalogItem && isTechKnowledgeItem(catalogItem)) {
      timer.skip("server_availability", "skipped: research blueprint unlock uses database TechKnowledge");
      timer.skip("runtime_transport_update", "skipped: research blueprint unlock uses database TechKnowledge");
      timer.skip("transport_health_check", "skipped: research blueprint unlock uses database TechKnowledge");
      if (mode === "execute" && payload?.confirmed !== true && payload?.confirmed !== "true") {
        const error = new Error("Confirm real research blueprint unlock before writing to the player database.");
        appendAdminAudit("research_blueprint_blocked", { ...auditBase, reason: error.message });
        throw error;
      }
      const result = await timer.step("unlock_research_blueprint", () => adminUnlockTechKnowledge(command, { mode }));
      result.timings = timer.finish();
      appendAdminAudit(mode === "execute" ? "give_item_research_blueprint_unlocked" : "give_item_research_blueprint_dry_run", {
        ...auditBase,
        result: { ok: result.ok, status: result.status, techKnowledgeKey: result.techKnowledgeKey, recipeId: result.recipeId, alreadyUnlocked: result.alreadyUnlocked },
        timings: result.timings
      });
      return result;
    }
    if (catalogItem && isRecipeSchematicItem(catalogItem)) {
      timer.skip("server_availability", "skipped: schematic unlock uses database recipe library");
      timer.skip("runtime_transport_update", "skipped: schematic unlock uses database recipe library");
      timer.skip("transport_health_check", "skipped: schematic unlock uses database recipe library");
      if (mode === "execute" && payload?.confirmed !== true && payload?.confirmed !== "true") {
        const error = new Error("Confirm real schematic recipe unlock before writing to the player database.");
        appendAdminAudit("schematic_recipe_blocked", { ...auditBase, reason: error.message });
        throw error;
      }
      const result = await timer.step("unlock_schematic_recipe", () => adminUnlockSchematicRecipe(command, { mode }));
      result.timings = timer.finish();
      appendAdminAudit(mode === "execute" ? "give_item_schematic_recipe_unlocked" : "give_item_schematic_recipe_dry_run", {
        ...auditBase,
        result: { ok: result.ok, status: result.status, recipeId: result.recipeId, alreadyUnlocked: result.alreadyUnlocked },
        timings: result.timings
      });
      return result;
    }
    const dbGrade = dbBackedGiveItemGrade(command);
    if (dbGrade > 0 || durability.applied) {
      timer.skip("server_availability", "skipped: verified item grant uses database inventory transaction");
      timer.skip("runtime_transport_update", "skipped: verified item grant uses database inventory transaction");
      timer.skip("transport_health_check", "skipped: database item grant does not use receiver transport");
      if (mode === "execute" && payload?.confirmed !== true && payload?.confirmed !== "true") {
        const error = new Error("Confirm the real database item grant before writing to the player inventory.");
        appendAdminAudit("give_item_db_grade_blocked", { ...auditBase, reason: error.message });
        throw error;
      }
      const result = await timer.step("database_grade_item_grant", () => adminGiveDbItemToPlayer(command, { mode }));
      result.timings = timer.finish();
      appendAdminAudit(mode === "execute" ? "give_item_db_grade_inserted" : "give_item_db_grade_dry_run", {
        ...auditBase,
        durability: result.durability,
        durabilityEvidence: result.durabilityEvidence,
        durabilityVerification: result.durabilityVerification,
        receiptId: result.receipt?.receiptId || "",
        result: { ok: result.ok, status: result.status, player: result.player, inventory: result.inventory, item: result.item },
        timings: result.timings
      });
      return result;
    }
    timer.skip("server_availability", "skipped: Live Give uses receiver transport health directly");
    timer.skip("runtime_transport_update", "skipped: no server/VM/battlegroup discovery during Give Item");
    const transport = await timer.step("transport_health_check", () => checkGiveTransport());
    if (!transport.configured || !transport.reachable) {
      const result = { ok: false, dryRun: mode !== "execute", status: "live-unavailable", command, durability, transport: transport.mode, missingEnv: transport.missingEnv || [], stdout: "", stderr: liveGiveUnavailableMessage(transport), error: liveGiveUnavailableMessage(transport) };
      result.timings = timer.finish();
      appendAdminAudit("give_item_live_unavailable", { ...auditBase, durability, result: { ok: result.ok, status: result.status, transport: result.transport, missingEnv: result.missingEnv, error: result.error }, timings: result.timings });
      return result;
    }
    if (mode !== "execute") {
      const result = {
        ok: true,
        dryRun: true,
        status: "dry-run-passed",
        transport: transport.mode,
        command,
        durability,
        requestId: command.requestId,
        stdout: `Dry-run passed. Command validated for ${command.template} x${command.qty} -> ${command.playerId}. ${durability.display}.`,
        stderr: "",
        note: "Dry-run validated the command and receiver transport. No live grant was executed."
      };
      result.timings = timer.finish();
      appendAdminAudit("give_item_dry_run", { ...auditBase, durability, result: { ok: result.ok, status: result.status }, timings: result.timings });
      return result;
    }
    if (payload?.confirmed !== true && payload?.confirmed !== "true") {
      const error = new Error("Confirm real Live Give execution before sending the command.");
      appendAdminAudit("give_item_live_blocked", { ...auditBase, reason: error.message });
      throw error;
    }
    appendAdminAudit("give_item_live_started", { ...auditBase, durability, transport: transport.mode });
    const live = await timer.step("send_live_give_item", () => sendLiveGiveItem(command, transport));
    live.durability = durability;
    if (live.status === "live-unavailable") {
      const result = { ...live, ok: false, dryRun: false, stdout: "", stderr: live.error || "Live Give unavailable." };
      result.timings = timer.finish();
      appendAdminAudit("give_item_live_unavailable", { ...auditBase, durability, result: { ok: result.ok, status: result.status, transport: result.transport, missingEnv: result.missingEnv || [], error: result.error || result.stderr }, timings: result.timings });
      return result;
    }
    if (!live.ok || live.dryRun) {
      const result = { ...live, ok: false, dryRun: false, status: "live-execution-failed", stdout: "", stderr: live.error || "Live execution failed." };
      result.timings = timer.finish();
      appendAdminAudit("give_item_live_failed", { ...auditBase, durability, result: { ok: result.ok, status: result.status, error: result.error || result.stderr }, timings: result.timings });
      return result;
    }
    if (live.status === "live-verified") {
      const result = { ...live, dryRun: false, status: "live-verified", stderr: "" };
      result.timings = timer.finish();
      appendAdminAudit("give_item_live_verified", { ...auditBase, durability, result: { ok: result.ok, status: result.status, transport: result.transport, response: result.response || null }, timings: result.timings });
      return result;
    }
    const result = { ...live, dryRun: false, status: "live-published", stderr: "" };
    result.timings = timer.finish();
    appendAdminAudit("give_item_live_published", { ...auditBase, durability, result: { ok: result.ok, status: result.status, transport: result.transport, response: result.response || null }, timings: result.timings });
    return result;
  } catch (error) {
    error.timings = timer.finish();
    appendAdminAudit("give_item_live_failed", { ...auditBase, durability: durabilityAudit, error: error.message, timings: error.timings });
    throw error;
  }
}

function marketPostingCatalogItem(template) {
  const id = String(template || "").trim();
  return gearCatalog().find((row) => row.id === id) || null;
}

const MARKET_EXPIRY_DAY_OPTIONS = [1, 3, 7, 14];

function normalizeMarketExpiryDays(value) {
  const days = Number(value ?? 3);
  if (!Number.isInteger(days) || !MARKET_EXPIRY_DAY_OPTIONS.includes(days)) {
    throw new Error("Expiration must be 1, 3, 7, or 14 days.");
  }
  return days;
}

function validateMarketListingPayload(payload) {
  const template = String(payload?.template || "").trim();
  const stackSize = requireInteger(payload?.stackSize ?? payload?.quantity ?? 1, "stack size", 1, 50000);
  const price = requireInteger(payload?.price ?? 1, "price", 1, 999999999);
  const quality = requireInteger(payload?.quality ?? 0, "grade", 0, 5);
  const listingCount = requireInteger(payload?.listingCount ?? 1, "listing count", 1, 50);
  const expiryDays = normalizeMarketExpiryDays(payload?.expiryDays ?? payload?.expiry_days ?? 3);
  if (!template || template.length > 240 || !/^[A-Za-z0-9_:.()+-]+$/.test(template)) throw new Error("Choose a valid item template.");
  const item = marketPostingCatalogItem(template);
  if (!item) throw new Error("Item template was not found in the local item catalog.");
  if (isTechKnowledgeItem(item) || isRecipeSchematicItem(item)) throw new Error("Research and recipe unlock pseudo-items cannot be posted to the market.");
  return {
    template,
    name: item.name || template,
    stackSize,
    price,
    quality,
    listingCount,
    expiryDays,
    pricing: normalizeMarketPricingAudit(payload?.pricing, template, price),
    requestId: `${Date.now()}-${Math.random().toString(16).slice(2)}`
  };
}

function normalizeMarketPricingAudit(value, template, finalPrice) {
  if (!value || typeof value !== "object") return null;
  const safeNumber = (candidate, fallback = 1) => {
    const number = Number(candidate);
    return Number.isFinite(number) && number >= 0 ? number : fallback;
  };
  const cleanText = (candidate, fallback = "") => String(candidate ?? fallback).slice(0, 500);
  return {
    template: cleanText(template),
    pricingMode: ["fixed", "dynamic"].includes(value.pricingMode) ? value.pricingMode : "dynamic",
    basePrice: safeNumber(value.basePrice, finalPrice),
    globalBasePrice: safeNumber(value.globalBasePrice, finalPrice),
    baseSource: cleanText(value.baseSource, "global-base"),
    metadata: {
      grade: cleanText(value.metadata?.grade, "Unknown"),
      tier: cleanText(value.metadata?.tier, "Unknown"),
      rarity: cleanText(value.metadata?.rarity, "Unknown"),
      category: cleanText(value.metadata?.category, "Unknown")
    },
    factors: {
      item: safeNumber(value.factors?.item),
      grade: safeNumber(value.factors?.grade),
      tier: safeNumber(value.factors?.tier),
      rarity: safeNumber(value.factors?.rarity),
      cycle: safeNumber(value.factors?.cycle)
    },
    variation: {
      itemPercent: safeNumber(value.variation?.itemPercent, 0),
      cyclePercent: safeNumber(value.variation?.cyclePercent, 0)
    },
    seed: {
      item: cleanText(value.seed?.item),
      cycle: cleanText(value.seed?.cycle),
      battlegroup: cleanText(value.seed?.battlegroup),
      cycleId: cleanText(value.seed?.cycleId)
    },
    calculatedPrice: safeNumber(value.calculatedPrice, finalPrice),
    finalSubmittedPrice: finalPrice
  };
}

async function marketListingGameNow() {
  try {
    const sql = `
      with database_clock as (
        select floor(extract(epoch from clock_timestamp()))::bigint as database_now
      ),
      player_clock as (
        select max(expiration_time) - ${14 * 24 * 3600} as inferred_now
        from dune.dune_exchange_orders
        where is_npc_order = false
          and item_id is not null
          and expiration_time between ${14 * 24 * 3600 + 1} and 999999999
      )
      select (
        case
          when p.inferred_now between d.database_now - ${30 * 24 * 3600} and d.database_now + ${30 * 24 * 3600}
            then p.inferred_now
          else d.database_now
        end
      )::text
      from player_clock p
      cross join database_clock d
    `;
    const row = parseDbRows(await dbQuery(sql, 12000), ["expirationTime"])[0] || {};
    return Number(row.expirationTime || 0) || 0;
  } catch {
    return 0;
  }
}

async function marketListingExpiryTime(expiryDays) {
  const gameNow = await marketListingGameNow();
  return Math.max(0, gameNow) + expiryDays * 24 * 3600;
}

async function cleanupExpiredMarketListings(options = {}) {
  return {
    ok: true,
    status: "delegated-to-market-bot",
    skipped: true,
    source: String(options.source || "manual"),
    matched: 0,
    removedOrders: 0,
    removedItems: 0,
    orderIds: [],
    durationMs: 0,
    message: "Suite-side broad cleanup is disabled. The persistent Market Bot cleans only rows in its strict ownership table."
  };
}

let marketExpiredCleanupRunning = false;

async function runMarketExpiredCleanupBackground(source = "timer") {
  if (SERVER_MIGRATION_ENABLED && migrationMaintenance.status().active) return { ok: true, skipped: true, source, reason: MIGRATION_MAINTENANCE_BANNER };
  if (marketExpiredCleanupRunning) return { ok: false, skipped: true, reason: "cleanup already running" };
  marketExpiredCleanupRunning = true;
  try {
    return await cleanupExpiredMarketListings({ source });
  } catch (error) {
    appendAdminAudit("market_expired_listing_cleanup_failed", { source, error: error.message });
    return { ok: false, source, error: error.message };
  } finally {
    marketExpiredCleanupRunning = false;
  }
}

async function marketPostingStatus() {
  const started = Date.now();
  const expiredCleanup = await cleanupExpiredMarketListings({ source: "status" }).catch((error) => ({ ok: false, error: error.message }));
  const requiredTables = [
    "actors",
    "inventories",
    "items",
    "world_partition",
    "dune_exchange_orders",
    "dune_exchange_sell_orders",
    "dune_exchange_users",
    "dune_exchanges"
  ];
  const tableSql = `
    select table_name, 'present'
    from information_schema.tables
    where table_schema = 'dune'
      and table_name in (${requiredTables.map(sqlString).join(",")})
    order by table_name
  `;
  const tableRows = await dbQuery(tableSql, 12000).then((output) => parseDbRows(output, ["name", "status"]));
  const tableSet = new Set(tableRows.map((row) => row.name));
  const missingTables = requiredTables.filter((name) => !tableSet.has(name));
  const missingFunctions = [];
  let exchange = null;
  let botListings = 0;
  if (!missingTables.length && !missingFunctions.length) {
    const statsSql = `
      with selected_exchange as (
        select id::text as exchange_id, exchange_name
        from dune.dune_exchanges
        where exchange_name != 'Global'
        order by id
        limit 1
      ),
      market_actor as (
        select id
        from dune.actors
        where class = 'AlphaNineMarket'
        order by id
        limit 1
      )
      select
        coalesce((select exchange_id from selected_exchange), ''),
        coalesce((select exchange_name from selected_exchange), ''),
        coalesce((select count(*)::text from dune.dune_exchange_orders where owner_id = (select id from market_actor) and is_npc_order = true), '0')
    `;
    const rows = parseDbRows(await dbQuery(statsSql, 12000), ["exchangeId", "exchangeName", "botListings"]);
    const row = rows[0] || {};
    exchange = row.exchangeId ? { id: row.exchangeId, name: row.exchangeName || "Exchange" } : null;
    botListings = Number(row.botListings || 0) || 0;
  }
  return {
    ok: !missingTables.length && !missingFunctions.length,
    status: !missingTables.length && !missingFunctions.length ? "ready" : "unsupported",
    exchange,
    botActorClass: "AlphaNineMarket",
    botListings,
    expiredCleanup,
    tables: requiredTables.map((name) => ({ name, status: tableSet.has(name) ? "present" : "missing" })),
    functions: [],
    missingTables,
    missingFunctions,
    durationMs: Date.now() - started
  };
}

async function marketListings(payload = {}) {
  const started = Date.now();
  const gameNow = await marketListingGameNow();
  const expiredCleanup = await cleanupExpiredMarketListings({ source: "listings", gameNow }).catch((error) => ({ ok: false, error: error.message }));
  const limit = requireInteger(payload.limit ?? 100, "limit", 1, 250);
  const q = String(payload.q || "").trim();
  const listingPredicates = ["i.stack_size > 0"];
  if (q) listingPredicates.push(`(o.template_id ilike ${sqlString(`%${q}%`)} or coalesce(e.exchange_name, '') ilike ${sqlString(`%${q}%`)} or coalesce(a.class, '') ilike ${sqlString(`%${q}%`)})`);
  const where = `where ${listingPredicates.join(" and ")}`;
  const sql = `
    select
      o.id::text,
      coalesce(e.exchange_name, ''),
      o.template_id,
      coalesce(i.stack_size::text, ''),
      coalesce(o.quality_level::text, ''),
      coalesce(o.item_price::text, ''),
      coalesce(s.initial_stack_size::text, ''),
      coalesce(s.wear_normalized_price::text, ''),
      coalesce(o.is_npc_order::text, ''),
      coalesce(a.class, ''),
      coalesce(o.owner_id::text, ''),
      coalesce(o.expiration_time::text, ''),
      coalesce(o.item_id::text, '')
    from dune.dune_exchange_orders o
    join dune.dune_exchange_sell_orders s on s.order_id = o.id
    join dune.items i on i.id = o.item_id
    left join dune.dune_exchanges e on e.id = o.exchange_id
    left join dune.actors a on a.id = o.owner_id
    ${where}
    order by o.id desc
    limit ${limit}
  `;
  const catalog = gearCatalog();
  const byId = new Map(catalog.map((item) => [item.id, item]));
  const rows = parseDbRows(await dbQuery(sql, 20000), ["orderId", "exchangeName", "template", "stackSize", "quality", "price", "initialStackSize", "normalizedPrice", "isNpcOrder", "ownerClass", "ownerId", "expirationTime", "itemId"]);
  const listings = rows.map((row) => {
    const item = byId.get(row.template);
    const quality = Number(row.quality || 0) || 0;
    const catalogGrade = item ? normalizeItemGrade(item.grade, item.rarity, item.quality, item.tier, item.itemGrade, item.itemRarity) : "Unknown";
    const displayGrade = catalogGrade && catalogGrade !== "Unknown" ? (quality > 0 ? `${catalogGrade} / Grade ${quality}` : catalogGrade) : `Grade ${quality}`;
    const tier = item ? normalizeItemTier(item.tier, item.itemTier, item.level, item.itemLevel) : "Unknown";
    return {
      orderId: row.orderId,
      itemId: row.itemId,
      template: row.template,
      name: item?.name || row.template,
      gradeLabel: displayGrade,
      tier: tier && tier !== "Unknown" ? tier : "",
      category: item ? normalizeItemCategory(item.category) : "",
      exchangeName: row.exchangeName || "Exchange",
      stackSize: Number(row.stackSize || row.initialStackSize || 0) || 0,
      quality,
      price: Number(row.price || row.normalizedPrice || 0) || 0,
      initialStackSize: Number(row.initialStackSize || row.stackSize || 0) || 0,
      isNpcOrder: row.isNpcOrder === "t" || row.isNpcOrder === "true",
      ownerClass: row.ownerClass || "",
      ownerId: row.ownerId,
      expirationTime: row.expirationTime
    };
  });
  return { ok: true, listings, count: listings.length, gameNow, expiredCleanup, durationMs: Date.now() - started };
}

