async function postMarketListing(payload) {
  const command = validateMarketListingPayload(payload);
  if (payload?.confirmed !== true && payload?.confirmed !== "true") throw new Error("Confirm live market posting before writing to the exchange.");
  const started = Date.now();
  const statsJson = JSON.stringify({ FCustomizationStats: [[], {}], FItemStackAndDurabilityStats: [[], {}] });
  const expiryTime = await marketListingExpiryTime(command.expiryDays);
  const sql = `
    with selected_exchange as (
      select id as exchange_id, inventory_id as exchange_inventory_id
      from dune.dune_exchanges
      where exchange_name != 'Global'
      order by id
      limit 1
    ),
    selected_access_point as (
      select coalesce(
        (select access_point_id from dune.dune_exchange_orders where exchange_id = (select exchange_id from selected_exchange) and access_point_id is not null limit 1),
        1
      )::bigint as access_point_id
    ),
    selected_inventory as (
      select id as inventory_id
      from dune.inventories
      where id = (select exchange_inventory_id from selected_exchange)
         or exchange_id = (select exchange_id from selected_exchange)
      order by case when id = (select exchange_inventory_id from selected_exchange) then 0 else 1 end, id
      limit 1
    ),
    created_inventory as (
      insert into dune.inventories (exchange_id)
      select (select exchange_id from selected_exchange)
      where not exists (select 1 from selected_inventory)
      returning id as inventory_id
    ),
    market_inventory as (
      select inventory_id from selected_inventory
      union all
      select inventory_id from created_inventory
      limit 1
    ),
    synced_exchange_inventory as (
      update dune.dune_exchanges
      set inventory_id = (select inventory_id from market_inventory)
      where id = (select exchange_id from selected_exchange)
        and inventory_id is null
      returning id
    ),
    selected_partition as (
      select partition_id
      from dune.world_partition
      order by partition_id
      limit 1
    ),
    existing_actor as (
      select id
      from dune.actors
      where class = 'AlphaNineMarket'
      order by id
      limit 1
    ),
    created_actor as (
      insert into dune.actors (class, serial, gas_attributes, properties, dimension_index, partition_id)
      select 'AlphaNineMarket', 0, '{}', '{}', 0, (select partition_id from selected_partition)
      where not exists (select 1 from existing_actor)
      returning id
    ),
    market_actor as (
      select id from existing_actor
      union all
      select id from created_actor
      limit 1
    ),
    exchange_user as (
      insert into dune.dune_exchange_users (owner_id)
      select id from market_actor
      on conflict do nothing
      returning id as user_id
    ),
    market_user as (
      select user_id from exchange_user
      union all
      select id as user_id
      from dune.dune_exchange_users
      where owner_id = (select id from market_actor)
      limit 1
    ),
    next_position as (
      select coalesce(max(position_index), -1) + 1 as position_index
      from dune.items
      where inventory_id = (select inventory_id from market_inventory)
    ),
    source_rows as (
      select generate_series(0, ${command.listingCount - 1}) as offset_index
    ),
    inserted_items as (
      insert into dune.items (inventory_id, stack_size, position_index, template_id, quality_level, stats)
      select
        (select inventory_id from market_inventory),
        ${command.stackSize},
        (select position_index from next_position) + offset_index,
        ${sqlString(command.template)},
        ${command.quality},
        ${sqlString(statsJson)}
      from source_rows
      returning id, position_index
    ),
    inserted_orders as (
      insert into dune.dune_exchange_orders
        (exchange_id, access_point_id, owner_id, is_npc_order, expiration_time,
         template_id, durability_cur, durability_max, category_mask, category_depth,
         item_price, quality_level, item_id)
      select
        (select exchange_id from selected_exchange),
        (select access_point_id from selected_access_point),
        (select id from market_actor),
        true,
        ${expiryTime},
        ${sqlString(command.template)},
        1.0,
        1.0,
        0,
        0,
        ${command.price},
        ${command.quality},
        id
      from inserted_items
      returning id, item_id
    ),
    inserted_sell_orders as (
      insert into dune.dune_exchange_sell_orders (order_id, initial_stack_size, wear_normalized_price)
      select id, ${command.stackSize}, ${command.price}
      from inserted_orders
      returning order_id
    )
    select
      (select count(*)::text from inserted_sell_orders),
      coalesce((select min(id)::text from inserted_orders), ''),
      coalesce((select max(id)::text from inserted_orders), ''),
      coalesce((select min(item_id)::text from inserted_orders), ''),
      coalesce((select max(item_id)::text from inserted_orders), ''),
      coalesce((select exchange_id::text from selected_exchange), ''),
      coalesce((select inventory_id::text from market_inventory), ''),
      coalesce((select id::text from market_actor), ''),
      coalesce((select user_id::text from market_user), '')
  `;
  const output = await dbQuery(sql, 45000);
  const row = parseDbRows(output, ["created", "firstOrderId", "lastOrderId", "firstItemId", "lastItemId", "exchangeId", "inventoryId", "actorId", "exchangeUserId"])[0] || {};
  const created = Number(row.created || 0) || 0;
  if (created !== command.listingCount) throw new Error(`Market posting returned ${created} created listing(s), expected ${command.listingCount}.`);
  const result = {
    ok: true,
    status: "posted",
    command,
    market: {
      exchangeId: row.exchangeId,
      inventoryId: row.inventoryId,
      actorId: row.actorId,
      exchangeUserId: row.exchangeUserId,
      firstOrderId: row.firstOrderId,
      lastOrderId: row.lastOrderId,
      firstItemId: row.firstItemId,
      lastItemId: row.lastItemId
    },
    item: {
      id: command.template,
      name: command.name,
      stackSize: command.stackSize,
      price: command.price,
      quality: command.quality,
      listingCount: created,
      expiryDays: command.expiryDays,
      expirationTime: expiryTime
    },
    pricing: command.pricing,
    durationMs: Date.now() - started,
    message: `Posted ${created} live market listing(s) for ${command.name} at ${command.price} Solari.`
  };
  appendAdminAudit("market_listing_posted", {
    requestId: command.requestId,
    template: command.template,
    stackSize: command.stackSize,
    price: command.price,
    quality: command.quality,
    listingCount: command.listingCount,
    expiryDays: command.expiryDays,
    expirationTime: expiryTime,
    pricing: command.pricing,
    result: result.market,
    durationMs: result.durationMs
  });
  return result;
}

function giveItemDisplayName(template) {
  if (/^recipe:/i.test(String(template || ""))) return recipeDisplayName(String(template || "").replace(/^recipe:/i, ""));
  if (/^tech:/i.test(String(template || ""))) return techKnowledgeDisplayName(techKnowledgeKeyFromTemplate(template));
  const item = itemCatalogProvider.resolve(template);
  return item?.name || template;
}

async function adminUnlockTechKnowledge(command, options = {}) {
  const template = String(command?.template || "").trim();
  const playerId = String(command?.playerId || "").trim();
  const qty = Math.max(1, Number(command?.qty || 1) || 1);
  const mode = String(options.mode || "dry-run").toLowerCase();
  const dryRun = mode !== "execute";
  const techKey = techKnowledgeKeyFromTemplate(template);
  if (!techKey || !/^[A-Za-z0-9_().+\-]+$/.test(techKey)) throw new Error("Selected template is not a research blueprint unlock.");
  const recipeCandidates = techKnowledgeRecipeIdCandidates(techKey);
  const recipeId = recipeCandidates[0] || "";
  const targetPredicate = [
    `ps.account_id::text = ${sqlString(playerId)}`,
    `ps.player_controller_id::text = ${sqlString(playerId)}`,
    `ps.player_pawn_id::text = ${sqlString(playerId)}`,
    `ps.player_state_id::text = ${sqlString(playerId)}`,
    `lower(ps.character_name) = lower(${sqlString(playerId)})`,
    `lower(coalesce(ac."user", '')) = lower(${sqlString(playerId)})`
  ].join("\n         or ");
  const techPath = "{TechKnowledgePlayerComponent,m_TechKnowledge,m_TechKnowledgeData}";
  const recipePath = "{CraftingRecipesLibraryActorComponent,m_KnownItemRecipes}";
  const updateCte = dryRun ? "" : `,
    next_properties as (
      select current_state.actor_id,
             jsonb_set(
               current_state.properties,
               '${techPath}',
               (
                 select jsonb_agg(
                   case when ord = matching_tech.ord then
                     jsonb_set(jsonb_set(elem, '{UnlockedState}', to_jsonb('Purchased'::text), true), '{bIsNewEntry}', 'true'::jsonb, true)
                   else elem end
                   order by ord
                 )
                 from jsonb_array_elements(current_state.tech_data) with ordinality entries(elem, ord)
               ),
               false
             ) as properties
      from current_state, matching_tech
    ),
    updated as (
      update dune.actors a
      set properties = case
        when ${recipeId ? "not exists(select 1 from already_known_recipe)" : "false"} then
          jsonb_set(
            next_properties.properties,
            '${recipePath}',
            coalesce(next_properties.properties#>'${recipePath}', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
              'm_Source', 'SchematicPickup',
              'm_bIsNew', true,
              'BaseRecipeId', jsonb_build_object('Name', (select resolved_recipe_id from selected_recipe)),
              'm_QualityLevel', 0,
              'm_NumberOfRecipeUses', 0,
              'm_bIsLimitedUseRecipe', false
            )),
            true
          )
        else next_properties.properties end
      from next_properties, matching_tech
      where a.id = next_properties.actor_id
        and (matching_tech.unlocked_state <> 'Purchased' or ${recipeId ? "not exists(select 1 from already_known_recipe)" : "false"})
      returning a.id
    )`;
  const sql = `
    with target as (
      select ps.account_id::text as account_id,
             ps.player_pawn_id::text as actor_id,
             coalesce(ps.character_name, ac."user", ps.account_id::text) as character_name,
             coalesce(ps.online_status::text, 'unknown') as online_status
      from dune.player_state ps
      left join dune.accounts ac on ac.id = ps.account_id
      where ${targetPredicate}
      order by case when lower(coalesce(ps.character_name, '')) = lower(${sqlString(playerId)}) then 0 else 1 end,
               ps.last_avatar_activity desc nulls last,
               ps.player_state_id
      limit 1
    ),
    current_state as (
      select a.id as actor_id,
             a.properties,
             coalesce(a.properties#>'${techPath}', '[]'::jsonb) as tech_data,
             coalesce(a.properties#>'${recipePath}', '[]'::jsonb) as recipes
      from dune.actors a
      join target t on t.actor_id::bigint = a.id
      where a.properties ? 'TechKnowledgePlayerComponent'
      ${dryRun ? "" : "for update"}
    ),
    matching_tech as (
      select ord,
             elem,
             elem->>'UnlockedState' as unlocked_state
      from current_state
      cross join lateral jsonb_array_elements(current_state.tech_data) with ordinality entries(elem, ord)
      where elem->>'ItemKey' = ${sqlString(techKey)}
      limit 1
    ),
    known_recipe as (
      select recipe->'BaseRecipeId'->>'Name' as resolved_recipe_id
      from dune.actors source_actor
      cross join lateral jsonb_array_elements(coalesce(source_actor.properties#>'${recipePath}', '[]'::jsonb)) recipe
      where ${recipeId ? `lower(recipe->'BaseRecipeId'->>'Name') = lower(${sqlString(recipeId)})` : "false"}
      order by recipe->'BaseRecipeId'->>'Name'
      limit 1
    ),
    selected_recipe as (
      select ${recipeId ? `coalesce((select resolved_recipe_id from known_recipe), ${sqlString(recipeId)})` : "''"} as resolved_recipe_id
    ),
    already_known_recipe as (
      select 1
      from current_state, selected_recipe
      cross join lateral jsonb_array_elements(current_state.recipes) recipe
      where selected_recipe.resolved_recipe_id <> ''
        and lower(recipe->'BaseRecipeId'->>'Name') = lower(selected_recipe.resolved_recipe_id)
      limit 1
    )
    ${updateCte}
    select
      case
        when not exists(select 1 from target) then 'player_not_found'
        when not exists(select 1 from current_state) then 'component_missing'
        when not exists(select 1 from matching_tech) then 'tech_missing'
        when (select unlocked_state from matching_tech limit 1) = 'Purchased'
          and (${recipeId ? "exists(select 1 from already_known_recipe)" : "true"}) then 'already_unlocked'
        when ${dryRun ? "true" : "exists(select 1 from updated)"} then '${dryRun ? "dry-run-passed" : "research-unlocked"}'
        else 'failed'
      end,
      coalesce((select account_id from target limit 1), ''),
      coalesce((select actor_id from target limit 1), ''),
      coalesce((select character_name from target limit 1), ''),
      coalesce((select online_status from target limit 1), ''),
      ${sqlString(techKey)},
      coalesce((select unlocked_state from matching_tech limit 1), ''),
      coalesce((select resolved_recipe_id from selected_recipe limit 1), ''),
      coalesce((select exists(select 1 from already_known_recipe)::text), 'false')
  `;
  const output = await dbQuery(sql, dryRun ? 15000 : 30000);
  const row = parseDbRows(output, ["status", "accountId", "actorId", "characterName", "onlineStatus", "techKnowledgeKey", "previousState", "recipeId", "recipeAlreadyKnown"])[0] || {};
  if (row.status === "player_not_found") throw new Error(`Player was not found for research blueprint unlock target: ${playerId}`);
  if (row.status === "component_missing") throw new Error(`TechKnowledgePlayerComponent was not found for ${row.characterName || playerId}.`);
  if (row.status === "tech_missing") throw new Error(`Research blueprint ${techKey} was not found in ${row.characterName || playerId}'s TechKnowledge tree.`);
  if (row.status === "failed") throw new Error(`Research blueprint unlock failed for ${techKey}.`);
  const online = String(row.onlineStatus || "").toLowerCase() === "online";
  const alreadyUnlocked = row.status === "already_unlocked";
  const result = {
    ok: true,
    dryRun,
    status: row.status,
    grantKind: "Research Blueprint Unlock",
    transport: "database",
    command,
    item: { id: template, name: techKnowledgeDisplayName(techKey) },
    player: {
      accountId: row.accountId,
      actorId: row.actorId,
      characterName: row.characterName,
      onlineStatus: row.onlineStatus
    },
    techKnowledgeKey: techKey,
    previousState: row.previousState,
    recipeId: row.recipeId || "",
    recipeName: row.recipeId ? recipeDisplayName(row.recipeId) : "",
    recipeAlreadyKnown: row.recipeAlreadyKnown === "true",
    alreadyUnlocked,
    quantityIgnored: qty > 1,
    verified: !dryRun,
    stdout: alreadyUnlocked
      ? `${row.characterName || playerId} already has ${techKnowledgeDisplayName(techKey)} unlocked in Research.`
      : dryRun
        ? `Dry-run passed. ${techKnowledgeDisplayName(techKey)} maps to Research TechKnowledge key ${techKey}${row.recipeId ? ` and crafting recipe ${row.recipeId}` : ""}.`
        : `Research blueprint unlocked: ${techKnowledgeDisplayName(techKey)} for ${row.characterName || playerId}.`,
    stderr: online ? (dryRun ? "Player is online. Dry-run did not write anything; a live research unlock may require relog/server reload before it appears." : "Player is online. The research value was written to the database, but the live game may require relog/server reload before it appears.") : "",
    note: "Research-screen blueprint unlock: writes TechKnowledgePlayerComponent.m_TechKnowledge.m_TechKnowledgeData and, for RCP_ entries, CraftingRecipesLibraryActorComponent.m_KnownItemRecipes.",
    timings: {}
  };
  appendAdminAudit(dryRun ? "research_blueprint_dry_run" : "research_blueprint_unlocked", {
    playerId,
    template,
    techKnowledgeKey: techKey,
    recipeId: row.recipeId || "",
    status: row.status,
    online,
    alreadyUnlocked
  });
  return result;
}

async function adminUnlockSchematicRecipe(command, options = {}) {
  const template = String(command?.template || "").trim();
  const playerId = String(command?.playerId || "").trim();
  const qty = Math.max(1, Number(command?.qty || 1) || 1);
  const mode = String(options.mode || "dry-run").toLowerCase();
  const dryRun = mode !== "execute";
  const recipeTemplateMatch = /^recipe:/i.test(template);
  const recipeIdFromTemplate = recipeTemplateMatch ? template.replace(/^recipe:/i, "") : "";
  const item = gearCatalog().find((row) => row.id === template) || (recipeTemplateMatch ? {
    id: template,
    name: recipeDisplayName(recipeIdFromTemplate),
    category: "Schematics",
    type: recipeCategory(recipeIdFromTemplate),
    source: "Live DB Known Recipes",
    recipeId: recipeIdFromTemplate
  } : null);
  if (!item || !isRecipeSchematicItem(item)) throw new Error("Selected template is not a schematic recipe unlock.");
  const candidates = schematicRecipeIdCandidates(template);
  if (!candidates.length) throw new Error(`No crafting recipe mapping could be derived for schematic ${template}.`);
  const valuesSql = candidates.map((recipeId, index) => `(${index}, ${sqlString(recipeId.toLowerCase())}, ${sqlString(recipeId)})`).join(",\n        ");
  const targetPredicate = [
    `ps.account_id::text = ${sqlString(playerId)}`,
    `ps.player_controller_id::text = ${sqlString(playerId)}`,
    `ps.player_pawn_id::text = ${sqlString(playerId)}`,
    `ps.player_state_id::text = ${sqlString(playerId)}`,
    `lower(ps.character_name) = lower(${sqlString(playerId)})`,
    `lower(coalesce(ac."user", '')) = lower(${sqlString(playerId)})`
  ].join("\n         or ");
  const componentPath = "{CraftingRecipesLibraryActorComponent,m_KnownItemRecipes}";
  const updateCte = dryRun ? "" : `,
      updated as (
        update dune.actors a
        set properties = jsonb_set(
          a.properties,
          '${componentPath}',
          current_recipes.recipes || jsonb_build_array(jsonb_build_object(
            'm_Source', 'SchematicPickup',
            'm_bIsNew', true,
            'BaseRecipeId', jsonb_build_object('Name', selected_recipe.recipe_id),
            'm_QualityLevel', 0,
            'm_NumberOfRecipeUses', 0,
            'm_bIsLimitedUseRecipe', false
          )),
          true
        )
        from current_recipes, selected_recipe
        where a.id = current_recipes.actor_id
          and not exists (select 1 from already_known)
        returning a.id
      )`;
  const updatedExistsSql = dryRun ? "false" : "exists(select 1 from updated)";
  const sql = `
    with input(ord, recipe_lower, recipe_id) as (
      values
        ${valuesSql}
    ),
    target as (
      select ps.account_id::text as account_id,
             ps.player_pawn_id::text as actor_id,
             coalesce(ps.character_name, ac."user", ps.account_id::text) as character_name,
             coalesce(ps.online_status::text, 'unknown') as online_status
      from dune.player_state ps
      left join dune.accounts ac on ac.id = ps.account_id
      where ${targetPredicate}
      order by case when lower(coalesce(ps.character_name, '')) = lower(${sqlString(playerId)}) then 0 else 1 end,
               ps.last_avatar_activity desc nulls last,
               ps.player_state_id
      limit 1
    ),
    current_recipes as (
      select a.id as actor_id,
             coalesce(a.properties#>'${componentPath}', '[]'::jsonb) as recipes
      from dune.actors a
      join target t on t.actor_id::bigint = a.id
      where a.properties ? 'CraftingRecipesLibraryActorComponent'
      ${dryRun ? "" : "for update"}
    ),
    known_recipe as (
      select recipe->'BaseRecipeId'->>'Name' as recipe_id, min(input.ord) as ord
      from input
      join dune.actors source_actor on source_actor.properties ? 'CraftingRecipesLibraryActorComponent'
      cross join lateral jsonb_array_elements(coalesce(source_actor.properties#>'${componentPath}', '[]'::jsonb)) recipe
      where lower(recipe->'BaseRecipeId'->>'Name') = input.recipe_lower
      group by recipe->'BaseRecipeId'->>'Name'
      order by min(input.ord)
      limit 1
    ),
    selected_recipe as (
      select coalesce((select recipe_id from known_recipe limit 1), (select recipe_id from input order by ord limit 1)) as recipe_id
    ),
    already_known as (
      select 1
      from current_recipes, selected_recipe
      cross join lateral jsonb_array_elements(current_recipes.recipes) recipe
      where lower(recipe->'BaseRecipeId'->>'Name') = lower(selected_recipe.recipe_id)
      limit 1
    )
    ${updateCte}
    select
      case
        when not exists(select 1 from target) then 'player_not_found'
        when not exists(select 1 from current_recipes) then 'component_missing'
        when exists(select 1 from already_known) then 'already_unlocked'
        when ${dryRun ? "true" : updatedExistsSql} then '${dryRun ? "dry-run-passed" : "recipe-unlocked"}'
        else 'failed'
      end,
      coalesce((select account_id from target limit 1), ''),
      coalesce((select actor_id from target limit 1), ''),
      coalesce((select character_name from target limit 1), ''),
      coalesce((select online_status from target limit 1), ''),
      coalesce((select recipe_id from selected_recipe limit 1), ''),
      coalesce((select count(*)::text from current_recipes cross join lateral jsonb_array_elements(current_recipes.recipes) recipe), '0'),
      coalesce((select count(*)::text from current_recipes cross join lateral jsonb_array_elements(current_recipes.recipes) recipe), '0'),
      coalesce((select recipe_id from known_recipe limit 1), '')
  `;
  const output = await dbQuery(sql, dryRun ? 15000 : 30000);
  const row = parseDbRows(output, ["status", "accountId", "actorId", "characterName", "onlineStatus", "recipeId", "beforeCount", "afterCount", "matchedRecipeId"])[0] || {};
  if (row.status === "player_not_found") throw new Error(`Player was not found for schematic unlock target: ${playerId}`);
  if (row.status === "component_missing") throw new Error(`CraftingRecipesLibraryActorComponent was not found for ${row.characterName || playerId}.`);
  if (row.status === "failed") throw new Error(`Crafting recipe unlock failed for ${row.recipeId || template}.`);
  const online = String(row.onlineStatus || "").toLowerCase() === "online";
  const alreadyUnlocked = row.status === "already_unlocked";
  const result = {
    ok: true,
    dryRun,
    status: row.status,
    grantKind: "Crafting Recipe Unlock",
    transport: "database",
    command,
    item: { id: template, name: item.name || template },
    player: {
      accountId: row.accountId,
      actorId: row.actorId,
      characterName: row.characterName,
      onlineStatus: row.onlineStatus
    },
    recipeId: row.recipeId,
    recipeName: recipeDisplayName(row.recipeId),
    recipeCandidates: candidates,
    matchedRecipeId: row.matchedRecipeId || "",
    alreadyUnlocked,
    quantityIgnored: qty > 1,
    verified: !dryRun,
    stdout: alreadyUnlocked
      ? `${row.characterName || playerId} already knows ${recipeDisplayName(row.recipeId)}.`
      : dryRun
        ? `Dry-run passed. ${item.name || template} maps to crafting recipe ${row.recipeId}.`
        : `Crafting recipe unlocked: ${recipeDisplayName(row.recipeId)} for ${row.characterName || playerId}.`,
    stderr: online ? (dryRun ? "Player is online. Dry-run did not write anything; a live recipe unlock may require relog/server reload before it appears." : "Player is online. The recipe was written to the database, but the live game may require relog/server reload before it appears.") : "",
    note: "Database-backed schematic unlock: writes CraftingRecipesLibraryActorComponent.m_KnownItemRecipes instead of character inventory.",
    timings: {}
  };
  appendAdminAudit(dryRun ? "schematic_recipe_dry_run" : "schematic_recipe_unlocked", {
    playerId,
    template,
    recipeId: row.recipeId,
    status: row.status,
    online,
    alreadyUnlocked
  });
  return result;
}

function liveGiveTimingTracker() {
  const started = Date.now();
  const timings = {};
  return {
    timings,
    async step(name, fn) {
      const stepStarted = Date.now();
      try {
        return await fn();
      } finally {
        timings[name] = Date.now() - stepStarted;
      }
    },
    skip(name, reason = "skipped") {
      timings[name] = { skipped: true, reason, ms: 0 };
    },
    finish() {
      timings.total = Date.now() - started;
      return timings;
    }
  };
}

async function adminGiveQueue(payload) {
  const queueTimer = liveGiveTimingTracker();
  const playerId = String(payload?.playerId || "").trim();
  const mode = String(payload?.mode || "dry-run").toLowerCase();
  const confirmed = payload?.confirmed === true || payload?.confirmed === "true";
  const items = Array.isArray(payload?.items) ? payload.items : [];
  if (!playerId) throw new Error("Choose a player first.");
  if (!items.length) throw new Error("Add at least one item to the Give Queue.");
  if (items.length > 100) throw new Error("Give Queue supports up to 100 items at a time.");
  if (mode === "execute" && !confirmed) throw new Error("Confirm real Live Give execution before sending the queue.");

  const results = [];
  for (let index = 0; index < items.length; index += 1) {
    const item = items[index] || {};
    const itemPayload = {
      playerId,
      template: item.template || item.itemId || item.id,
      qty: item.qty ?? item.quantity ?? 1,
      mode,
      confirmed
    };
    if (Object.prototype.hasOwnProperty.call(item, "quality")) itemPayload.quality = item.quality;
    itemPayload.setDurabilityTo200 = requestedDurability(item.setDurabilityTo200);
    const startedAt = new Date().toISOString();
    try {
      const result = await queueTimer.step(`item_${index + 1}`, () => adminGiveItem(itemPayload));
      const command = result.command || itemPayload;
      const success = Boolean(result.ok || result.dryRun);
      results.push({
        index,
        itemId: command.template || itemPayload.template,
        itemName: giveItemDisplayName(command.template || itemPayload.template),
        quantity: command.qty || Number(itemPayload.qty || 1),
        quality: command.quality,
        success,
        status: result.status || (success ? "ok" : "failed"),
        error: success ? "" : (result.error || result.stderr || "Give item failed."),
        result,
        startedAt,
        completedAt: new Date().toISOString()
      });
    } catch (error) {
      const itemId = String(itemPayload.template || "").trim();
      results.push({
        index,
        itemId,
        itemName: giveItemDisplayName(itemId),
        quantity: Number(itemPayload.qty || 1),
        quality: itemPayload.quality,
        success: false,
        status: "failed",
        error: error.message,
        timings: error.timings || {},
        startedAt,
        completedAt: new Date().toISOString()
      });
    }
  }
  const succeeded = results.filter((row) => row.success).length;
  const failed = results.length - succeeded;
  const response = {
    ok: failed === 0,
    status: failed ? "queue-completed-with-failures" : "queue-completed",
    playerId,
    mode,
    total: results.length,
    processed: results.length,
    succeeded,
    failed,
    results,
    timings: queueTimer.finish()
  };
  appendAdminAudit("give_item_queue_completed", {
    playerId,
    mode,
    total: response.total,
    succeeded,
    failed,
    items: results.map((row) => ({ itemId: row.itemId, quantity: row.quantity, success: row.success, status: row.status, error: row.error || "" }))
  });
  return response;
}

function giveQueuePresetSlug(name) {
  const slug = String(name || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_.-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
  if (!slug) throw new Error("Preset name is required.");
  return slug;
}

function giveQueuePresetPath(name) {
  return path.join(GIVE_QUEUE_PRESET_DIR, `${giveQueuePresetSlug(name)}.json`);
}

function normalizeGiveQueuePresetItems(items) {
  if (!Array.isArray(items) || !items.length) throw new Error("Preset must contain at least one queue item.");
  if (items.length > 100) throw new Error("Preset supports up to 100 queue items.");
  return items.map((item, index) => {
    const template = String(item?.template || item?.itemId || item?.id || "").trim();
    const qty = Number(item?.qty ?? item?.quantity ?? 1);
    if (!template) throw new Error(`Preset item ${index + 1} is missing an item template.`);
    if (!isValidTemplateId(template)) throw new Error(`Preset item ${index + 1} has an invalid exact template identifier: ${template}`);
    if (!Number.isInteger(qty) || qty < 1 || qty > 50000) throw new Error(`Preset item ${index + 1} quantity must be a whole number between 1 and 50000.`);
    const normalized = {
      template,
      name: String(item?.name || giveItemDisplayName(template)),
      qty
    };
    if (Object.prototype.hasOwnProperty.call(item || {}, "quality") && item.quality !== "" && item.quality !== null && item.quality !== undefined) {
      const quality = Number(item.quality);
      if (!Number.isInteger(quality) || quality < 0 || quality > 5) throw new Error(`Preset item ${index + 1} grade must be a whole number between 0 and 5.`);
      normalized.quality = quality;
    }
    normalized.setDurabilityTo200 = requestedDurability(item?.setDurabilityTo200);
    return normalized;
  });
}

function normalizeGiveQueuePreset(payload, existing = null) {
  const name = String(payload?.name || payload?.presetName || "").trim();
  if (!name || name.length > 80) throw new Error("Preset name must be 1-80 characters.");
  const items = normalizeGiveQueuePresetItems(payload?.items);
  const now = new Date().toISOString();
  return {
    version: 1,
    name,
    createdAt: existing?.createdAt || payload?.createdAt || now,
    updatedAt: now,
    items
  };
}

function readGiveQueuePresetFile(filePath) {
  const preset = JSON.parse(fs.readFileSync(filePath, "utf8").replace(/^\uFEFF/, ""));
  return normalizeGiveQueuePreset(preset, preset);
}

function listGiveQueuePresets() {
  fs.mkdirSync(GIVE_QUEUE_PRESET_DIR, { recursive: true });
  const presets = [];
  for (const entry of fs.readdirSync(GIVE_QUEUE_PRESET_DIR)) {
    if (!entry.toLowerCase().endsWith(".json")) continue;
    try {
      const filePath = path.join(GIVE_QUEUE_PRESET_DIR, entry);
      const preset = readGiveQueuePresetFile(filePath);
      presets.push({
        name: preset.name,
        itemCount: preset.items.length,
        updatedAt: preset.updatedAt,
        createdAt: preset.createdAt,
        fileName: entry
      });
    } catch {
      // Ignore malformed local preset files in the list; import/load reports validation errors.
    }
  }
  presets.sort((a, b) => String(a.name).localeCompare(String(b.name)));
  return presets;
}

function findGiveQueuePresetPath(name) {
  const direct = giveQueuePresetPath(name);
  if (fs.existsSync(direct)) return direct;
  fs.mkdirSync(GIVE_QUEUE_PRESET_DIR, { recursive: true });
  const target = String(name || "").trim();
  for (const entry of fs.readdirSync(GIVE_QUEUE_PRESET_DIR)) {
    if (!entry.toLowerCase().endsWith(".json")) continue;
    const filePath = path.join(GIVE_QUEUE_PRESET_DIR, entry);
    try {
      const preset = readGiveQueuePresetFile(filePath);
      if (preset.name === target) return filePath;
    } catch {}
  }
  return direct;
}

function saveGiveQueuePreset(payload) {
  fs.mkdirSync(GIVE_QUEUE_PRESET_DIR, { recursive: true });
  const filePath = giveQueuePresetPath(payload?.name);
  let existing = null;
  if (fs.existsSync(filePath)) {
    try { existing = readGiveQueuePresetFile(filePath); } catch {}
  }
  const preset = normalizeGiveQueuePreset(payload, existing);
  fs.writeFileSync(filePath, JSON.stringify(preset, null, 2), "utf8");
  return { ok: true, preset, path: filePath };
}

function loadGiveQueuePreset(name) {
  const filePath = findGiveQueuePresetPath(name);
  if (!fs.existsSync(filePath)) throw new Error("Give Queue preset was not found.");
  return { ok: true, preset: readGiveQueuePresetFile(filePath), path: filePath };
}

function deleteGiveQueuePreset(name) {
  const filePath = findGiveQueuePresetPath(name);
  if (!fs.existsSync(filePath)) throw new Error("Give Queue preset was not found.");
  fs.unlinkSync(filePath);
  return { ok: true, deleted: String(name || ""), path: filePath };
}

function sqlString(value) {
  return `'${String(value || "").replace(/'/g, "''")}'`;
}

function requireInteger(value, name, min = 0, max = Number.MAX_SAFE_INTEGER) {
  const text = String(value ?? "").trim();
  if (!/^-?\d+$/.test(text)) throw new Error(`${name} must be a whole number.`);
  const number = Number(text);
  if (!Number.isSafeInteger(number) || number < min || number > max) {
    throw new Error(`${name} must be between ${min} and ${max}.`);
  }
  return number;
}

function requireSqlBigint(value, name, min = 0n, max = 9223372036854775807n) {
  const text = String(value ?? "").trim();
  if (!/^-?\d+$/.test(text)) throw new Error(`${name} must be a whole number.`);
  const number = BigInt(text);
  if (number < min || number > max) {
    throw new Error(`${name} must be between ${min} and ${max}.`);
  }
  return text;
}

function optionalInteger(value, name, min = 0, max = Number.MAX_SAFE_INTEGER) {
  if (value === undefined || value === null || String(value).trim() === "") return null;
  return requireInteger(value, name, min, max);
}

function requireReal(value, name, min = 0, max = 1000) {
  const number = Number(value);
  if (!Number.isFinite(number) || number < min || number > max) {
    throw new Error(`${name} must be between ${min} and ${max}.`);
  }
  return number;
}

function requireConfirmed(value) {
  if (value !== true && value !== "true" && value !== 1 && value !== "1") {
    throw new Error("Confirm the exact function call before running this permission action.");
  }
}

function appendAdminAudit(action, payload) {
  const entry = {
    at: new Date().toISOString(),
    ...payload,
    action
  };
  fs.mkdirSync(path.dirname(ADMIN_AUDIT_LOG), { recursive: true });
  fs.appendFileSync(ADMIN_AUDIT_LOG, `${JSON.stringify(entry)}\n`, "utf8");
}

async function adminPermissions(playerControllerIdValue) {
  const playerControllerId = optionalInteger(playerControllerIdValue, "player_controller_id", 0);
  const selectedWhere = playerControllerId === null ? "" : `where gm.player_id = ${playerControllerId}`;
  const rankWhere = playerControllerId === null ? "" : `where par.player_id = ${playerControllerId}`;
  const accessWhere = playerControllerId === null ? "" : `where pac.account_id in (select account_id from dune.player_state where player_controller_id = ${playerControllerId})`;
  const sql = `
    select
      'guild' as row_type,
      gm.player_id::text,
      gm.guild_id::text,
      gm.role_id::text,
      coalesce(ps.account_id::text, ''),
      coalesce(ps.character_name, ''),
      coalesce(ac.funcom_id, ac."user", ''),
      case when gm.role_id = 100 then 'true' else 'false' end
    from dune.guild_members gm
    left join dune.player_state ps on ps.player_controller_id = gm.player_id
    left join dune.accounts ac on ac.id = ps.account_id
    ${selectedWhere}
    order by gm.guild_id, gm.role_id desc, gm.player_id
    limit 300;

    select
      'actor_rank' as row_type,
      par.player_id::text,
      par.permission_actor_id::text,
      par.rank::text,
      coalesce(pa.actor_name, ''),
      coalesce(pa.actor_type::text, ''),
      coalesce(pa.access_level::text, '')
    from dune.permission_actor_rank par
    left join dune.permission_actor pa on pa.actor_id = par.permission_actor_id
    ${rankWhere}
    order by par.permission_actor_id, par.player_id
    limit 300;

    select
      'access_code' as row_type,
      pac.account_id::text,
      pac.access_code::text,
      pac.access_code_type::text,
      pac.is_resettable::text
    from dune.player_access_codes pac
    ${accessWhere}
    order by pac.account_id, pac.access_code_type, pac.access_code
    limit 300;
  `;
  const output = await dbQuery(sql);
  const guildMembers = [];
  const objectPermissions = [];
  const accessCodes = [];
  for (const line of output.split(/\r?\n/).filter(Boolean)) {
    const parts = line.split("\t");
    if (parts[0] === "guild") {
      guildMembers.push({
        player_id: parts[1] || "",
        guild_id: parts[2] || "",
        role_id: parts[3] || "",
        account_id: parts[4] || "",
        character_name: parts[5] || "",
        funcom_id: parts[6] || "",
        is_guild_admin: /^true$/i.test(parts[7] || "")
      });
    } else if (parts[0] === "actor_rank") {
      objectPermissions.push({
        player_id: parts[1] || "",
        actor_id: parts[2] || "",
        rank: parts[3] || "",
        actor_name: parts[4] || "",
        actor_type: parts[5] || "",
        access_level: parts[6] || ""
      });
    } else if (parts[0] === "access_code") {
      accessCodes.push({
        account_id: parts[1] || "",
        access_code: parts[2] || "",
        access_code_type: parts[3] || "",
        is_resettable: parts[4] || ""
      });
    }
  }
  return {
    ok: true,
    playerControllerId: playerControllerId === null ? "" : String(playerControllerId),
    guildMembers,
    objectPermissions,
    accessCodes,
    isGuildAdmin: guildMembers.some((row) => row.is_guild_admin),
    diagnostics: {
      sourceTables: ["dune.guild_members", "dune.permission_actor_rank", "dune.permission_actor", "dune.player_access_codes", "dune.player_state", "dune.accounts"],
      selectedPlayerControllerId: playerControllerId === null ? "" : String(playerControllerId),
      guildMembersFound: guildMembers.length,
      objectPermissionsFound: objectPermissions.length,
      accessCodesFound: accessCodes.length,
      writePolicy: "Writes call confirmed Dune functions only; no direct permission table insert/update."
    }
  };
}

function previewPermissionRankCall(payload) {
  const actorId = requireInteger(payload.actorId, "actor_id", 0);
  const playerControllerId = requireInteger(payload.playerControllerId, "player_controller_id", 0);
  const rank = requireInteger(payload.rank, "rank", 0, 100);
  const mapId = String(payload.mapId || "").trim();
  if (!/^[A-Za-z0-9_-]{1,80}$/.test(mapId)) throw new Error("map_id must use letters, numbers, underscore, or dash.");
  return {
    actorId,
    playerControllerId,
    rank,
    mapId,
    sql: `select dune.permission_set_player_rank(${actorId}, ${playerControllerId}, ${rank}, ${sqlString(mapId)});`
  };
}

async function adminSetPermissionRank(payload) {
  const call = previewPermissionRankCall(payload || {});
  requireConfirmed(payload?.confirmed);
  await dbQuery(call.sql);
  return {
    ok: true,
    action: "permission_set_player_rank",
    sql: call.sql,
    message: "Object permission rank function executed."
  };
}

function previewAccessCodeCall(payload) {
  const accountId = requireInteger(payload.accountId, "account_id", 0);
  const accessCode = requireInteger(payload.accessCode, "access_code", 0, 2147483647);
  const accessCodeType = requireInteger(payload.accessCodeType, "access_code_type", 0, 2147483647);
  const isResettable = payload.isResettable === true || payload.isResettable === "true" || payload.isResettable === 1 || payload.isResettable === "1";
  return {
    accountId,
    accessCode,
    accessCodeType,
    isResettable,
    sql: `select dune.create_server_player_access_codes(${accountId}, ${accessCode}, ${accessCodeType}, ${isResettable ? "true" : "false"});`
  };
}

async function adminCreateAccessCode(payload) {
  const call = previewAccessCodeCall(payload || {});
  requireConfirmed(payload?.confirmed);
  await dbQuery(call.sql);
  return {
    ok: true,
    action: "create_server_player_access_codes",
    sql: call.sql,
    message: "Access code function executed."
  };
}

function normalizeBaseCleanupRow(line) {
  const [
    actorId = "",
    actorName = "",
    actorType = "",
    buildingIds = "",
    buildingCount = "0",
    instanceCount = "0",
    ownerEntityIds = "",
    refCount = "0",
    matchedRefCount = "0",
    missingRefCount = "0",
    playerRefs = "",
    missingRefs = "",
    status = "unknown"
  ] = String(line || "").split("\t");
  return {
    actorId,
    actorName: actorName || `Base ${actorId || "unknown"}`,
    actorType,
    buildingIds: buildingIds ? buildingIds.split(",").filter(Boolean) : [],
    buildingCount: Number(buildingCount) || 0,
    instanceCount: Number(instanceCount) || 0,
    ownerEntityIds: ownerEntityIds ? ownerEntityIds.split(",").filter(Boolean) : [],
    ownerReferenceCount: Number(refCount) || 0,
    matchedPlayerReferenceCount: Number(matchedRefCount) || 0,
    missingPlayerReferenceCount: Number(missingRefCount) || 0,
    playerRefs,
    missingRefs,
    status,
    orphaned: status === "orphaned",
    deletable: status === "orphaned" && Boolean(actorId)
  };
}

function baseCleanupBaseSql(actorWhere = "") {
  return `
    with base_links as (
      select
        b.id as building_id,
        b.owner_id,
        bi.owner_entity_id,
        bi.instance_id,
        afe.actor_id,
        pa.actor_name,
        pa.actor_type,
        a.owner_account_id
      from dune.buildings b
      left join dune.building_instances bi on bi.building_id = b.id
      left join dune.actor_fgl_entities afe on afe.entity_id = bi.owner_entity_id
      left join dune.actors a on a.id = afe.actor_id
      left join dune.permission_actor pa on pa.actor_id = afe.actor_id
      where afe.actor_id is not null
        ${actorWhere}
    ),
    base_summary as (
      select
        actor_id,
        coalesce(nullif(max(actor_name), ''), 'Base ' || actor_id::text) as actor_name,
        coalesce(max(actor_type)::text, '') as actor_type,
        string_agg(distinct building_id::text, ',' order by building_id::text) as building_ids,
        count(distinct building_id) as building_count,
        count(distinct (building_id::text || ':' || coalesce(instance_id::text, ''))) as instance_count,
        string_agg(distinct owner_entity_id::text, ',' order by owner_entity_id::text) filter (where owner_entity_id is not null) as owner_entity_ids
      from base_links
      group by actor_id
    ),
    owner_refs as (
      select distinct actor_id, owner_id as player_ref, 'buildings.owner_id' as source
      from base_links
      where owner_id is not null
      union
      select distinct actor_id, owner_account_id as player_ref, 'actors.owner_account_id' as source
      from base_links
      where owner_account_id is not null
      union
      select distinct bl.actor_id, par.player_id as player_ref, 'permission_actor_rank.player_id' as source
      from base_links bl
      join dune.permission_actor_rank par on par.permission_actor_id = bl.actor_id
      where par.player_id is not null
    ),
    ref_matches as (
      select
        refs.actor_id,
        refs.player_ref,
        refs.source,
        ps.account_id,
        ps.player_controller_id,
        ps.player_state_id,
        ps.player_pawn_id,
        ps.character_name,
        ps.online_status
      from owner_refs refs
      left join dune.player_state ps
        on ps.account_id = refs.player_ref
        or ps.player_controller_id = refs.player_ref
        or ps.player_state_id = refs.player_ref
        or ps.player_pawn_id = refs.player_ref
    ),
    ref_summary as (
      select
        actor_id,
        count(distinct source || ':' || player_ref::text) as ref_count,
        count(distinct source || ':' || player_ref::text) filter (where account_id is not null) as matched_ref_count,
        count(distinct source || ':' || player_ref::text) filter (where account_id is null) as missing_ref_count,
        string_agg(distinct source || '=' || player_ref::text || ' -> ' || coalesce(character_name, 'missing') || ' (' || coalesce(online_status::text, 'unknown') || ')', '; ' order by source || '=' || player_ref::text || ' -> ' || coalesce(character_name, 'missing') || ' (' || coalesce(online_status::text, 'unknown') || ')') as player_refs,
        string_agg(distinct source || '=' || player_ref::text, '; ' order by source || '=' || player_ref::text) filter (where account_id is null) as missing_refs
      from ref_matches
      group by actor_id
    )
  `;
}

async function adminBaseCleanupScan() {
  const sql = `
    ${baseCleanupBaseSql()}
    select
      bs.actor_id::text,
      replace(bs.actor_name, E'\\t', ' '),
      bs.actor_type,
      coalesce(bs.building_ids, ''),
      bs.building_count::text,
      bs.instance_count::text,
      coalesce(bs.owner_entity_ids, ''),
      coalesce(rs.ref_count, 0)::text,
      coalesce(rs.matched_ref_count, 0)::text,
      coalesce(rs.missing_ref_count, 0)::text,
      replace(coalesce(rs.player_refs, ''), E'\\t', ' '),
      replace(coalesce(rs.missing_refs, ''), E'\\t', ' '),
      case
        when coalesce(rs.ref_count, 0) = 0 then 'unknown-owner'
        when coalesce(rs.matched_ref_count, 0) = 0 then 'orphaned'
        when coalesce(rs.missing_ref_count, 0) > 0 then 'partial-missing'
        else 'owned'
      end as status
    from base_summary bs
    left join ref_summary rs on rs.actor_id = bs.actor_id
    order by
      case
        when coalesce(rs.ref_count, 0) > 0 and coalesce(rs.matched_ref_count, 0) = 0 then 0
        when coalesce(rs.missing_ref_count, 0) > 0 then 1
        when coalesce(rs.ref_count, 0) = 0 then 2
        else 3
      end,
      bs.actor_id
    limit 500
  `;
  const output = await dbQuery(sql, 45000);
  const bases = output ? output.split(/\r?\n/).filter(Boolean).map(normalizeBaseCleanupRow) : [];
  const summary = {
    totalBases: bases.length,
    orphanedBases: bases.filter((row) => row.orphaned).length,
    unknownOwnerBases: bases.filter((row) => row.status === "unknown-owner").length,
    partialMissingBases: bases.filter((row) => row.status === "partial-missing").length,
    ownedBases: bases.filter((row) => row.status === "owned").length,
    buildingRecordsAtRisk: bases.filter((row) => row.orphaned).reduce((sum, row) => sum + row.buildingCount, 0),
    buildingInstancesAtRisk: bases.filter((row) => row.orphaned).reduce((sum, row) => sum + row.instanceCount, 0)
  };
  return {
    ok: true,
    generatedAt: new Date().toISOString(),
    mode: "dry-run",
    bases,
    summary,
    policy: "Orphan deletion requires no player_state match. Owned-base override requires a verified player match, an offline owner, and actor-specific typed confirmation. Unknown-owner bases remain protected."
  };
}

async function adminDeleteOrphanBase(payload = {}) {
  // Actor IDs are PostgreSQL bigint values. Keep the exact string received from
  // the scan rather than round-tripping it through a JavaScript Number.
  const actorId = requireSqlBigint(payload.actorId, "actor_id", 0n);
  requireConfirmed(payload.confirmed);
  const forceOwned = payload.forceOwned === true || payload.forceOwned === "true";
  const expectedConfirmation = `DELETE BASE ${actorId}`;
  if (forceOwned && String(payload.confirmText || "").trim() !== expectedConfirmation) {
    throw new Error(`Owned-base override requires typing ${expectedConfirmation}.`);
  }
  const allowOwnedSql = forceOwned ? "true" : "false";
  const sql = `
    begin;
    ${baseCleanupBaseSql(`and afe.actor_id = ${actorId}`)}
    , delete_target as (
      select
        bs.actor_id,
        case when coalesce(rs.matched_ref_count, 0) = 0 then 'orphaned' else 'owned_override' end as delete_mode
      from base_summary bs
      left join ref_summary rs on rs.actor_id = bs.actor_id
      where bs.actor_id = ${actorId}
        and coalesce(rs.ref_count, 0) > 0
        and (
          coalesce(rs.matched_ref_count, 0) = 0
          or (
            ${allowOwnedSql}
            and coalesce(rs.matched_ref_count, 0) > 0
            and not exists (
              select 1
              from ref_matches rm
              where rm.actor_id = bs.actor_id
                and rm.account_id is not null
                and lower(coalesce(rm.online_status::text, '')) in ('online', 'connected', 'true', '1')
            )
          )
        )
    ),
    target_buildings as (
      select distinct b.id as building_id, bi.owner_entity_id
      from dune.buildings b
      join dune.building_instances bi on bi.building_id = b.id
      join dune.actor_fgl_entities afe on afe.entity_id = bi.owner_entity_id
      join delete_target t on t.actor_id = afe.actor_id
    ),
    deleted_ranks as (
      delete from dune.permission_actor_rank par
      using delete_target t
      where par.permission_actor_id = t.actor_id
      returning 1
    ),
    deleted_permission as (
      delete from dune.permission_actor pa
      using delete_target t
      where pa.actor_id = t.actor_id
      returning 1
    ),
    deleted_instances as (
      delete from dune.building_instances bi
      using target_buildings tb
      where bi.building_id = tb.building_id
      returning 1
    ),
    deleted_buildings as (
      delete from dune.buildings b
      using target_buildings tb
      where b.id = tb.building_id
      returning 1
    ),
    deleted_fgl as (
      delete from dune.actor_fgl_entities afe
      using delete_target t
      where afe.actor_id = t.actor_id
      returning 1
    ),
    deleted_actor as (
      delete from dune.actors a
      using delete_target t
      where a.id = t.actor_id
      returning 1
    )
    select 'deleted',
      (select count(*) from delete_target)::text,
      coalesce((select max(delete_mode) from delete_target), ''),
      (select count(*) from deleted_ranks)::text,
      (select count(*) from deleted_permission)::text,
      (select count(*) from deleted_instances)::text,
      (select count(*) from deleted_buildings)::text,
      (select count(*) from deleted_fgl)::text,
      (select count(*) from deleted_actor)::text;
    commit;
  `;
  const output = await dbQuery(sql, 45000);
  const row = output.split(/\r?\n/).find((line) => line.startsWith("deleted\t"));
  const parts = row ? row.split("\t") : [];
  const matchedTargets = Number(parts[1] || 0);
  if (!matchedTargets) {
    throw new Error(forceOwned
      ? "Base was not deleted. It may not exist, may have no verified owner reference, or a matched owner may still be online."
      : "Base was not deleted because it is no longer orphaned or was not found.");
  }
  const deleteMode = parts[2] || "orphaned";
  const result = {
    ok: true,
    actorId: String(actorId),
    deleteMode,
    forceOwned: deleteMode === "owned_override",
    deletedRanks: Number(parts[3] || 0),
    deletedPermissionActors: Number(parts[4] || 0),
    deletedBuildingInstances: Number(parts[5] || 0),
    deletedBuildings: Number(parts[6] || 0),
    deletedFglLinks: Number(parts[7] || 0),
    deletedActors: Number(parts[8] || 0),
    message: deleteMode === "owned_override" ? `Deleted owned base actor ${actorId} by administrator override.` : `Deleted orphaned base actor ${actorId}.`
  };
  appendAdminAudit(deleteMode === "owned_override" ? "owned_base_override_deleted" : "orphan_base_deleted", result);
  return result;
}

// Legacy progression helpers are intentionally kept out of the active UI/API.
// Phase 1 uses /api/progression/inspect for read-only metadata discovery only.
const SPECIALIZATION_TRACKS = ["Crafting", "Gathering", "Exploration", "Combat", "Sabotage"];

function requireTrack(value) {
  const clean = String(value || "").trim();
  if (!SPECIALIZATION_TRACKS.includes(clean)) {
    throw new Error(`Track must be one of: ${SPECIALIZATION_TRACKS.join(", ")}.`);
  }
  return clean;
}

async function adminSkillReputation(playerControllerIdValue) {
  const playerControllerId = optionalInteger(playerControllerIdValue, "player_controller_id", 0);
  const trackWhere = playerControllerId === null ? "" : `where st.player_id = ${playerControllerId}`;
  const repWhere = playerControllerId === null ? "" : `where pfr.actor_id = ${playerControllerId}`;
  const factionWhere = playerControllerId === null ? "" : `where pf.actor_id = ${playerControllerId}`;
  const sql = `
    select 'track', st.player_id::text, st.track_type::text, st.xp_amount::text, st.level::text
    from dune.specialization_tracks st
    ${trackWhere}
    order by st.player_id, st.track_type;

    select 'reputation', pfr.actor_id::text, pfr.faction_id::text, coalesce(f.name, ''), pfr.reputation_amount::text
    from dune.player_faction_reputation pfr
    left join dune.factions f on f.id = pfr.faction_id
    ${repWhere}
    order by pfr.actor_id, pfr.faction_id;

    select 'current_faction', pf.actor_id::text, pf.faction_id::text, coalesce(f.name, ''), coalesce(pf.utc_time_faction_change::text, '')
    from dune.player_faction pf
    left join dune.factions f on f.id = pf.faction_id
    ${factionWhere}
    order by pf.actor_id;

    select 'faction', id::text, name, '', '' from dune.factions order by id;
  `;
  const output = await dbQuery(sql);
  const tracks = [];
  const reputation = [];
  const currentFactions = [];
  const factions = [];
  for (const line of output.split(/\r?\n/).filter(Boolean)) {
    const parts = line.split("\t");
    if (parts[0] === "track") {
      tracks.push({ player_id: parts[1] || "", track_type: parts[2] || "", xp_amount: parts[3] || "0", level: parts[4] || "0" });
    } else if (parts[0] === "reputation") {
      reputation.push({ actor_id: parts[1] || "", faction_id: parts[2] || "", faction_name: parts[3] || "", reputation_amount: parts[4] || "0" });
    } else if (parts[0] === "current_faction") {
      currentFactions.push({ actor_id: parts[1] || "", faction_id: parts[2] || "", faction_name: parts[3] || "", changed_at: parts[4] || "" });
    } else if (parts[0] === "faction") {
      factions.push({ id: parts[1] || "", name: parts[2] || "" });
    }
  }
  return {
    ok: true,
    playerControllerId: playerControllerId === null ? "" : String(playerControllerId),
    availableTracks: SPECIALIZATION_TRACKS,
    tracks,
    reputation,
    currentFactions,
    factions,
    warning: "Live pickup is not confirmed for specialization XP/level or reputation. A player relog or server restart may be required."
  };
}

async function currentTrackRow(playerControllerId, track) {
  const sql = `
    select xp_amount::text, level::text
    from dune.specialization_tracks
    where player_id = ${playerControllerId}
      and track_type = ${sqlString(track)}::dune.specializationtracktype
  `;
  const output = await dbQuery(sql);
  if (!output) return null;
  const [xp = "0", level = "0"] = output.split(/\t/);
  return { xp_amount: Number(xp) || 0, level: Number(level) || 0 };
}

function specializationCall(playerControllerId, track, xpAmount, level) {
  return `begin;
set local search_path to dune, public;
select dune.set_specialization_xp_and_level(${playerControllerId}, ${sqlString(track)}::dune.specializationtracktype, ${xpAmount}, ${level});
commit;`;
}

async function adminSpecializationAction(payload, mode) {
  const playerControllerId = requireInteger(payload?.playerControllerId, "player_controller_id", 0);
  const track = requireTrack(payload?.trackType);
  const previous = await currentTrackRow(playerControllerId, track);
  const amount = requireInteger(payload?.xpAmount, mode === "add" ? "xp_to_add" : "xp_amount", 0, 2147483647);
  const levelInput = payload?.level === undefined || payload?.level === null || String(payload.level).trim() === "" ? null : requireReal(payload.level, "level", 0, 1000);
  const nextXp = mode === "add" ? (previous?.xp_amount || 0) + amount : amount;
  const nextLevel = levelInput === null ? (previous?.level || 0) : levelInput;
  const sql = specializationCall(playerControllerId, track, nextXp, nextLevel);
  requireConfirmed(payload?.confirmed);
  await dbQuery(sql);
  const result = {
    ok: true,
    action: mode === "add" ? "give_skill_points" : "set_skill_points",
    sql,
    previous,
    next: { xp_amount: nextXp, level: nextLevel },
    rollbackSql: previous
      ? specializationCall(playerControllerId, track, previous.xp_amount, previous.level)
      : `delete from dune.specialization_tracks where player_id = ${playerControllerId} and track_type = ${sqlString(track)}::dune.specializationtracktype;`,
    warning: "Live pickup is not confirmed. Player relog or server restart may be required."
  };
  appendAdminAudit(result.action, { playerControllerId, track, previous, next: result.next, sql, rollbackSql: result.rollbackSql });
  return result;
}

async function currentReputationRow(playerControllerId, factionId) {
  const sql = `
    select reputation_amount::text
    from dune.player_faction_reputation
    where actor_id = ${playerControllerId}
      and faction_id = ${factionId}
  `;
  const output = await dbQuery(sql);
  if (!output) return null;
  return { reputation_amount: Number(output.trim()) || 0 };
}

function reputationCall(playerControllerId, factionId, amount) {
  return `select dune.set_player_faction_reputation(${playerControllerId}, ${factionId}::smallint, ${amount});`;
}

async function adminReputationAction(payload, mode) {
  const playerControllerId = requireInteger(payload?.playerControllerId, "player_controller_id", 0);
  const factionId = requireInteger(payload?.factionId, "faction_id", 1, 32767);
  const previous = await currentReputationRow(playerControllerId, factionId);
  const amount = mode === "add"
    ? requireInteger(payload?.reputationAmount, "reputation_to_add", 0, 2147483647)
    : requireInteger(payload?.reputationAmount, "reputation_amount", 0, 2147483647);
  const nextAmount = mode === "add" ? (previous?.reputation_amount || 0) + amount : amount;
  const sql = reputationCall(playerControllerId, factionId, nextAmount);
  requireConfirmed(payload?.confirmed);
  await dbQuery(sql);
  const result = {
    ok: true,
    action: mode === "add" ? "add_reputation" : "set_reputation",
    sql,
    previous,
    next: { reputation_amount: nextAmount },
    rollbackSql: previous
      ? reputationCall(playerControllerId, factionId, previous.reputation_amount)
      : `delete from dune.player_faction_reputation where actor_id = ${playerControllerId} and faction_id = ${factionId};`,
    warning: "Live pickup is not confirmed. Player relog or server restart may be required."
  };
  appendAdminAudit(result.action, { playerControllerId, factionId, previous, next: result.next, sql, rollbackSql: result.rollbackSql });
  return result;
}

async function adminTunedChannels() {
  const sql = `
    select
      coalesce(p.account_id::text, c.account_id::text) as account_id,
      coalesce(p.selected_channel_name::text, '') as selected_channel,
      coalesce(c.channel_name::text, '') as channel_name,
      coalesce(c.is_tuned::text, '') as is_tuned
    from dune.communinet_player p
    full outer join dune.communinet_player_channels c on c.account_id = p.account_id
    order by account_id, channel_name
    limit 300
  `;
  const output = await dbQuery(sql);
  const rows = output ? output.split(/\r?\n/).filter(Boolean).map((line) => {
    const [accountId = "", selectedChannel = "", channelName = "", isTuned = ""] = line.split("\t");
    return { accountId, selectedChannel, channelName, isTuned };
  }) : [];
  return { ok: true, rows };
}

function logLiveGiveStartupValidation() {
  const config = giveTransportConfig();
  const selected = transportDisplayName(config.mode);
  const missing = config.missingEnv || [];
  console.log(`Live give-item transport: ${selected}`);
  if (config.configured) {
    console.log("Live give-item env: configured");
    return;
  }
  if (missing.length) {
    console.log(`Live give-item dry-run: missing ${missing.map((name) => LIVE_GIVE_SECRET_ENV_NAMES.has(name) ? `${name}=<secret missing>` : name).join(", ")}`);
    return;
  }
  console.log(`Live give-item dry-run: ${config.reason || "transport is not configured"}`);
}

function attemptConfiguredServerStart(source = "startup") {
  try {
    assertWorkloadStartAllowed("start the battlegroup");
  } catch (error) {
    appendAdminAudit("server_start_suppressed", { source, reason: error.code || "migration_maintenance", maintenance: migrationMaintenance.status() });
    return;
  }
  const readiness = serverControlConfigured();
  if (runtimeGiveTransport.serverOnline) return;
  if (!readiness.configured) {
    appendAdminAudit("server_start_skipped", {
      source,
      reason: readiness.reason,
      config: readiness.summary
    });
    return;
  }
  appendAdminAudit("server_start_requested", {
    source,
    config: readiness.summary
  });
  battlegroup("start", {
    operationId: `startup-${Date.now()}-${crypto.randomBytes(4).toString("hex")}`,
    reason: `Startup ensure-server-running hook (${source})`,
    callSite: "server.js:attemptConfiguredServerStart"
  }).then((result) => {
    appendAdminAudit(result.ok ? "server_start_request_completed" : "server_start_request_failed", {
      source,
      ok: Boolean(result.ok),
      skipped: Boolean(result.skipped),
      error: result.error || result.stderr || ""
    });
  }).catch((error) => {
    appendAdminAudit("server_start_request_failed", {
      source,
      ok: false,
      error: error.message
    });
  });
}

async function directorUrl() {
  const info = await vmInfo();
  if (!info.exists || info.state !== "Running" || !info.ip) return { ok: false, error: "VM is not running or has no IP." };
  const result = await sshCommand("sudo kubectl get svc -A -o jsonpath='{.items[*].spec.ports[?(@.port==11717)].nodePort}' 2>&1", 30000);
  const port = (result.stdout || "").trim();
  if (!/^\d+$/.test(port)) return { ok: false, error: result.stdout || result.stderr || "Could not find director port." };
  lastDirectorUrl = `http://${info.ip}:${port}`;
  return { ok: true, url: lastDirectorUrl };
}

function contentTypeFor(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  if (ext === ".html") return "text/html";
  if (ext === ".js") return "text/javascript";
  if (ext === ".css") return "text/css";
  if (ext === ".json") return "application/json";
  if (ext === ".webmanifest") return "application/manifest+json";
  if (ext === ".png") return "image/png";
  if (ext === ".jpg" || ext === ".jpeg") return "image/jpeg";
  if (ext === ".svg") return "image/svg+xml";
  if (ext === ".webp") return "image/webp";
  if (ext === ".ico") return "image/x-icon";
  return "application/octet-stream";
}

function unquoteEnvValue(value) {
  const trimmed = String(value || "").trim();
  if ((trimmed.startsWith('"') && trimmed.endsWith('"')) || (trimmed.startsWith("'") && trimmed.endsWith("'"))) {
    return trimmed.slice(1, -1);
  }
  return trimmed;
}

function normalizeExecutablePath(value) {
  let executable = unquoteEnvValue(value).trim();
  executable = executable.replace(/^\uFEFF/, "");
  executable = unquoteEnvValue(executable).trim();
  if (IS_WINDOWS) {
    executable = executable.replace(/\//g, "\\");
  }
  if (!executable) return "";
  return path.normalize(executable);
}

function readEnvValue(filePath, name) {
  if (!filePath || !fs.existsSync(filePath)) return "";
  const lines = fs.readFileSync(filePath, "utf8").split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (match && match[1] === name) return normalizeExecutablePath(expandEnvPath(match[2]));
  }
  return "";
}

function envFilesByName(fileName) {
  return [
    APPDATA_DIR ? path.join(APPDATA_DIR, fileName) : "",
    path.join(__dirname, fileName)
  ].filter(Boolean);
}

function commandAvailable(command) {
  const result = spawnSync(command, ["--version"], {
    windowsHide: true,
    stdio: "ignore",
    timeout: 5000
  });
  return !result.error && result.status === 0;
}

function configuredPythonPath() {
  for (const filePath of envFilesByName(".env.local")) {
    const pythonPath = readEnvValue(filePath, "PYTHON_PATH");
    if (pythonPath) return { command: pythonPath, source: filePath };
  }
  for (const filePath of envFilesByName(".env")) {
    const pythonPath = readEnvValue(filePath, "PYTHON_PATH");
    if (pythonPath) return { command: pythonPath, source: filePath };
  }
  return null;
}

function installedPythonCandidates() {
  if (!IS_WINDOWS) return [];
  const roots = [
    process.env.LOCALAPPDATA ? path.join(process.env.LOCALAPPDATA, "Programs", "Python") : "",
    process.env.ProgramFiles ? path.join(process.env.ProgramFiles, "Python") : "",
    process.env["ProgramFiles(x86)"] ? path.join(process.env["ProgramFiles(x86)"], "Python") : ""
  ].filter(Boolean);
  const candidates = [];
  for (const root of roots) {
    try {
      const installs = fs.readdirSync(root, { withFileTypes: true })
        .filter((entry) => entry.isDirectory() && /^Python\d+$/i.test(entry.name))
        .sort((a, b) => b.name.localeCompare(a.name, undefined, { numeric: true }));
      for (const install of installs) {
        candidates.push(path.join(root, install.name, "python.exe"));
      }
    } catch {
      // The standard install root is optional; continue to the next location.
    }
  }
  return [...new Set(candidates)];
}

function findPython() {
  const configured = configuredPythonPath();
  if (configured) {
    const exists = fs.existsSync(configured.command);
    console.log(`Manager service PYTHON_PATH: ${configured.command} (${configured.source}) exists=${exists}`);
    if (exists || isWindowsAppsAlias(configured.command)) {
      return { command: configured.command, source: `PYTHON_PATH from ${configured.source}`, exists };
    }
    console.warn(`Configured PYTHON_PATH was not found: ${configured.command} (${configured.source})`);
  }
  if (commandAvailable("python3")) return { command: "python3", source: "PATH", exists: true };
  if (commandAvailable("python")) return { command: "python", source: "PATH", exists: true };
  if (commandAvailable("py")) return { command: "py", source: "PATH", exists: true };
  for (const command of installedPythonCandidates()) {
    if (commandAvailable(command)) {
      return { command, source: "standard Windows install location", exists: true };
    }
  }
  return null;
}

function isWindowsAppsAlias(command) {
  return IS_WINDOWS && /\\WindowsApps\\/i.test(String(command || ""));
}

function managerSpawnDetails(resolved, args, useShell, reason = "") {
  const executable = resolved?.command || "";
  return {
    reason,
    command: executable,
    source: resolved?.source || "",
    cwd: MANAGER_DIR,
    args,
    shell: Boolean(useShell),
    executableExists: executable ? fs.existsSync(executable) : false,
    isWindowsAppsAlias: isWindowsAppsAlias(executable),
    ComSpec: process.env.ComSpec || "",
    SystemRoot: process.env.SystemRoot || "",
    PATH: process.env.PATH || "",
    PYTHONPATH: process.env.PYTHONPATH || ""
  };
}

function logManagerSpawnDetails(details) {
  const attempts = Array.isArray(managerSpawnDiagnostics?.attempts) ? managerSpawnDiagnostics.attempts : [];
  managerSpawnDiagnostics = { ...details, attempts: [...attempts, details] };
  console.log(`Manager service spawn diagnostics: ${JSON.stringify(details)}`);
}

function managerErrorPayload(error) {
  return {
    ok: false,
    error: error || managerFallbackWarning(),
    spawnDiagnostics: managerSpawnDiagnostics
  };
}

function logPythonResolution(resolved) {
  const message = resolved
    ? `Manager service Python command resolved: ${resolved.command} (${resolved.source}) exists=${resolved.exists}`
    : "Manager service warning: Python was not found. Set PYTHON_PATH in .env.local or install python/py.";
  if (message === loggedPythonCommand) return;
  loggedPythonCommand = message;
  console.log(message);
}

function defaultManagerConfig() {
  const sshKeyPath = process.env.LOCALAPPDATA ? path.join(process.env.LOCALAPPDATA, "DuneAwakeningServer", "sshKey") : "";
  return { vmIp: "", sshKeyPath, sshUser: "dune", battlegroup: "", namespace: "", source: "" };
}

function storageDisplayName(actorClass) {
  const match = String(actorClass || "").match(/\/([^/.]+)\.[^/.]+_C$/);
  return String(match?.[1] || "Storage")
    .replace(/^BP_/, "")
    .replace(/_CHOAM$/i, "")
    .replace(/_/g, " ")
    .replace(/\bMediumStorageContainer\b/i, "Medium Storage Container")
    .replace(/\bItemContainerBase\b/i, "Storage Container")
    .replace(/\bSpiceSiloContainer\b/i, "Spice Silo")
    .replace(/\bContainerVehicle\b/i, "Carrier Cargo Vehicle")
    .trim();
}

const STORAGE_CUSTOM_NAME_SQL = `
  coalesce((
    select max(nullif(btrim(pa.actor_name), ''))
    from dune.permission_actor pa
    where pa.actor_id = a.id
      and btrim(coalesce(pa.actor_name, '')) <> ''
      and pa.actor_name not like '##%'
      and lower(btrim(pa.actor_name)) <> 'none'
  ), '')
`;

async function adminStorageTargets() {
  const sql = `
    select
      a.id::text,
      i.id::text,
      coalesce(i.inventory_type::text, ''),
      coalesce(i.max_item_count::text, '0'),
      coalesce(i.max_item_volume::text, '0'),
       (select count(*)::text from dune.items it where it.inventory_id=i.id),
       (select coalesce(max(it.position_index), -1)::text from dune.items it where it.inventory_id=i.id),
       a.class,
       replace(${STORAGE_CUSTOM_NAME_SQL}, E'\\t', ' '),
       coalesce(a.map, ''),
       coalesce(a.partition_id::text, ''),
       coalesce(a.dimension_index::text, ''),
      coalesce(((a.transform).location).x::text, ''),
      coalesce(((a.transform).location).y::text, ''),
      coalesce(((a.transform).location).z::text, ''),
      coalesce((select jsonb_object_agg(stacks.template_id, stacks.total) from (
        select it.template_id, sum(it.stack_size) total from dune.items it where it.inventory_id=i.id group by it.template_id
      ) stacks), '{}'::jsonb)::text
    from dune.actors a
    join dune.inventories i on i.actor_id = a.id
    where (
      (i.inventory_type = 4 and a.class ilike '%Container%')
      or (i.inventory_type = 0 and coalesce(i.max_item_count, 0) > 0 and a.class ilike '%Vehicles%')
    )
      and a.class not ilike '%PlayerCharacter%'
    order by a.map, a.partition_id, a.dimension_index, a.class, a.id
  `;
  const output = await dbQuery(sql, 20000);
  const rows = parseDbRows(output, ["actorId", "inventoryId", "inventoryType", "maxItemCount", "maxItemVolume", "itemCount", "maxPosition", "actorClass", "customName", "map", "partitionId", "dimensionIndex", "x", "y", "z", "items"]);
  return {
    ok: true,
    storages: rows.map((row) => {
      let storedItems = {};
      try { storedItems = JSON.parse(row.items || "{}"); } catch {}
      const usedVolume = Object.entries(storedItems).reduce((sum, [template, count]) => sum + storageItemMetadata(template).volume * Math.max(0, Number(count) || 0), 0);
      const contents = Object.entries(storedItems).map(([template, count]) => {
        const item = itemCatalogProvider.resolve(template);
        return { template, name: item?.name || template, count: Number(count) || 0, source: item?.source || "raw-id", icon: item?.icon || "" };
      }).sort((a, b) => a.name.localeCompare(b.name));
      const typeName = storageDisplayName(row.actorClass);
      const customName = String(row.customName || "").trim();
      return {
        actorId: row.actorId,
        inventoryId: row.inventoryId,
        inventoryType: Number(row.inventoryType),
        name: customName || typeName,
        customName,
        typeName,
        kind: Number(row.inventoryType) === 4 ? "Placeable Storage" : "Vehicle Cargo",
        actorClass: row.actorClass,
        map: row.map,
        partitionId: row.partitionId,
        dimensionIndex: Number(row.dimensionIndex || 0),
        position: { x: Number(row.x), y: Number(row.y), z: Number(row.z) },
        itemCount: Number(row.itemCount || 0),
        maxItemCount: Number(row.maxItemCount || 0),
        usedVolume: Math.round(usedVolume * 100) / 100,
        maxItemVolume: Number(row.maxItemVolume || 0),
        volumeVerified: Object.keys(storedItems).every((template) => storageItemMetadata(template).volume > 0),
        contents
      };
    })
  };
}

async function adminGiveItemToStorage(payload = {}) {
  const playerId = String(payload.playerId || "").trim();
  const template = String(payload.template || "").trim();
  const inventoryId = requireInteger(payload.inventoryId, "storage inventory", 1);
  const actorId = requireInteger(payload.actorId, "storage actor", 1);
  const qty = requireInteger(payload.qty, "quantity", 1, 50000);
  const grade = requireInteger(payload.quality ?? 0, "grade", 0, 5);
  const mode = String(payload.mode || "dry-run").toLowerCase();
  const dryRun = mode !== "execute";
  if (!playerId) throw new Error("Choose the player associated with this storage deposit.");
  if (!isValidTemplateId(template)) throw new Error("Choose a valid exact item template identifier.");
  if (!dryRun && payload.confirmed !== true) throw new Error("Confirm the storage deposit before writing to the database.");
  const catalogItem = giveItemCatalogItem(template);
  const durability = durabilityExpectation(catalogItem, payload.setDurabilityTo200);
  const durabilityEvidence = await investigateGiveItemDurability(template);
  assertAuthoritativeDurabilityEvidence(durability, durabilityEvidence);
  const playerPredicate = [
    `ps.account_id::text = ${sqlString(playerId)}`,
    `ps.player_controller_id::text = ${sqlString(playerId)}`,
    `ps.player_pawn_id::text = ${sqlString(playerId)}`,
    `ps.player_state_id::text = ${sqlString(playerId)}`,
    `lower(ps.character_name) = lower(${sqlString(playerId)})`
  ].join(" or ");
  const precheckSql = `
    with target_player as (
      select ps.account_id::text account_id, coalesce(ps.character_name, ps.account_id::text) character_name,
             coalesce(ps.online_status::text, 'unknown') online_status
      from dune.player_state ps where ${playerPredicate}
      order by ps.last_avatar_activity desc nulls last limit 1
    ), target_storage as (
      select i.id inventory_id, i.actor_id, i.inventory_type, coalesce(i.max_item_count, 0) max_item_count,
             coalesce(i.max_item_volume, 0) max_item_volume, a.class, ${STORAGE_CUSTOM_NAME_SQL} custom_name,
             a.map, a.partition_id, a.dimension_index,
             (select count(*)::int from dune.items it where it.inventory_id=i.id) item_count,
             (select coalesce(max(it.position_index), -1)::bigint from dune.items it where it.inventory_id=i.id) max_position,
             (select count(*)::int from (
               select it.position_index from dune.items it
               where it.inventory_id=i.id and it.position_index is not null
               group by it.position_index having count(*) > 1
             ) conflicts) duplicate_slots,
             (select count(*)::int from dune.items it
               where it.inventory_id=i.id and (it.position_index < 0 or (coalesce(i.max_item_count,0) > 0 and it.position_index >= i.max_item_count))) invalid_positions,
             coalesce((select jsonb_object_agg(stacks.template_id, stacks.total) from (
               select it.template_id, sum(it.stack_size) total from dune.items it where it.inventory_id=i.id group by it.template_id
             ) stacks), '{}'::jsonb)::text item_stacks
      from dune.inventories i join dune.actors a on a.id=i.actor_id
      where i.id=${inventoryId} and i.actor_id=${actorId}
        and (((i.inventory_type=4) and a.class ilike '%Container%') or (i.inventory_type=0 and coalesce(i.max_item_count,0)>0 and a.class ilike '%Vehicles%'))
        and a.class not ilike '%PlayerCharacter%'
    )
    select case when not exists(select 1 from target_player) then 'player_not_found'
                when lower((select online_status from target_player)) not in ('offline','disconnected','inactive') then 'player_not_offline'
                when not exists(select 1 from target_storage) then 'storage_not_found'
                else 'ready' end,
           coalesce((select account_id from target_player),''), coalesce((select character_name from target_player),''),
           coalesce((select online_status from target_player),''), coalesce((select class from target_storage),''),
           coalesce((select custom_name from target_storage),''),
           coalesce((select map from target_storage),''), coalesce((select partition_id::text from target_storage),''),
           coalesce((select dimension_index::text from target_storage),''), coalesce((select max_item_count::text from target_storage),'0'),
           coalesce((select max_item_volume::text from target_storage),'0'), coalesce((select item_count::text from target_storage),'0'),
           coalesce((select max_position::text from target_storage),'-1'), coalesce((select duplicate_slots::text from target_storage),'0'),
           coalesce((select invalid_positions::text from target_storage),'0'), coalesce((select item_stacks from target_storage),'{}')
  `;
  const precheck = parseDbRows(await dbQuery(precheckSql, 15000), ["status", "accountId", "characterName", "onlineStatus", "actorClass", "customName", "map", "partitionId", "dimensionIndex", "maxItemCount", "maxItemVolume", "itemCount", "maxPosition", "duplicateSlots", "invalidPositions", "itemStacks"])[0] || {};
  if (precheck.status === "player_not_found") throw new Error("The selected player was not found.");
  if (precheck.status === "player_not_offline") throw new Error(`${precheck.characterName || "Selected player"} must be offline before depositing items into storage. Current status: ${precheck.onlineStatus || "unknown"}.`);
  if (precheck.status === "storage_not_found") throw new Error("The selected storage actor or inventory no longer exists. Refresh storage containers.");
  if (precheck.status !== "ready") throw new Error(`Storage deposit precheck failed: ${precheck.status || "unknown"}.`);
  if (Number(precheck.duplicateSlots || 0) > 0) throw new Error("This storage container has duplicate occupied slot positions. Repair its inventory integrity before depositing another item.");
  if (Number(precheck.invalidPositions || 0) > 0) throw new Error("This storage container has items outside its valid slot range. Repair its inventory integrity before depositing another item.");
  const metadata = storageItemMetadata(template);
  const stackCount = Math.ceil(qty / metadata.stackMax);
  const availableSlots = Number(precheck.maxItemCount || 0) > 0 ? Number(precheck.maxItemCount) - Number(precheck.itemCount || 0) : Number.MAX_SAFE_INTEGER;
  if (stackCount > availableSlots) throw new Error(`Storage needs ${stackCount} free slot(s), but only ${Math.max(0, availableSlots)} are available.`);
  const itemVolume = metadata.volume * qty;
  let itemStacks = {};
  try { itemStacks = JSON.parse(precheck.itemStacks || "{}"); } catch {}
  const volumeVerified = metadata.volume > 0 && Object.keys(itemStacks).every((storedTemplate) => storageItemMetadata(storedTemplate).volume > 0);
  const usedVolume = Object.entries(itemStacks).reduce((sum, [storedTemplate, count]) => sum + storageItemMetadata(storedTemplate).volume * Math.max(0, Number(count) || 0), 0);
  const maxItemVolume = Number(precheck.maxItemVolume || 0);
  if (volumeVerified && maxItemVolume > 0 && usedVolume + itemVolume > maxItemVolume) throw new Error(`Storage volume would exceed capacity: ${Math.round((usedVolume + itemVolume) * 100) / 100} required / ${maxItemVolume} maximum.`);
  const typeName = storageDisplayName(precheck.actorClass);
  const customName = String(precheck.customName || "").trim();
  const storage = { actorId: String(actorId), inventoryId: String(inventoryId), name: customName || typeName, customName, typeName, actorClass: precheck.actorClass, map: precheck.map, partitionId: precheck.partitionId, dimensionIndex: Number(precheck.dimensionIndex || 0), itemCount: Number(precheck.itemCount || 0), maxItemCount: Number(precheck.maxItemCount || 0), usedVolume: Math.round(usedVolume * 100) / 100, maxItemVolume, volumeVerified };
  if (dryRun) return { ok: true, dryRun: true, status: "dry-run-passed", transport: "database", player: { accountId: precheck.accountId, characterName: precheck.characterName, onlineStatus: precheck.onlineStatus }, storage, item: { id: template, name: giveItemDisplayName(template), qty, grade, stackCount, stackMax: metadata.stackMax, volume: itemVolume, durability }, durability, durabilityEvidence, note: `Player is offline. Storage target, identity, capacity, free slots, and durability applicability were validated. No database write was performed. ${durability.applicable ? durability.reason : "Durability not applicable; no durability data will be written."}` };
  const statsJson = itemStatsJsonForGrant(durability);
  const insertSql = `
    begin;
    set local search_path=dune,public;
    do $$ begin
      if not exists(select 1 from dune.player_state ps where (${playerPredicate}) and lower(coalesce(ps.online_status::text,'unknown')) in ('offline','disconnected','inactive')) then
        raise exception 'Selected player is no longer offline';
      end if;
    end $$;
    select i.id from dune.inventories i join dune.actors a on a.id=i.actor_id
      where i.id=${inventoryId} and i.actor_id=${actorId}
        and (((i.inventory_type=4) and a.class ilike '%Container%') or (i.inventory_type=0 and coalesce(i.max_item_count,0)>0 and a.class ilike '%Vehicles%'))
      for update of i;
    create temp table storage_grant_target on commit drop as
      select i.id inventory_id, i.actor_id, coalesce(i.max_item_count,0)::int max_item_count,
             (select count(*)::int from dune.items it where it.inventory_id=i.id) item_count,
             (select coalesce(max(it.position_index),-1)::bigint from dune.items it where it.inventory_id=i.id) max_position
      from dune.inventories i join dune.actors a on a.id=i.actor_id
      where i.id=${inventoryId} and i.actor_id=${actorId}
        and (((i.inventory_type=4) and a.class ilike '%Container%') or (i.inventory_type=0 and coalesce(i.max_item_count,0)>0 and a.class ilike '%Vehicles%'))
      limit 1;
    create temp table storage_grant_slots on commit drop as
      select candidate.position_index,
             row_number() over (order by candidate.position_index)::int slot_number
      from storage_grant_target t
      cross join lateral (
        select free_slot.position_index::bigint
        from generate_series(0, greatest(t.max_item_count-1, 0)) free_slot(position_index)
        where t.max_item_count>0
          and not exists(select 1 from dune.items occupied where occupied.inventory_id=t.inventory_id and occupied.position_index=free_slot.position_index)
        order by free_slot.position_index
        limit ${stackCount}
      ) candidate
      union all
      select (t.max_position+n)::bigint, n::int
      from storage_grant_target t cross join generate_series(1,${stackCount}) n
      where t.max_item_count<=0;
    do $$ begin
      if (select count(*) from storage_grant_slots) <> ${stackCount} then
        raise exception 'Storage no longer has enough valid free slots';
      end if;
    end $$;
    create temp table storage_grant_prepared on commit drop as
      select nextval('dune.items_id_seq'::regclass) item_id, t.inventory_id,
             least(${metadata.stackMax}, ${qty}-(s.slot_number-1)*${metadata.stackMax})::bigint stack_size,
             s.position_index
      from storage_grant_target t cross join storage_grant_slots s;
    select dune.save_item(row(p.item_id,p.inventory_id,p.stack_size,p.position_index,${sqlString(template)},true,extract(epoch from clock_timestamp())::bigint,${sqlString(statsJson)}::jsonb,${grade},null)::dune.inventoryitem) from storage_grant_prepared p;
    do $$ begin
      if not coalesce((select count(*)=${stackCount} and coalesce(sum(i.stack_size),0)=${qty}
                       and count(distinct i.position_index)=count(*)
                       and bool_and(i.position_index>=0 and (t.max_item_count<=0 or i.position_index<t.max_item_count))
                       and bool_and((select count(*) from dune.items occupied where occupied.inventory_id=i.inventory_id and occupied.position_index=i.position_index)=1)
                       and bool_and(${durability.applied
                         ? `jsonb_typeof(i.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}')='number' and (i.stats #>> '${GIVE_ITEM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE} and jsonb_typeof(i.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')='number' and (i.stats #>> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE}`
                         : `i.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}' is null and i.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}' is null`})
                from storage_grant_prepared p
                join dune.items i on i.id=p.item_id and i.inventory_id=p.inventory_id and i.template_id=${sqlString(template)}
                cross join storage_grant_target t
                group by t.max_item_count),false) then
        raise exception 'Storage deposit failed transactional slot and quantity verification';
      end if;
    end $$;
    select case when count(*)=${stackCount} and coalesce(sum(i.stack_size),0)=${qty}
                       and count(distinct i.position_index)=count(*)
                       and bool_and(i.position_index>=0 and (t.max_item_count<=0 or i.position_index<t.max_item_count))
                       and bool_and((select count(*) from dune.items occupied where occupied.inventory_id=i.inventory_id and occupied.position_index=i.position_index)=1)
                     then 'inserted' else 'verification_failed' end,
           count(*)::text, coalesce(sum(i.stack_size),0)::text,
           coalesce(string_agg(i.id::text,',' order by i.id),''),
           coalesce(string_agg(i.position_index::text,',' order by i.id),''),
           count(*) filter(where i.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}' is not null)::text,
           count(*) filter(where jsonb_typeof(i.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}')='number')::text,
           count(*) filter(where jsonb_typeof(i.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}')='number' and (i.stats #>> '${GIVE_ITEM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE})::text,
           count(*) filter(where i.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}' is not null)::text,
           count(*) filter(where jsonb_typeof(i.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')='number')::text,
           count(*) filter(where jsonb_typeof(i.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')='number' and (i.stats #>> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE})::text
      from storage_grant_prepared p
      join dune.items i on i.id=p.item_id and i.inventory_id=p.inventory_id and i.template_id=${sqlString(template)}
      cross join storage_grant_target t
      group by t.max_item_count;
    commit;
  `;
  const resultRows = parseDbRows(await dbQuery(insertSql, 30000), ["status", "stackCount", "quantity", "itemIds", "positions", "durabilityPresentStacks", "numericDurabilityStacks", "exactDurabilityStacks", "maximumDurabilityPresentStacks", "numericMaximumDurabilityStacks", "exactMaximumDurabilityStacks"]);
  const inserted = [...resultRows].reverse().find((row) => row.status === "inserted" || row.status === "verification_failed") || {};
  if (inserted.status !== "inserted") throw new Error("Storage deposit did not pass post-write verification; inspect the database before retrying.");
  const itemIds = String(inserted.itemIds || "").split(",").filter(Boolean);
  const positions = String(inserted.positions || "").split(",").filter(Boolean).map(Number);
  const durabilityReadBack = { foundStacks: Number(inserted.stackCount || 0), durabilityPresentStacks: Number(inserted.durabilityPresentStacks || 0), numericDurabilityStacks: Number(inserted.numericDurabilityStacks || 0), exactDurabilityStacks: Number(inserted.exactDurabilityStacks || 0), maximumDurabilityPresentStacks: Number(inserted.maximumDurabilityPresentStacks || 0), numericMaximumDurabilityStacks: Number(inserted.numericMaximumDurabilityStacks || 0), exactMaximumDurabilityStacks: Number(inserted.exactMaximumDurabilityStacks || 0) };
  const durabilityVerification = classifyDurabilityReadBack(durability, durabilityReadBack);
  if (!durabilityVerification.ok) throw new Error(durabilityVerification.message);
  const receiptId = `storage-${Date.now()}-${crypto.randomBytes(4).toString("hex")}`;
  const receipt = {
    receiptId,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    status: "database-verified",
    visibility: "unknown",
    confirmedVisible: false,
    checkCount: 0,
    player: { accountId: precheck.accountId, characterName: precheck.characterName },
    storage,
    item: { id: template, name: giveItemDisplayName(template), quantity: Number(inserted.quantity || qty), grade, stackCount: Number(inserted.stackCount || stackCount), itemIds, positions, durability },
    durability,
    durabilityEvidence,
    verification: { durability: durabilityReadBack },
    preFingerprint: crypto.createHash("sha256").update(String(precheck.itemStacks || "{}")).digest("hex")
  };
  let receiptWarning = "";
  try { storageDepositStore.add(receipt); }
  catch (error) { receiptWarning = ` The database write succeeded, but the receipt could not be persisted to disk: ${error.message}`; }
  const result = { ok: true, dryRun: false, status: "storage-inserted", transport: "database", verified: true, player: { accountId: precheck.accountId, characterName: precheck.characterName, onlineStatus: precheck.onlineStatus }, storage, item: { id: template, name: giveItemDisplayName(template), qty: Number(inserted.quantity || qty), grade, stackCount: Number(inserted.stackCount || stackCount), stackMax: metadata.stackMax, volume: itemVolume, itemIds, positions, durability }, durability, durabilityEvidence, durabilityVerification, receipt, note: `Database write, destination read-back, slot integrity, and durability verification passed. ${durability.display}. Reopen the container to check game visibility; the Suite will continue checking that the rows remain stable.` + receiptWarning };
  appendAdminAudit("storage_item_deposited", { receiptId, playerId, actorId, inventoryId, template, qty, grade, itemIds, positions, durability, durabilityEvidence, durabilityVerification });
  return result;
}

function giveItemReceipt(receiptId) {
  const receipt = giveItemReceiptStore.get(String(receiptId || "").trim());
  if (!receipt) throw new Error("Give Item receipt was not found.");
  return receipt;
}

async function verifyGiveItemReceipt(receiptId) {
  const receipt = giveItemReceipt(receiptId);
  const inventoryId = String(receipt.inventory?.id || "");
  const template = String(receipt.item?.id || "");
  const grade = requireInteger(receipt.item?.grade ?? 0, "receipt grade", 0, 5);
  const itemIds = Array.isArray(receipt.item?.itemIds) ? receipt.item.itemIds.map(String) : [];
  const positions = Array.isArray(receipt.item?.positions) ? receipt.item.positions.map(String) : [];
  if (!/^\d+$/.test(inventoryId) || !itemIds.length || itemIds.some((value) => !/^\d+$/.test(value))) throw new Error("Give Item receipt contains invalid database identifiers.");
  const expectedValues = itemIds.map((itemId, index) => `(${itemId}::bigint,${/^\d+$/.test(positions[index] || "") ? positions[index] : "-1"}::bigint)`).join(",");
  const sql = `
    with expected(item_id,expected_position) as (values ${expectedValues}),
    observed as (
      select e.item_id,e.expected_position,i.inventory_id,i.stack_size,i.position_index,i.template_id,i.quality_level,i.stats
      from expected e left join dune.items i on i.id=e.item_id
    )
    select (select count(*)::text from expected),
           count(o.inventory_id)::text,
           count(*) filter(where o.inventory_id=${inventoryId} and o.template_id=${sqlString(template)}
                                  and o.quality_level=${grade} and o.position_index=o.expected_position)::text,
           coalesce(sum(o.stack_size) filter(where o.inventory_id=${inventoryId} and o.template_id=${sqlString(template)}),0)::text,
           count(*) filter(where o.inventory_id is not null and o.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}' is not null)::text,
           count(*) filter(where o.inventory_id is not null and jsonb_typeof(o.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}')='number')::text,
           count(*) filter(where o.inventory_id is not null and jsonb_typeof(o.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}')='number'
                                  and (o.stats #>> '${GIVE_ITEM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE})::text,
           count(*) filter(where o.inventory_id is not null and o.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}' is not null)::text,
           count(*) filter(where o.inventory_id is not null and jsonb_typeof(o.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')='number')::text,
           count(*) filter(where o.inventory_id is not null and jsonb_typeof(o.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')='number'
                                  and (o.stats #>> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE})::text,
           coalesce(jsonb_agg(jsonb_build_object('itemId',o.item_id::text,'inventoryId',coalesce(o.inventory_id::text,''),
             'stackSize',coalesce(o.stack_size,0),'position',o.position_index,'expectedPosition',o.expected_position,
             'template',coalesce(o.template_id,''),'grade',o.quality_level,
             'currentDurability',o.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}',
             'maximumDurability',o.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}') order by o.item_id),'[]'::jsonb)::text
      from observed o
  `;
  const row = parseDbRows(await dbQuery(sql, 15000), ["expectedStacks", "foundStacks", "matchingStacks", "foundQuantity", "durabilityPresentStacks", "numericDurabilityStacks", "exactDurabilityStacks", "maximumDurabilityPresentStacks", "numericMaximumDurabilityStacks", "exactMaximumDurabilityStacks", "rows"])[0] || {};
  let rows = [];
  try { rows = JSON.parse(row.rows || "[]"); } catch {}
  const observed = {
    expectedStacks: Number(row.expectedStacks || 0),
    foundStacks: Number(row.foundStacks || 0),
    matchingStacks: Number(row.matchingStacks || 0),
    foundQuantity: Number(row.foundQuantity || 0),
    durabilityPresentStacks: Number(row.durabilityPresentStacks || 0),
    numericDurabilityStacks: Number(row.numericDurabilityStacks || 0),
    exactDurabilityStacks: Number(row.exactDurabilityStacks || 0),
    maximumDurabilityPresentStacks: Number(row.maximumDurabilityPresentStacks || 0),
    numericMaximumDurabilityStacks: Number(row.numericMaximumDurabilityStacks || 0),
    exactMaximumDurabilityStacks: Number(row.exactMaximumDurabilityStacks || 0),
    rows
  };
  let classification;
  if (observed.foundStacks < observed.expectedStacks) classification = { ok: false, status: "runtime-overwrite", message: "One or more granted player-inventory rows disappeared after the verified transaction." };
  else if (observed.matchingStacks !== observed.expectedStacks || observed.foundQuantity !== Number(receipt.item?.quantity || 0)) classification = { ok: false, status: "read-back-mismatch", message: "The granted rows remain, but destination, template, grade, position, or quantity no longer matches the receipt." };
  else classification = classifyDurabilityReadBack(receipt.durability || receipt.item?.durability, observed);
  const checkedAt = new Date().toISOString();
  const check = { checkedAt, ...classification, ...observed };
  const updated = giveItemReceiptStore.update(receipt.receiptId, {
    status: classification.status,
    lastCheckedAt: checkedAt,
    checkCount: Number(receipt.checkCount || 0) + 1,
    checks: [...(Array.isArray(receipt.checks) ? receipt.checks : []), check].slice(-12),
    verification: observed
  });
  appendAdminAudit("give_item_receipt_rechecked", { receiptId: receipt.receiptId, status: classification.status, durability: receipt.durability || receipt.item?.durability, ...observed });
  return { ok: classification.ok, receipt: updated, verification: observed, message: classification.message };
}

function storageDepositReceipt(receiptId) {
  const receipt = storageDepositStore.get(String(receiptId || "").trim());
  if (!receipt) throw new Error("Storage deposit receipt was not found.");
  return receipt;
}

async function verifyStorageDepositReceipt(receiptId) {
  const receipt = storageDepositReceipt(receiptId);
  const inventoryId = String(receipt.storage?.inventoryId || "");
  const template = String(receipt.item?.id || "");
  const itemIds = Array.isArray(receipt.item?.itemIds) ? receipt.item.itemIds.map(String) : [];
  const positions = Array.isArray(receipt.item?.positions) ? receipt.item.positions.map(String) : [];
  if (!/^\d+$/.test(inventoryId) || !itemIds.length || itemIds.some((value) => !/^\d+$/.test(value))) throw new Error("Storage deposit receipt contains invalid database identifiers.");
  const expectedValues = itemIds.map((itemId, index) => `(${itemId}::bigint,${/^\d+$/.test(positions[index] || "") ? positions[index] : "-1"}::bigint)`).join(",");
  const sql = `
    with expected(item_id, expected_position) as (values ${expectedValues}),
    observed as (
      select e.item_id, e.expected_position, i.inventory_id, i.stack_size, i.position_index, i.template_id, i.stats
      from expected e left join dune.items i on i.id=e.item_id
    )
    select
      (select count(*)::text from expected),
      count(o.inventory_id)::text,
      count(*) filter (where o.inventory_id=${inventoryId} and o.template_id=${sqlString(template)} and o.position_index=o.expected_position})::text,
      coalesce(sum(o.stack_size) filter (where o.inventory_id=${inventoryId} and o.template_id=${sqlString(template)}),0)::text,
      (select count(*)::text from (
        select i.position_index from dune.items i
        where i.inventory_id=${inventoryId} and i.position_index is not null
        group by i.position_index having count(*)>1
      ) conflicts),
      (select count(*)::text from dune.items i cross join dune.inventories inv
        where inv.id=${inventoryId} and i.inventory_id=inv.id
          and (i.position_index<0 or (coalesce(inv.max_item_count,0)>0 and i.position_index>=inv.max_item_count))),
      count(*) filter(where o.inventory_id is not null and o.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}' is not null)::text,
      count(*) filter(where o.inventory_id is not null and jsonb_typeof(o.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}')='number')::text,
      count(*) filter(where o.inventory_id is not null and jsonb_typeof(o.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}')='number' and (o.stats #>> '${GIVE_ITEM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE})::text,
      count(*) filter(where o.inventory_id is not null and o.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}' is not null)::text,
      count(*) filter(where o.inventory_id is not null and jsonb_typeof(o.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')='number')::text,
      count(*) filter(where o.inventory_id is not null and jsonb_typeof(o.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')='number' and (o.stats #>> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}')::numeric=${GIVE_ITEM_DURABILITY_VALUE})::text,
      coalesce(jsonb_agg(jsonb_build_object(
        'itemId',o.item_id::text,'inventoryId',coalesce(o.inventory_id::text,''),'stackSize',coalesce(o.stack_size,0),
        'position',o.position_index,'expectedPosition',o.expected_position,'template',coalesce(o.template_id,''),
        'currentDurability',o.stats #> '${GIVE_ITEM_DURABILITY_SQL_PATH}',
        'maximumDurability',o.stats #> '${GIVE_ITEM_MAXIMUM_DURABILITY_SQL_PATH}'
      ) order by o.item_id),'[]'::jsonb)::text
    from observed o
  `;
  const row = parseDbRows(await dbQuery(sql, 15000), ["expectedStacks", "foundStacks", "matchingStacks", "foundQuantity", "duplicateSlots", "invalidPositions", "durabilityPresentStacks", "numericDurabilityStacks", "exactDurabilityStacks", "maximumDurabilityPresentStacks", "numericMaximumDurabilityStacks", "exactMaximumDurabilityStacks", "rows"])[0] || {};
  let observedRows = [];
  try { observedRows = JSON.parse(row.rows || "[]"); } catch {}
  const observed = {
    expectedStacks: Number(row.expectedStacks || 0),
    foundStacks: Number(row.foundStacks || 0),
    matchingStacks: Number(row.matchingStacks || 0),
    foundQuantity: Number(row.foundQuantity || 0),
    duplicateSlots: Number(row.duplicateSlots || 0),
    invalidPositions: Number(row.invalidPositions || 0),
    durabilityPresentStacks: Number(row.durabilityPresentStacks || 0),
    numericDurabilityStacks: Number(row.numericDurabilityStacks || 0),
    exactDurabilityStacks: Number(row.exactDurabilityStacks || 0),
    maximumDurabilityPresentStacks: Number(row.maximumDurabilityPresentStacks || 0),
    numericMaximumDurabilityStacks: Number(row.numericMaximumDurabilityStacks || 0),
    exactMaximumDurabilityStacks: Number(row.exactMaximumDurabilityStacks || 0),
    rows: observedRows
  };
  const storageClassification = classifyStorageVerification({ stackCount: receipt.item.stackCount, quantity: receipt.item.quantity }, observed);
  const durabilityClassification = classifyDurabilityReadBack(receipt.durability || receipt.item?.durability, observed);
  const classification = storageClassification.ok ? durabilityClassification : storageClassification;
  const checkedAt = new Date().toISOString();
  const check = { checkedAt, ...classification, ...observed };
  const checks = [...(Array.isArray(receipt.checks) ? receipt.checks : []), check].slice(-12);
  const updated = storageDepositStore.update(receipt.receiptId, {
    status: classification.status,
    visibility: receipt.confirmedVisible ? "confirmed" : "unknown",
    lastCheckedAt: checkedAt,
    checkCount: Number(receipt.checkCount || 0) + 1,
    checks,
    verification: observed
  });
  appendAdminAudit("storage_deposit_rechecked", { receiptId: receipt.receiptId, status: classification.status, durability: receipt.durability || receipt.item?.durability, durabilityVerification: durabilityClassification, ...observed });
  return { ok: classification.ok, receipt: updated, verification: observed, message: classification.message };
}

function confirmStorageDepositVisible(receiptId) {
  const receipt = storageDepositReceipt(receiptId);
  if (receipt.status !== "database-verified") throw new Error("Resolve the storage integrity warning before confirming in-game visibility.");
  const confirmedAt = new Date().toISOString();
  const updated = storageDepositStore.update(receipt.receiptId, { confirmedVisible: true, visibility: "confirmed", confirmedAt });
  appendAdminAudit("storage_deposit_visibility_confirmed", { receiptId: receipt.receiptId, confirmedAt });
  return { ok: true, receipt: updated, message: "Database integrity and in-game visibility are both confirmed." };
}

function readManagerConfigFallback() {
  const config = defaultManagerConfig();
  if (!fs.existsSync(MANAGER_CONFIG_PATH)) return config;
  try {
    const saved = JSON.parse(fs.readFileSync(MANAGER_CONFIG_PATH, "utf8"));
    if (saved && typeof saved === "object") {
      for (const key of Object.keys(config)) {
        if (Object.prototype.hasOwnProperty.call(saved, key)) config[key] = String(saved[key] || "").trim();
      }
    }
  } catch {}
  return config;
}

function writeManagerConfigFallback(payload) {
  const config = readManagerConfigFallback();
  for (const key of ["vmIp", "sshKeyPath", "sshUser", "battlegroup", "namespace", "source"]) {
    if (Object.prototype.hasOwnProperty.call(payload || {}, key)) config[key] = String(payload[key] || "").trim();
  }
  fs.mkdirSync(MANAGER_DATA_DIR, { recursive: true });
  fs.writeFileSync(MANAGER_CONFIG_PATH, JSON.stringify(config, null, 2), "utf8");
  return config;
}

function managerConnectionFromSuite(configValue = loadConfig()) {
  const selected = normalizeSelectedBattlegroup(configValue.selectedBattlegroup);
  const key = sshKeyStatus(configValue.sshKey || configValue.receiverSshKey || defaultSshKeyPath());
  const vmIp = String(configValue.sshHost || configValue.vmIp || configValue.receiverSshHost || "").trim();
  return {
    vmIp,
    sshKeyPath: key.path || "",
    sshUser: String(configValue.sshUser || configValue.receiverSshUser || "dune").trim(),
    battlegroup: selected?.name || "",
    namespace: selected?.namespace || "",
    source: "AlphaNine Dune Suite startup"
  };
}

function syncManagerConnectionFromSuite(configValue = loadConfig()) {
  const runtime = managerConnectionFromSuite(configValue);
  const saved = writeManagerConfigFallback(runtime);
  return {
    ...saved,
    ready: Boolean(saved.vmIp && saved.sshKeyPath && saved.battlegroup && saved.namespace),
    missing: [
      !saved.vmIp && "VM IP",
      !saved.sshKeyPath && "SSH key",
      !(saved.battlegroup && saved.namespace) && "battlegroup"
    ].filter(Boolean)
  };
}

function managerFallbackWarning() {
  return managerStartError || managerReadinessError || "Manager service is unavailable. The Python process has not become ready yet; check the startup diagnostics.";
}

async function handleManagerFallback(req, res, managerPath) {
  if (managerPath === "/api/server/config" && req.method === "GET") {
    await json(res, { config: readManagerConfigFallback(), configFile: MANAGER_CONFIG_PATH, warning: managerFallbackWarning(), spawnDiagnostics: managerSpawnDiagnostics });
    return true;
  }
  if (managerPath === "/api/server/config" && req.method === "POST") {
    try {
      const config = writeManagerConfigFallback(JSON.parse(await readBody(req) || "{}"));
      await json(res, { ok: true, config, configFile: MANAGER_CONFIG_PATH, warning: managerFallbackWarning(), spawnDiagnostics: managerSpawnDiagnostics });
    } catch {
      await json(res, { ok: false, error: "Invalid server setup payload" }, 400);
    }
    return true;
  }
  if (managerPath === "/api/server/discover" && req.method === "GET") {
    await json(res, managerErrorPayload(`Battlegroup discovery could not start the manager service. ${managerFallbackWarning()}`), 502);
    return true;
  }
  if (managerPath === "/api/server/settings" && req.method === "GET") {
    let payload = { profileName: "No applied profile", settings: {} };
    try {
      if (fs.existsSync(MANAGER_APPLIED_PROFILE_PATH)) payload = JSON.parse(fs.readFileSync(MANAGER_APPLIED_PROFILE_PATH, "utf8"));
    } catch {}
    await json(res, { ...payload, warning: managerFallbackWarning(), spawnDiagnostics: managerSpawnDiagnostics });
    return true;
  }
  if (managerPath === "/api/server/settings" && req.method === "POST") {
    try {
      const payload = JSON.parse(await readBody(req) || "{}");
      const flatSettings = {};
      for (const [sectionName, sectionSettings] of Object.entries(payload.settings || {})) {
        if (!sectionSettings || typeof sectionSettings !== "object" || Array.isArray(sectionSettings)) continue;
        for (const [key, value] of Object.entries(sectionSettings)) flatSettings[`${sectionName}.${key}`] = value;
      }
      fs.mkdirSync(MANAGER_DATA_DIR, { recursive: true });
      fs.writeFileSync(MANAGER_APPLIED_PROFILE_PATH, JSON.stringify(payload, null, 2), "utf8");
      fs.writeFileSync(MANAGER_APPLIED_SETTINGS_PATH, JSON.stringify(flatSettings, null, 2), "utf8");
      await json(res, {
        ok: true,
        message: "Settings saved locally. Install Python or set PYTHON_PATH to apply them to the server.",
        profileFile: MANAGER_APPLIED_PROFILE_PATH,
        settingsFile: MANAGER_APPLIED_SETTINGS_PATH,
        settingCount: Object.keys(flatSettings).length,
        warning: managerFallbackWarning(),
        spawnDiagnostics: managerSpawnDiagnostics
      });
    } catch {
      await json(res, { ok: false, error: "Invalid JSON payload" }, 400);
    }
    return true;
  }
  return false;
}

function safeFile(baseDir, requestPath) {
  const relative = decodeURIComponent(requestPath).replace(/^\/+/, "") || "index.html";
  const fullPath = path.join(baseDir, relative);
  const resolvedBase = path.resolve(baseDir);
  const resolvedFull = path.resolve(fullPath);
  if (!resolvedFull.startsWith(resolvedBase)) return null;
  return resolvedFull;
}

function send(res, status, type, body) {
  res.writeHead(status, { "Content-Type": `${type}; charset=utf-8`, "Cache-Control": "no-store" });
  res.end(body);
}

function blueprintDownloadName(value, fallback = "blueprint") {
  return String(value || fallback).replace(/[\x00-\x1f\x7f<>:"/\\|?*]/g, "_").trim().replace(/\.+$/g, "") || fallback;
}

async function readJsonRequest(req, maxBytes = 1024 * 1024 * 8) {
  const raw = await readBody(req, maxBytes);
  try { return JSON.parse(raw || "{}"); }
  catch { throw new Error("Invalid JSON payload."); }
}

async function json(res, body, status = 200) {
  send(res, status, "application/json", JSON.stringify(body));
}

function serveStatic(res, baseDir, requestPath) {
  const filePath = safeFile(baseDir, requestPath);
  if (!filePath || !fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) return false;
  const ext = path.extname(filePath).toLowerCase();
  const cacheControl = [".png", ".jpg", ".jpeg", ".webp", ".svg", ".ico", ".css", ".js", ".webmanifest"].includes(ext)
    ? "public, max-age=86400"
    : "no-store";
  res.writeHead(200, { "Content-Type": contentTypeFor(filePath), "Cache-Control": cacheControl });
  fs.createReadStream(filePath).pipe(res);
  return true;
}

function managerUnavailableHtml(reason) {
  const safeReason = String(reason || "Manager service not running").replace(/[&<>"']/g, (ch) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  }[ch]));
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Server Manager unavailable</title>
  <style>
    :root { color-scheme: dark; font-family: Inter, Segoe UI, Arial, sans-serif; background:#080a0d; color:#f6d98a; }
    body { margin:0; min-height:100vh; display:grid; place-items:center; background:linear-gradient(135deg,#080a0d,#17120a); }
    .panel { width:min(720px, calc(100vw - 48px)); border:1px solid rgba(214,166,69,.35); background:rgba(10,12,12,.88); padding:28px; box-shadow:0 18px 48px rgba(0,0,0,.45); }
    h1 { margin:0 0 12px; font-size:22px; letter-spacing:.08em; text-transform:uppercase; }
    .label { margin-top:18px; color:#bda764; font-size:11px; letter-spacing:.12em; text-transform:uppercase; }
    .reason { margin-top:8px; color:#f1e0ac; line-height:1.45; white-space:pre-wrap; overflow-wrap:anywhere; }
  </style>
</head>
<body>
  <main class="panel">
    <h1>Server Manager unavailable.</h1>
    <div class="label">Reason</div>
    <div class="reason">${safeReason}</div>
  </main>
</body>
</html>`;
}

function sendManagerUnavailable(res, reason, status = 503) {
  send(res, status, "text/html", managerUnavailableHtml(reason));
}

function startManagerService() {
  if (!SUITE_STARTUP_POLICY.allowManager) return false;
  if (managerProcess) return;
  if (managerStartError) return;
  const resolved = findPython();
  logPythonResolution(resolved);
  if (!resolved) {
    managerStartError = "Manager service failed to start: Python was not found. Set PYTHON_PATH in .env.local or install python/py.";
    console.warn(managerStartError);
    return;
  }
  spawnManagerProcess(resolved, isWindowsAppsAlias(resolved.command), isWindowsAppsAlias(resolved.command) ? "WindowsApps alias requires shell fallback" : "direct spawn");
  return true;
}

function spawnManagerProcess(resolved, useShell, reason) {
  const args = ["manager-server.py", "--no-open"];
  const details = managerSpawnDetails(resolved, args, useShell, reason);
  logManagerSpawnDetails(details);
  const spawnCommand = useShell ? `"${String(resolved.command).replace(/"/g, "")}"` : resolved.command;
  managerProcess = spawn(spawnCommand, args, {
    cwd: MANAGER_DIR,
    shell: useShell,
    windowsHide: true,
    stdio: ["ignore", "pipe", "pipe"]
  });
  let stdout = "";
  let stderr = "";
  const appendOutput = (current, chunk) => `${current}${String(chunk || "")}`.slice(-4000);
  managerProcess.stdout?.on("data", (chunk) => { stdout = appendOutput(stdout, chunk); });
  managerProcess.stderr?.on("data", (chunk) => { stderr = appendOutput(stderr, chunk); });
  managerProcess.on("error", (error) => {
    if (error.code === "ENOENT" && !useShell && isWindowsAppsAlias(resolved.command)) {
      managerSpawnDiagnostics = { ...managerSpawnDiagnostics, errorCode: error.code || "", errorMessage: error.message || String(error) };
      console.warn(`Manager service direct spawn failed with ENOENT for ${resolved.command}; retrying with shell:true.`);
      managerProcess = null;
      spawnManagerProcess(resolved, true, "direct spawn ENOENT; retrying with shell:true");
      return;
    }
    managerSpawnDiagnostics = { ...managerSpawnDiagnostics, errorCode: error.code || "", errorMessage: error.message || String(error) };
    managerStartError = `Manager service failed to start with ${resolved.command}: ${error.message}`;
    console.error(managerStartError);
    managerProcess = null;
  });
  managerProcess.on("exit", (code, signal) => {
    managerSpawnDiagnostics = {
      ...managerSpawnDiagnostics,
      exitCode: code,
      exitSignal: signal || "",
      stdout: stdout.trim(),
      stderr: stderr.trim()
    };
    if (code !== 0 && !managerStartError) {
      const detail = stderr.trim() || stdout.trim() || `exit code ${code}${signal ? ` (${signal})` : ""}`;
      managerStartError = `Manager service exited before becoming ready: ${detail}`;
      console.error(managerStartError);
    }
    managerProcess = null;
  });
}

async function waitForManagerReady(timeoutMs = Math.min(envNumber("ALPHANINE_MANAGER_START_TIMEOUT_MS", 20000), 60000)) {
  if (managerReadinessPromise) return managerReadinessPromise;
  managerReadinessPromise = (async () => {
    const startedAt = Date.now();
    const deadline = startedAt + timeoutMs;
    let lastError = "";
    while (Date.now() < deadline) {
      if (managerStartError) return false;
      try {
        const response = await fetch(`http://127.0.0.1:${MANAGER_PORT}/`, { signal: AbortSignal.timeout(1000) });
        if (response.ok) {
          const readyAfterMs = Date.now() - startedAt;
          if (managerReadinessError) console.log(`Manager service recovered after a previous readiness timeout; port ${MANAGER_PORT} is ready.`);
          managerReadinessError = "";
          managerSpawnDiagnostics = { ...managerSpawnDiagnostics, ready: true, readyAfterMs, readinessError: "" };
          return true;
        }
        lastError = `HTTP ${response.status}`;
      } catch (error) {
        lastError = error.message || String(error);
      }
      await new Promise((resolve) => setTimeout(resolve, 150));
    }
    if (!managerStartError) {
      managerReadinessError = `Manager service is still starting on port ${MANAGER_PORT} after ${timeoutMs}ms${lastError ? `: ${lastError}` : ". It will be checked again automatically."}`;
      managerSpawnDiagnostics = { ...managerSpawnDiagnostics, ready: false, readinessTimeoutMs: timeoutMs, readinessError: lastError };
      console.warn(managerReadinessError);
    }
    return false;
  })();
  try {
    return await managerReadinessPromise;
  } finally {
    managerReadinessPromise = null;
  }
}

async function proxyToManager(req, res, pathname) {
  if (startManagerService() === false) {
    await json(res, { ok: false, code: "startup_suppressed", error: "Server Manager is disabled by the centralized startup-suppression policy." }, 409);
    return;
  }
  const managerPath = pathname.replace(/^\/manager-api/, "");
  const suiteConnection = syncManagerConnectionFromSuite();
  if (managerPath === "/api/server/suite-connection" && req.method === "GET") {
    await json(res, { ok: suiteConnection.ready, config: suiteConnection });
    return;
  }
  if (!managerStartError) await waitForManagerReady();
  if (managerStartError && await handleManagerFallback(req, res, managerPath)) return;
  const target = `http://127.0.0.1:${MANAGER_PORT}${managerPath}`;
  const body = req.method === "GET" || req.method === "HEAD" ? undefined : await readBody(req);
  try {
    const response = await fetch(target, {
      method: req.method,
      headers: { "Content-Type": req.headers["content-type"] || "application/json" },
      body
    });
    const text = await response.text();
    res.writeHead(response.status, { "Content-Type": response.headers.get("content-type") || "application/json; charset=utf-8" });
    res.end(text);
  } catch (error) {
    if (await handleManagerFallback(req, res, managerPath)) return;
    await json(res, managerErrorPayload(managerStartError || managerReadinessError || `Manager service is not ready: ${error.message}`), 502);
  }
}

