function appConfirm(title,message,okText="Continue",cancelText="Cancel"){return new Promise(resolve=>{const dialog=document.getElementById("suiteConfirmDialog");const titleEl=document.getElementById("suiteConfirmTitle");const messageEl=document.getElementById("suiteConfirmMessage");const ok=document.getElementById("suiteConfirmOk");const cancel=document.getElementById("suiteConfirmCancel");if(!dialog||!ok||!cancel){resolve(false);return;}titleEl.textContent=title||"Confirm";messageEl.textContent=message||"";ok.textContent=okText||"Continue";const showCancel=cancelText!==null&&cancelText!==false;cancel.textContent=showCancel?cancelText:"";cancel.classList.toggle("hidden",!showCancel);const cleanup=result=>{dialog.classList.add("hidden");ok.onclick=null;cancel.onclick=null;cancel.classList.remove("hidden");document.removeEventListener("keydown",onKey,true);resolve(result);};const onKey=event=>{if(event.key==="Escape")cleanup(false);if(event.key==="Enter")cleanup(true);};ok.onclick=()=>cleanup(true);cancel.onclick=()=>cleanup(false);document.addEventListener("keydown",onKey,true);dialog.classList.remove("hidden");ok.focus();});}
async function appAlert(title,message,okText="OK"){await appConfirm(title,message,okText,null);}
let suiteToastTimer=null,suiteActionTimer=null;function setUxText(id,value){const el=document.getElementById(id);if(el)el.textContent=String(value||"");}
function normalizeActionKind(kind){const text=String(kind||"").toLowerCase();if(text==="error"||text==="bad"||text==="failed")return"error";if(text==="working"||text==="warn"||text==="pending")return"working";return"success";}
function setActionCenter(title,detail,kind="working"){const card=document.getElementById("suiteActionCard");if(!card)return;const normalized=normalizeActionKind(kind);const titleEl=document.getElementById("suiteActionTitle");const detailEl=document.getElementById("suiteActionDetail");if(titleEl)titleEl.textContent=String(title||"Action received");if(detailEl)detailEl.textContent=String(detail||"The Suite heard your click.");card.className="suite-action-card "+normalized;clearActionCenterSoon(4000);}
